M834 80h400000v40h-400000z&#34;/&gt;&lt;/svg&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.1828em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;top:-3.23em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;frac-line&#34; style=&#34;border-bottom-width:0.04em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;top:-3.677em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;Q&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.07153em;&#34;&gt;K&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.8413em;&#34;&gt;&lt;span style=&#34;top:-3.063em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34; style=&#34;margin-right:0.13889em;&#34;&gt;T&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.93em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mclose nulldelimiter&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;其中 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;S&lt;/mi&gt;&lt;mo&gt;∈&lt;/mo&gt;&lt;msup&gt;&lt;mi mathvariant=&#34;double-struck&#34;&gt;R&lt;/mi&gt;&lt;mrow&gt;&lt;mi&gt;n&lt;/mi&gt;&lt;mo&gt;×&lt;/mo&gt;&lt;mi&gt;n&lt;/mi&gt;&lt;/mrow&gt;&lt;/msup&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;S \in \mathbb{R}^{n \times n}&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.7224em;vertical-align:-0.0391em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.05764em;&#34;&gt;S&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;∈&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.7713em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathbb&#34;&gt;R&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.7713em;&#34;&gt;&lt;span style=&#34;top:-3.063em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;n&lt;/span&gt;&lt;span class=&#34;mbin mtight&#34;&gt;×&lt;/span&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;n&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;，&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;S&lt;/mi&gt;&lt;mo stretchy=&#34;false&#34;&gt;[&lt;/mo&gt;&lt;mi&gt;i&lt;/mi&gt;&lt;mo separator=&#34;true&#34;&gt;,&lt;/mo&gt;&lt;mi&gt;j&lt;/mi&gt;&lt;mo stretchy=&#34;false&#34;&gt;]&lt;/mo&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;S[i,j]&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1em;vertical-align:-0.25em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.05764em;&#34;&gt;S&lt;/span&gt;&lt;span class=&#34;mopen&#34;&gt;[&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;i&lt;/span&gt;&lt;span class=&#34;mpunct&#34;&gt;,&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.1667em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.05724em;&#34;&gt;j&lt;/span&gt;&lt;span class=&#34;mclose&#34;&gt;]&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 表示第 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;i&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;i&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6595em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;i&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 个位置对第 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;j&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;j&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.854em;vertical-align:-0.1944em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.05724em;&#34;&gt;j&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 个位置的相关性。当 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;j&lt;/mi&gt;&lt;mo&gt;&amp;gt;&lt;/mo&gt;&lt;mi&gt;i&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;j &amp;gt; i&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.854em;vertical-align:-0.1944em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.05724em;&#34;&gt;j&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;&amp;gt;&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6595em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;i&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 时，对应未来信息，需要被屏蔽。&lt;/p&gt;
&lt;p&gt;为此，引入掩码矩阵 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;M&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;M&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.10903em;&#34;&gt;M&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;：&lt;/p&gt;
&lt;p&gt;&lt;span class=&#34;katex-display&#34;&gt;&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34; display=&#34;block&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;M&lt;/mi&gt;&lt;mo stretchy=&#34;false&#34;&gt;[&lt;/mo&gt;&lt;mi&gt;i&lt;/mi&gt;&lt;mo separator=&#34;true&#34;&gt;,&lt;/mo&gt;&lt;mi&gt;j&lt;/mi&gt;&lt;mo stretchy=&#34;false&#34;&gt;]&lt;/mo&gt;&lt;mo&gt;=&lt;/mo&gt;&lt;mrow&gt;&lt;mo fence=&#34;true&#34;&gt;{&lt;/mo&gt;&lt;mtable rowspacing=&#34;0.36em&#34; columnalign=&#34;left left&#34; columnspacing=&#34;1em&#34;&gt;&lt;mtr&gt;&lt;mtd&gt;&lt;mstyle scriptlevel=&#34;0&#34; displaystyle=&#34;false&#34;&gt;&lt;mrow&gt;&lt;mn&gt;0&lt;/mn&gt;&lt;mo separator=&#34;true&#34;&gt;,&lt;/mo&gt;&lt;/mrow&gt;&lt;/mstyle&gt;&lt;/mtd&gt;&lt;mtd&gt;&lt;mstyle scriptlevel=&#34;0&#34; displaystyle=&#34;false&#34;&gt;&lt;mrow&gt;&lt;mi&gt;j&lt;/mi&gt;&lt;mo&gt;≤&lt;/mo&gt;&lt;mi&gt;i&lt;/mi&gt;&lt;/mrow&gt;&lt;/mstyle&gt;&lt;/mtd&gt;&lt;/mtr&gt;&lt;mtr&gt;&lt;mtd&gt;&lt;mstyle scriptlevel=&#34;0&#34; displaystyle=&#34;false&#34;&gt;&lt;mrow&gt;&lt;mo&gt;−&lt;/mo&gt;&lt;mi mathvariant=&#34;normal&#34;&gt;∞&lt;/mi&gt;&lt;mo separator=&#34;true&#34;&gt;,&lt;/mo&gt;&lt;/mrow&gt;&lt;/mstyle&gt;&lt;/mtd&gt;&lt;mtd&gt;&lt;mstyle scriptlevel=&#34;0&#34; displaystyle=&#34;false&#34;&gt;&lt;mrow&gt;&lt;mi&gt;j&lt;/mi&gt;&lt;mo&gt;&amp;gt;&lt;/mo&gt;&lt;mi&gt;i&lt;/mi&gt;&lt;/mrow&gt;&lt;/mstyle&gt;&lt;/mtd&gt;&lt;/mtr&gt;&lt;/mtable&gt;&lt;/mrow&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;M[i,j] =
\begin{cases}
0, &amp;amp; j \le i \\
-\infty, &amp;amp; j &amp;gt; i
\end{cases}
&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1em;vertical-align:-0.25em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.10903em;&#34;&gt;M&lt;/span&gt;&lt;span class=&#34;mopen&#34;&gt;[&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;i&lt;/span&gt;&lt;span class=&#34;mpunct&#34;&gt;,&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.1667em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.05724em;&#34;&gt;j&lt;/span&gt;&lt;span class=&#34;mclose&#34;&gt;]&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:3em;vertical-align:-1.25em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;minner&#34;&gt;&lt;span class=&#34;mopen delimcenter&#34; style=&#34;top:0em;&#34;&gt;&lt;span class=&#34;delimsizing size4&#34;&gt;{&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mtable&#34;&gt;&lt;span class=&#34;col-align-l&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:1.69em;&#34;&gt;&lt;span style=&#34;top:-3.69em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3.008em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord&#34;&gt;0&lt;/span&gt;&lt;span class=&#34;mpunct&#34;&gt;,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;top:-2.25em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3.008em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord&#34;&gt;−&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;∞&lt;/span&gt;&lt;span class=&#34;mpunct&#34;&gt;,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:1.19em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;arraycolsep&#34; style=&#34;width:1em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;col-align-l&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:1.69em;&#34;&gt;&lt;span style=&#34;top:-3.69em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3.008em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.05724em;&#34;&gt;j&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;≤&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;i&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;top:-2.25em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3.008em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.05724em;&#34;&gt;j&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;&amp;gt;&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;i&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:1.19em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mclose nulldelimiter&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;将掩码加到注意力分数上：&lt;/p&gt;
&lt;p&gt;&lt;span class=&#34;katex-display&#34;&gt;&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34; display=&#34;block&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;msub&gt;&lt;mi&gt;S&lt;/mi&gt;&lt;mtext&gt;masked&lt;/mtext&gt;&lt;/msub&gt;&lt;mo&gt;=&lt;/mo&gt;&lt;mi&gt;S&lt;/mi&gt;&lt;mo&gt;+&lt;/mo&gt;&lt;mi&gt;M&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;S_{\text{masked}} = S + M
&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.8333em;vertical-align:-0.15em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.05764em;&#34;&gt;S&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.3361em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;&lt;span class=&#34;mord text mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;masked&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.7667em;vertical-align:-0.0833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.05764em;&#34;&gt;S&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mbin&#34;&gt;+&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.10903em;&#34;&gt;M&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;随后应用 softmax：&lt;/p&gt;
&lt;p&gt;&lt;span class=&#34;katex-display&#34;&gt;&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34; display=&#34;block&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;A&lt;/mi&gt;&lt;mo&gt;=&lt;/mo&gt;&lt;mtext&gt;softmax&lt;/mtext&gt;&lt;mo stretchy=&#34;false&#34;&gt;(&lt;/mo&gt;&lt;msub&gt;&lt;mi&gt;S&lt;/mi&gt;&lt;mtext&gt;masked&lt;/mtext&gt;&lt;/msub&gt;&lt;mo stretchy=&#34;false&#34;&gt;)&lt;/mo&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;A = \text{softmax}(S_{\text{masked}})
&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;A&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1em;vertical-align:-0.25em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord text&#34;&gt;&lt;span class=&#34;mord&#34;&gt;softmax&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mopen&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.05764em;&#34;&gt;S&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.3361em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;&lt;span class=&#34;mord text mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;masked&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mclose&#34;&gt;)&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;由于 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;exp&lt;/mi&gt;&lt;mo&gt;⁡&lt;/mo&gt;&lt;mo stretchy=&#34;false&#34;&gt;(&lt;/mo&gt;&lt;mo&gt;−&lt;/mo&gt;&lt;mi mathvariant=&#34;normal&#34;&gt;∞&lt;/mi&gt;&lt;mo stretchy=&#34;false&#34;&gt;)&lt;/mo&gt;&lt;mo&gt;=&lt;/mo&gt;&lt;mn&gt;0&lt;/mn&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;\exp(-\infty) = 0&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1em;vertical-align:-0.25em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mop&#34;&gt;exp&lt;/span&gt;&lt;span class=&#34;mopen&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;−&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;∞&lt;/span&gt;&lt;span class=&#34;mclose&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6444em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;0&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;，因此被屏蔽的位置（&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;j&lt;/mi&gt;&lt;mo&gt;&amp;gt;&lt;/mo&gt;&lt;mi&gt;i&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;j &amp;gt; i&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.854em;vertical-align:-0.1944em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.05724em;&#34;&gt;j&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;&amp;gt;&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6595em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;i&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;）在归一化后对应的权重为 0，而允许的位置（&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;j&lt;/mi&gt;&lt;mo&gt;≤&lt;/mo&gt;&lt;mi&gt;i&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;j \le i&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.854em;vertical-align:-0.1944em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.05724em;&#34;&gt;j&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;≤&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6595em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;i&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;）仍然按照原始分数参与归一化。&lt;/p&gt;
&lt;p&gt;最后计算输出：&lt;/p&gt;
&lt;p&gt;&lt;span class=&#34;katex-display&#34;&gt;&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34; display=&#34;block&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mtext&gt;Output&lt;/mtext&gt;&lt;mo&gt;=&lt;/mo&gt;&lt;mi&gt;A&lt;/mi&gt;&lt;mi&gt;V&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;\text{Output} = A V
&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.8778em;vertical-align:-0.1944em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord text&#34;&gt;&lt;span class=&#34;mord&#34;&gt;Output&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;A&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.22222em;&#34;&gt;V&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;由于被屏蔽位置的权重为 0，在计算第 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;i&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;i&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6595em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;i&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 个位置的输出时，仅会对 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;j&lt;/mi&gt;&lt;mo&gt;≤&lt;/mo&gt;&lt;mi&gt;i&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;j \le i&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.854em;vertical-align:-0.1944em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.05724em;&#34;&gt;j&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;≤&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6595em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;i&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 的位置进行加权求和，从而实现只依赖历史信息的自回归建模。&lt;/p&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-text&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span&gt;注意力分数矩阵 S (计算后)：&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;[[ s11, s12, s13, s14],&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt; [ s21, s22, s23, s24],&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt; [ s31, s32, s33, s34],&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt; [ s41, s42, s43, s44]]&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt; &lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;掩码矩阵 M (下三角为0，上三角为-inf)：&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;[[ 0, -inf, -inf, -inf],&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt; [ 0,    0, -inf, -inf],&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt; [ 0,    0,    0, -inf],&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt; [ 0,    0,    0,    0]]&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt; &lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;掩码后的分数 S_masked = S + M：&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;[[ s11, -inf, -inf, -inf],   -&gt; 位置1只能看到位置1&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt; [ s21,  s22, -inf, -inf],   -&gt; 位置2只能看到位置1、2&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt; [ s31,  s32,  s33, -inf],   -&gt; 位置3只能看到位置1、2、3&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt; [ s41,  s42,  s43,  s44]]   -&gt; 位置4可以看到所有位置1、2、3、4&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt; &lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;应用 Softmax(S_masked) 得到注意力权重矩阵 A：&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;[[ a11,   0,   0,   0],   -&gt; a11 = exp(s11)/exp(s11) = 1&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt; [ a21, a22,   0,   0],   -&gt; a21 = exp(s21)/(exp(s21)+exp(s22)), a22 = exp(s22)/(exp(s21)+exp(s22))&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt; [ a31, a32, a33,   0],&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt; [ a41, a42, a43, a44]]&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt; &lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;计算输出：每一行只对非零权重对应的 Value 进行加权求和。&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;h5 id=&#34;cross-attention&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#cross-attention&#34;&gt;#&lt;/a&gt; Cross-Attention&lt;/h5&gt;
&lt;blockquote&gt;
&lt;p&gt;对于我之前的疑惑：&lt;/p&gt;
&lt;p&gt;Multi-Head Attention 是一个通用模块。它是否是 Cross-Attention，不取决于类名，而取决于传入的 Q、K、V 来自哪里。&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;如果 Q = K = V = 解码器自己的输入 → Self-Attention&lt;/li&gt;
&lt;li&gt;如果 Q = 解码器，K = V = 编码器输出 → Cross-Attention&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;所以：&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;同一个 MultiHeadAttention 类，传不同的 Q/K/V，就变成不同类型的注意力。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;/blockquote&gt;
&lt;p&gt;&lt;strong&gt;位置&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;在 Transformer 解码器的每一层中：&lt;/p&gt;
&lt;p&gt;[&lt;br /&gt;
\text{Masked Multi-Head Self-Attention} \rightarrow \text{Add &amp;amp; Norm} \rightarrow \text{Cross-Attention} \rightarrow \text{FFN}&lt;br /&gt;
]&lt;/p&gt;
&lt;p&gt;即 Cross-Attention 是第二个 Multi-Head Attention。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;核心目的&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Cross-Attention 的作用是：在生成目标序列的当前词时，让解码器有选择地关注编码器输出的整个源序列表示。&lt;/p&gt;
&lt;p&gt;这是 Seq2Seq 任务（如机器翻译、文本摘要等）的核心机制。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;直观理解&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;想象你在翻译一句话。当你在写目标语言的某个词时，你需要参考源语言句子的哪些部分提供了最相关的信息？Cross-Attention 就是让解码器模型自动学习这种“软对齐”（Soft Alignment）的过程。它动态地为每个目标词位置计算一个权重分布，这个分布告诉模型源序列的哪些词或短语对生成当前目标词最重要。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;输入来源&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Cross-Attention 接收两部分输入：&lt;/p&gt;
&lt;p&gt;(1) Query（Q）：来自解码器&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;来源：&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;[&lt;br /&gt;
Q = \text{Decoder Output (after Multi-Head Self-Attention + Add &amp;amp; Norm)}&lt;br /&gt;
]&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;含义：表示当前解码状态（包含已生成信息 + 当前预测位置）&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;形状：&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;[&lt;br /&gt;
Q \in \mathbb&lt;ruby&gt;R}&lt;rp&gt;(&lt;/rp&gt;&lt;rt&gt;{B \times T_{\text{target&lt;/rt&gt;&lt;rp&gt;)&lt;/rp&gt;&lt;/ruby&gt;} \times d_{\text{model}}}&lt;br /&gt;
]&lt;/p&gt;
&lt;p&gt;(2) Key（K）与 Value（V）：来自编码器&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;来源：&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;[&lt;br /&gt;
K, V = \text{Encoder Output (final layer)}&lt;br /&gt;
]&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;含义：&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;表示编码器对整个源序列的理解&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;形状：&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;[&lt;br /&gt;
K, V \in \mathbb&lt;ruby&gt;R}&lt;rp&gt;(&lt;/rp&gt;&lt;rt&gt;{B \times T_{\text{source&lt;/rt&gt;&lt;rp&gt;)&lt;/rp&gt;&lt;/ruby&gt;} \times d_{\text{model}}}&lt;br /&gt;
]&lt;/p&gt;
&lt;p&gt;&amp;lt;img src=&amp;quot;&lt;a href=&#34;https://i-blog.csdnimg.cn/direct/26c56c9e2eb543aab72c4debbbada8b8.png&#34;&gt;https://i-blog.csdnimg.cn/direct/26c56c9e2eb543aab72c4debbbada8b8.png&lt;/a&gt;&amp;quot; alt=&amp;quot;img&amp;quot; style=&amp;quot;zoom: 67%;&amp;quot; /&amp;gt;&lt;/p&gt;
&lt;p&gt;在标准 Transformer 中：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;编码器输出 &lt;strong&gt;同时作为 K 和 V&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;但会经过不同的线性变换：&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;[&lt;br /&gt;
K = X W^K,\quad V = X W^V&lt;br /&gt;
]&lt;/p&gt;
&lt;p&gt;Cross-Attention 同样使用 Scaled Dot-Product Attention：&lt;/p&gt;
&lt;h1 id=&#34;textattentionq-k-v&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#textattentionq-k-v&#34;&gt;#&lt;/a&gt; [&lt;br /&gt;
\text{Attention}(Q, K, V)&lt;/h1&gt;
&lt;p&gt;\text&lt;ruby&gt;softmax}\left(
\frac{QK&lt;rp&gt;(&lt;/rp&gt;&lt;rt&gt;\top&lt;/rt&gt;&lt;rp&gt;)&lt;/rp&gt;&lt;/ruby&gt;{\sqrt{d_k}}&lt;br /&gt;
\right)V&lt;br /&gt;
]&lt;/p&gt;
&lt;p&gt;同样，然后再次传递给前馈神经网络，然后 Add &amp;amp; Norm 后传回来（也是有好几层这样的）或者传入 softmax&lt;/p&gt;
&lt;h2 id=&#34;lecture-7&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#lecture-7&#34;&gt;#&lt;/a&gt; lecture 7&lt;/h2&gt;
&lt;h3 id=&#34;mlp-mixer&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#mlp-mixer&#34;&gt;#&lt;/a&gt; MLP-Mixer&lt;/h3&gt;
&lt;blockquote&gt;
&lt;p&gt;不用卷积（CNN）也不用注意力（Transformer），只用全连接（MLP）来做图像分类&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;&amp;lt;img src=&amp;quot;/assets/图片/image-20260414102849222.png&amp;quot; alt=&amp;quot;image-20260414102849222&amp;quot; style=&amp;quot;zoom:50%;&amp;quot; /&amp;gt;&lt;/p&gt;
&lt;p&gt;图片 → 切 patch → 多层 Mixer → 池化 → 分类&lt;/p&gt;
&lt;h3 id=&#34;mamba&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#mamba&#34;&gt;#&lt;/a&gt; Mamba&lt;/h3&gt;
&lt;p&gt;&lt;strong&gt;Mamba = 一种基于状态空间模型（SSM）的序列建模方法&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;用来替代 Transformer 的 Attention&lt;/li&gt;
&lt;li&gt;目标：&lt;strong&gt;高效处理长序列（O(n)复杂度）&lt;/strong&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;状态建模（像 RNN 但更强）&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span class=&#34;katex-display&#34;&gt;&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34; display=&#34;block&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;msub&gt;&lt;mi&gt;h&lt;/mi&gt;&lt;mi&gt;t&lt;/mi&gt;&lt;/msub&gt;&lt;mo&gt;=&lt;/mo&gt;&lt;mi&gt;A&lt;/mi&gt;&lt;msub&gt;&lt;mi&gt;h&lt;/mi&gt;&lt;mrow&gt;&lt;mi&gt;t&lt;/mi&gt;&lt;mo&gt;−&lt;/mo&gt;&lt;mn&gt;1&lt;/mn&gt;&lt;/mrow&gt;&lt;/msub&gt;&lt;mo&gt;+&lt;/mo&gt;&lt;mi&gt;B&lt;/mi&gt;&lt;msub&gt;&lt;mi&gt;x&lt;/mi&gt;&lt;mi&gt;t&lt;/mi&gt;&lt;/msub&gt;&lt;mo separator=&#34;true&#34;&gt;,&lt;/mo&gt;&lt;mspace width=&#34;1em&#34;/&gt;&lt;msub&gt;&lt;mi&gt;y&lt;/mi&gt;&lt;mi&gt;t&lt;/mi&gt;&lt;/msub&gt;&lt;mo&gt;=&lt;/mo&gt;&lt;mi&gt;C&lt;/mi&gt;&lt;msub&gt;&lt;mi&gt;h&lt;/mi&gt;&lt;mi&gt;t&lt;/mi&gt;&lt;/msub&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;h_t = A h_{t-1} + B x_t,\quad y_t = C h_t
&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.8444em;vertical-align:-0.15em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;h&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.2806em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:0em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;t&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.9028em;vertical-align:-0.2083em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;A&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;h&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.3011em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:0em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;t&lt;/span&gt;&lt;span class=&#34;mbin mtight&#34;&gt;−&lt;/span&gt;&lt;span class=&#34;mord mtight&#34;&gt;1&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.2083em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mbin&#34;&gt;+&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.8778em;vertical-align:-0.1944em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.05017em;&#34;&gt;B&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;x&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.2806em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:0em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;t&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mpunct&#34;&gt;,&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:1em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.1667em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.03588em;&#34;&gt;y&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.2806em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;t&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.8444em;vertical-align:-0.15em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.07153em;&#34;&gt;C&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;h&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.2806em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:0em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;t&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;用“状态 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mo stretchy=&#34;false&#34;&gt;(&lt;/mo&gt;&lt;msub&gt;&lt;mi&gt;h&lt;/mi&gt;&lt;mi&gt;t&lt;/mi&gt;&lt;/msub&gt;&lt;mo stretchy=&#34;false&#34;&gt;)&lt;/mo&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;(h_t)&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1em;vertical-align:-0.25em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mopen&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;h&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.2806em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:0em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;t&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mclose&#34;&gt;)&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;”来记忆历史信息&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;选择性机制&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;参数变成输入相关：&lt;/p&gt;
&lt;p&gt;&lt;span class=&#34;katex-display&#34;&gt;&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34; display=&#34;block&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;A&lt;/mi&gt;&lt;mo stretchy=&#34;false&#34;&gt;(&lt;/mo&gt;&lt;msub&gt;&lt;mi&gt;x&lt;/mi&gt;&lt;mi&gt;t&lt;/mi&gt;&lt;/msub&gt;&lt;mo stretchy=&#34;false&#34;&gt;)&lt;/mo&gt;&lt;mo separator=&#34;true&#34;&gt;,&lt;/mo&gt;&lt;mtext&gt; &lt;/mtext&gt;&lt;mi&gt;B&lt;/mi&gt;&lt;mo stretchy=&#34;false&#34;&gt;(&lt;/mo&gt;&lt;msub&gt;&lt;mi&gt;x&lt;/mi&gt;&lt;mi&gt;t&lt;/mi&gt;&lt;/msub&gt;&lt;mo stretchy=&#34;false&#34;&gt;)&lt;/mo&gt;&lt;mo separator=&#34;true&#34;&gt;,&lt;/mo&gt;&lt;mtext&gt; &lt;/mtext&gt;&lt;mi&gt;C&lt;/mi&gt;&lt;mo stretchy=&#34;false&#34;&gt;(&lt;/mo&gt;&lt;msub&gt;&lt;mi&gt;x&lt;/mi&gt;&lt;mi&gt;t&lt;/mi&gt;&lt;/msub&gt;&lt;mo stretchy=&#34;false&#34;&gt;)&lt;/mo&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;A(x_t),\ B(x_t),\ C(x_t)
&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1em;vertical-align:-0.25em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;A&lt;/span&gt;&lt;span class=&#34;mopen&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;x&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.2806em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:0em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;t&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mclose&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;mpunct&#34;&gt;,&lt;/span&gt;&lt;span class=&#34;mspace&#34;&gt; &lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.1667em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.05017em;&#34;&gt;B&lt;/span&gt;&lt;span class=&#34;mopen&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;x&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.2806em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:0em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;t&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mclose&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;mpunct&#34;&gt;,&lt;/span&gt;&lt;span class=&#34;mspace&#34;&gt; &lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.1667em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.07153em;&#34;&gt;C&lt;/span&gt;&lt;span class=&#34;mopen&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;x&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.2806em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:0em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;t&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mclose&#34;&gt;)&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;每个 token 动态调整&lt;br /&gt;
类似 attention 的“选择性关注”&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;高效计算&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;使用 &lt;strong&gt;scan（并行前缀计算）&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;时间复杂度：&lt;strong&gt;O(n)&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;可 GPU 并行&lt;/li&gt;
&lt;li&gt;比 Attention 更省资源&lt;/li&gt;
&lt;/ul&gt;
&lt;h4 id=&#34;结构block&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#结构block&#34;&gt;#&lt;/a&gt; 结构（Block）&lt;/h4&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-text&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span&gt;Input&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt; ↓&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;Linear Projection&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt; ↓&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;Selective SSM（核心）&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt; ↓&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;Gating / 非线性&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt; ↓&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;Output&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;h4 id=&#34;和-transformer-对比&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#和-transformer-对比&#34;&gt;#&lt;/a&gt; 和 Transformer 对比&lt;/h4&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;方面&lt;/th&gt;
&lt;th&gt;Transformer&lt;/th&gt;
&lt;th&gt;Mamba&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;核心&lt;/td&gt;
&lt;td&gt;Attention&lt;/td&gt;
&lt;td&gt;SSM&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;复杂度&lt;/td&gt;
&lt;td&gt;O(n²)&lt;/td&gt;
&lt;td&gt;O(n)&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;长序列&lt;/td&gt;
&lt;td&gt;弱&lt;/td&gt;
&lt;td&gt;强&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;记忆方式&lt;/td&gt;
&lt;td&gt;显式（对齐）&lt;/td&gt;
&lt;td&gt;隐式（状态）&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;h3 id=&#34;预训练&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#预训练&#34;&gt;#&lt;/a&gt; 预训练&lt;/h3&gt;
&lt;p&gt;预训练（Pre-training）本质上是：&lt;strong&gt;先在大规模通用数据上训练一个模型，让它学到“通用能力”，再拿去做具体任务&lt;/strong&gt;。&lt;/p&gt;
&lt;p&gt;直觉上可以理解为：不是让模型一开始就学“某个任务”，而是先让它“变聪明”。&lt;/p&gt;
&lt;hr /&gt;
&lt;p&gt;从过程上看，预训练通常分两步：第一步是&lt;strong&gt;通用训练（预训练阶段）&lt;/strong&gt;&lt;br /&gt;
模型在海量数据上学习，比如：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;文本 → 学语言规律（语法、常识、逻辑）&lt;/li&gt;
&lt;li&gt;图像 → 学边缘、纹理、结构&lt;/li&gt;
&lt;li&gt;多模态 → 学图文对应关系&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;例如大语言模型常用的是：预测下一个词（next token prediction）&lt;/p&gt;
&lt;p&gt;本质是让模型学会：“在当前上下文下，什么是合理的内容”&lt;/p&gt;
&lt;hr /&gt;
&lt;p&gt;第二步是&lt;strong&gt;任务适配（微调 / 使用阶段）&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;有两种常见方式：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Fine-tuning（微调）&lt;/strong&gt;：在小数据上再训练，让模型适应任务&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Prompt / In-context&lt;/strong&gt;：不改模型，直接通过输入引导它完成任务&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;最经典的预训练其实就是我们的词向量。预训练的第一步是：把词变成向量（embedding），本质就是一个训练好的查表过程。&lt;/p&gt;
&lt;h3 id=&#34;bert&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#bert&#34;&gt;#&lt;/a&gt; BERT&lt;/h3&gt;
&lt;blockquote&gt;
&lt;p&gt;BERT是一个自然语言理解模型（NLU）&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h4 id=&#34;bert-2&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#bert-2&#34;&gt;#&lt;/a&gt; BERT&lt;/h4&gt;
&lt;p&gt;&lt;strong&gt;BERT&lt;/strong&gt; 的全称是 &lt;strong&gt;B&lt;/strong&gt;idirectional &lt;strong&gt;E&lt;/strong&gt;ncoder &lt;strong&gt;R&lt;/strong&gt;epresentations from &lt;strong&gt;T&lt;/strong&gt;ransformers。&lt;br /&gt;
它是 Google 在 2018 年提出的一种自然语言处理（NLP）模型。它的出现可以说是 NLP 领域的“原子弹”，打破了当时几乎所有的各项纪录。&lt;/p&gt;
&lt;p&gt;我们可以把它的名字拆解：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;T (Transformers):&lt;/strong&gt; 它的底层身体结构是 Transformer，准确地说，它只用了 Transformer 架构中的 &lt;strong&gt;Encoder（编码器）&lt;/strong&gt; 部分。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;ER (Encoder Representations):&lt;/strong&gt; 它的主要工作不是像 ChatGPT 那样“聊天/生成文字”，而是去**“深刻理解”&lt;strong&gt;一句话的含义，并把它转化成计算机能懂的高级特征向量（Representations）。可以理解成一个极其优秀的&lt;/strong&gt;“文本阅读理解专家”**。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;B (Bidirectional - 双向的):&lt;/strong&gt; 这是 BERT 最牛、最核心的特点。
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;以前的模型（单向）：&lt;/strong&gt; 只能从左读到右。比如读“苹果”这个词，它只能看到前面的词。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;BERT（双向）：&lt;/strong&gt; 它是一眼看全一句话，**同时结合上下文（左边和右边）**来理解当前的词。&lt;/li&gt;
&lt;li&gt;&lt;em&gt;举个例子：&lt;/em&gt; “我昨天买了一个&lt;strong&gt;苹果&lt;/strong&gt;手机” 和 “我昨天吃了一个&lt;strong&gt;苹果&lt;/strong&gt;”。&lt;/li&gt;
&lt;li&gt;如果是单向阅读，读到“苹果”时，前面都是“我昨天...了一个”，模型根本不知道“苹果”是水果还是手机。但 BERT 能同时看到后面的“手机”或“句号”，瞬间就能精准区分这两个“苹果”的含义。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h4 id=&#34;mlm&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#mlm&#34;&gt;#&lt;/a&gt; MLM&lt;/h4&gt;
&lt;p&gt;&lt;strong&gt;MLM&lt;/strong&gt; 的全称是 &lt;strong&gt;M&lt;/strong&gt;asked &lt;strong&gt;L&lt;/strong&gt;anguage &lt;strong&gt;M&lt;/strong&gt;odeling，中文叫 &lt;strong&gt;掩蔽语言模型&lt;/strong&gt;。&lt;br /&gt;
它不是一个独立的模型，而是 &lt;strong&gt;专门为了训练 BERT 发明的一种“学习方法”或“考试题型”&lt;/strong&gt;。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;为什么需要 MLM&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;以前训练语言模型（比如 GPT 的祖先），都是用“接龙”的方法：给定前几个词，让模型猜下一个词。&lt;br /&gt;
但是，BERT 是“双向”的，它能一眼看到整句话。如果还让它猜下一个词，这就好比你让学生做填空题，却把带答案的完整试卷直接发给他，他直接“抄答案”（通过网络结构直接看到后面的词）就行了，什么都学不到。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;MLM 是怎么做的&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;为了不让 BERT 抄答案，又能逼迫它利用双向信息学习，Google 的科学家想出了一个极其简单又绝妙的方法：&lt;strong&gt;做完形填空&lt;/strong&gt;。&lt;/p&gt;
&lt;p&gt;这就是你在上一张图里看到的：在把一句话输入给 BERT 之前，&lt;strong&gt;人为地随机抠掉（Mask）句子中 15% 的词&lt;/strong&gt;。&lt;br /&gt;
然后对 BERT 说：“我不限制你怎么看上下文，但现在卷子上有几个洞，你根据剩下的词，把这些洞里的词给我猜出来！”&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;em&gt;比如原句：&lt;/em&gt; &lt;code&gt;今天 天气 真好，我们 去 爬山 吧。&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;em&gt;MLM 破坏后：&lt;/em&gt; &lt;code&gt;今天 [MASK] 真好，我们 [MASK] 爬山 吧。&lt;/code&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;BERT 为了猜出第一个 &lt;code&gt;[MASK]&lt;/code&gt; 是“天气”，它不仅要看左边的“今天”，还要看右边的“真好”，这就强迫它必须&lt;strong&gt;同时理解左右两边的上下文&lt;/strong&gt;。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;MLM 的处理小细节&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;为了防止 BERT 在实际应用时犯傻（因为实际生活中没人在句子里加 &lt;code&gt;[MASK]&lt;/code&gt;），这 15% 挑出来的词会做三种处理：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;80% 抠掉：&lt;/strong&gt; 换成 &lt;code&gt;[MASK]&lt;/code&gt;（完形填空）。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;10% 乱填：&lt;/strong&gt; 换成随机的词，比如把“天气”换成“苹果”（故意加入错别字，逼迫模型纠错并更依赖上下文）。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;10% 不动：&lt;/strong&gt; 保持原词不变（让模型知道，给你的词有时候也是对的，你要坚定自己的判断）。&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;lecture-8&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#lecture-8&#34;&gt;#&lt;/a&gt; lecture 8&lt;/h2&gt;
&lt;h3 id=&#34;linear-attention&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#linear-attention&#34;&gt;#&lt;/a&gt; Linear Attention&lt;/h3&gt;
&lt;p&gt;标准 Transformer 的 self-attention 需要计算完整的注意力矩阵：&lt;/p&gt;
&lt;p&gt;[&lt;br /&gt;
\text&lt;ruby&gt;Attention}(Q,K,V)=\text{softmax}\left(\frac{QK&lt;rp&gt;(&lt;/rp&gt;&lt;rt&gt;\top&lt;/rt&gt;&lt;rp&gt;)&lt;/rp&gt;&lt;/ruby&gt;{\sqrt{d}}\right)V&lt;br /&gt;
]&lt;/p&gt;
&lt;p&gt;如果序列长度是 (N)，注意力矩阵大小是 (N\times N)，所以显存和计算都会随序列长度快速增长，典型复杂度是 (O(N^2))。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Linear Attention 的核心想法&lt;/strong&gt;：把 self-attention 中最贵的部分改写成可以按序列递推 / 累积的形式，从而避免显式保存完整的 (N\times N) 注意力矩阵。&lt;/p&gt;
&lt;p&gt;PPT 里给的直觉是：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Linear Attention = Self-Attention without Softmax&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Linear Attention = RNN without forget gate&lt;/strong&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;也就是说，它一方面像 attention 一样做信息聚合，另一方面又可以像 RNN 一样维护一个“历史状态”。这样训练时能更并行，推理时也可以逐 token 更新状态。&lt;/p&gt;
&lt;p&gt;但是 Linear Attention 有一个问题：&lt;strong&gt;它不容易忘记旧信息&lt;/strong&gt;。&lt;/p&gt;
&lt;p&gt;标准 attention 里的 softmax 会重新分配注意力权重，重要 token 权重大，不重要 token 权重小；而线性形式如果只是不断累积，历史信息会一直留在状态里，模型不一定能很好地区分“该保留的”和“该淡化的”。&lt;/p&gt;
&lt;h3 id=&#34;retention-network&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#retention-network&#34;&gt;#&lt;/a&gt; Retention Network&lt;/h3&gt;
&lt;p&gt;Retention Network（RetNet）可以理解成对 Linear Attention 的进一步改造。&lt;/p&gt;
&lt;p&gt;它的目标是同时保留三件事：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;训练时可以并行。&lt;/li&gt;
&lt;li&gt;推理时可以像 RNN 一样递推。&lt;/li&gt;
&lt;li&gt;长序列上比普通 attention 更省显存。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;PPT 中强调了 &lt;code&gt;forget / keep / fade&lt;/code&gt; 这类机制：也就是让模型不仅能保存历史，还能控制哪些信息要保留、哪些信息要衰减。&lt;/p&gt;
&lt;p&gt;Gated Retention Network 进一步加入 gate，让模型动态控制信息流。直觉上类似 LSTM/GRU 里的门控思想，只是这里服务的是 attention/retention 风格的序列建模。&lt;/p&gt;
&lt;p&gt;和 Transformer 对比：&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;方法&lt;/th&gt;
&lt;th&gt;主要思想&lt;/th&gt;
&lt;th&gt;优点&lt;/th&gt;
&lt;th&gt;风险&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;Transformer Attention&lt;/td&gt;
&lt;td&gt;显式计算所有 token 两两关系&lt;/td&gt;
&lt;td&gt;表达能力强，可解释性强&lt;/td&gt;
&lt;td&gt;长序列 (O(N^2)) 显存压力大&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Linear Attention&lt;/td&gt;
&lt;td&gt;去掉/改写 softmax，让注意力可线性计算&lt;/td&gt;
&lt;td&gt;更省显存，适合长序列&lt;/td&gt;
&lt;td&gt;容易“不会忘”&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;RetNet / Gated Retention&lt;/td&gt;
&lt;td&gt;在线性状态中加入 retention/gate&lt;/td&gt;
&lt;td&gt;兼顾并行训练和递推推理&lt;/td&gt;
&lt;td&gt;结构更复杂&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;h3 id=&#34;contextualized-word-embedding&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#contextualized-word-embedding&#34;&gt;#&lt;/a&gt; Contextualized Word Embedding&lt;/h3&gt;
&lt;p&gt;传统 Word2Vec / GloVe 的问题是：&lt;strong&gt;同一个 token 永远查到同一个 embedding&lt;/strong&gt;。&lt;/p&gt;
&lt;p&gt;例如：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;宠物狗&lt;/code&gt; 里的“狗”&lt;/li&gt;
&lt;li&gt;&lt;code&gt;单身狗&lt;/code&gt; 里的“狗”&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;如果只做表查找，两个“狗”的向量是一样的。但这两个词里的语义明显不同。&lt;/p&gt;
&lt;p&gt;所以后来的预训练模型使用 &lt;strong&gt;Contextualized Word Embedding（上下文化词向量）&lt;/strong&gt;：&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;token 的表示不只由 token 本身决定，还由上下文决定。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;也就是说，同一个词放在不同句子里，经过 LSTM / Transformer / Tree-based model 等多层模型以后，会得到不同的上下文化表示。&lt;/p&gt;
&lt;p&gt;这也是 BERT、GPT 这类模型比静态词向量强很多的原因：它们输出的不是一个死的查表向量，而是“结合上下文读完以后”的向量。&lt;/p&gt;
&lt;h3 id=&#34;bigger-model-和-smaller-model&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#bigger-model-和-smaller-model&#34;&gt;#&lt;/a&gt; Bigger Model 和 Smaller Model&lt;/h3&gt;
&lt;p&gt;预训练模型的发展有两个方向：&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;1. Bigger Model&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;把模型做大：更多层、更宽 hidden size、更多参数、更多数据。比如 Megatron、Turing NLG 这类工作。&lt;/p&gt;
&lt;p&gt;大模型的优势是容量更大，能记住和抽象更多模式；缺点是训练和部署成本非常高。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;2. Smaller Model&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;把模型压小，让它更容易部署。常见路线包括：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Network Pruning（剪枝）&lt;/strong&gt;：删掉不重要的连接、神经元或结构。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Knowledge Distillation（知识蒸馏）&lt;/strong&gt;：用大模型当 teacher，训练小模型 student。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Parameter Quantization（参数量化）&lt;/strong&gt;：用更低 bit 表示权重，比如 fp16、int8、int4。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Architecture Design（结构设计）&lt;/strong&gt;：直接设计更轻量的模型结构。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;这部分只是引出“模型太大怎么办”，真正的模型压缩会在第 7 个 PPT 里继续讲。&lt;/p&gt;
&lt;h3 id=&#34;fine-tuning&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#fine-tuning&#34;&gt;#&lt;/a&gt; Fine-tuning&lt;/h3&gt;
&lt;p&gt;预训练模型学到的是通用语言能力，下游任务还需要 fine-tune。&lt;/p&gt;
&lt;p&gt;基本做法：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;输入句子或句子对。&lt;/li&gt;
&lt;li&gt;经过预训练模型得到表示。&lt;/li&gt;
&lt;li&gt;接一个 task-specific layer。&lt;/li&gt;
&lt;li&gt;用具体任务的数据继续训练。&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;输入可以是：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;one sentence&lt;/strong&gt;：单句分类、情感分析等。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;multiple sentences&lt;/strong&gt;：句子对匹配、自然语言推理、问答中的 query-document 等。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;输出常见有四类：&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;输出类型&lt;/th&gt;
&lt;th&gt;例子&lt;/th&gt;
&lt;th&gt;做法&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;one class&lt;/td&gt;
&lt;td&gt;情感分类、文本分类&lt;/td&gt;
&lt;td&gt;用 &lt;code&gt;[CLS]&lt;/code&gt; 的表示接分类器&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;class for each token&lt;/td&gt;
&lt;td&gt;命名实体识别、词性标注&lt;/td&gt;
&lt;td&gt;每个 token 输出一个类别&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;copy from input&lt;/td&gt;
&lt;td&gt;抽取式 QA&lt;/td&gt;
&lt;td&gt;预测答案 span 的起点 (s) 和终点 (e)&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;general sequence&lt;/td&gt;
&lt;td&gt;翻译、摘要、生成&lt;/td&gt;
&lt;td&gt;接 decoder 或直接做 seq2seq&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;h4 id=&#34;抽取式-qa&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#抽取式-qa&#34;&gt;#&lt;/a&gt; 抽取式 QA&lt;/h4&gt;
&lt;p&gt;输入：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Document: (D=d_1,d_2,\cdots,d_N)&lt;/li&gt;
&lt;li&gt;Query: (Q=q_1,q_2,\cdots,q_M)&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;输出两个整数：&lt;/p&gt;
&lt;p&gt;[&lt;br /&gt;
(s,e)&lt;br /&gt;
]&lt;/p&gt;
&lt;p&gt;答案就是：&lt;/p&gt;
&lt;p&gt;[&lt;br /&gt;
A=d_s,\cdots,d_e&lt;br /&gt;
]&lt;/p&gt;
&lt;p&gt;BERT 做抽取式 QA 时，通常把 question 和 document 拼起来：&lt;/p&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-text&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span&gt;[CLS] question [SEP] document&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;然后对 document 中每个位置分别预测：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;这个位置是不是答案起点。&lt;/li&gt;
&lt;li&gt;这个位置是不是答案终点。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;最后选出概率最大的 (s,e)。&lt;/p&gt;
&lt;h4 id=&#34;fine-tune-的几种方式&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#fine-tune-的几种方式&#34;&gt;#&lt;/a&gt; Fine-tune 的几种方式&lt;/h4&gt;
&lt;p&gt;&lt;strong&gt;1. 全量 fine-tune&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;所有参数都跟着下游任务更新。&lt;/p&gt;
&lt;p&gt;优点：效果通常最好。&lt;/p&gt;
&lt;p&gt;缺点：每个任务都要保存一份大模型参数，显存和存储压力大。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;2. Feature extractor&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;把预训练模型固定住，只把它当特征提取器，然后训练一个小的 task-specific layer。&lt;/p&gt;
&lt;p&gt;优点：省显存，训练快。&lt;/p&gt;
&lt;p&gt;缺点：适配能力弱一些。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;3. Adapter&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;在每层 Transformer 中插入很小的 Adapter 模块，只训练 Adapter 和任务头，原模型主体参数固定。&lt;/p&gt;
&lt;p&gt;优点：每个任务只存一小份 Adapter。&lt;/p&gt;
&lt;p&gt;缺点：结构会稍微复杂一点。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;4. Weighted Features&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;不同层的表示可能包含不同信息。可以学习每一层的权重，把多层 hidden states 加权融合后用于下游任务。&lt;/p&gt;
&lt;h3 id=&#34;self-supervised-learning&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#self-supervised-learning&#34;&gt;#&lt;/a&gt; Self-supervised Learning&lt;/h3&gt;
&lt;p&gt;预训练语言模型通常不依赖人工标注，而是用 &lt;strong&gt;self-supervised learning（自监督学习）&lt;/strong&gt;。&lt;/p&gt;
&lt;p&gt;监督学习是：&lt;/p&gt;
&lt;p&gt;[&lt;br /&gt;
x \rightarrow y&lt;br /&gt;
]&lt;/p&gt;
&lt;p&gt;也就是输入 (x)，人工给标签 (y)。&lt;/p&gt;
&lt;p&gt;自监督学习是：&lt;/p&gt;
&lt;p&gt;[&lt;br /&gt;
x \rightarrow x&#39;&lt;br /&gt;
]&lt;/p&gt;
&lt;p&gt;标签来自数据本身。比如从一段文本里挖掉一部分，让模型预测被挖掉的词；或者给前面的 token，让模型预测下一个 token。&lt;/p&gt;
&lt;p&gt;NLP 中最典型的两种自监督任务：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Masked Language Modeling（MLM）&lt;/strong&gt;：BERT 风格，mask 中间的词，再用左右上下文预测。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Next Token Prediction&lt;/strong&gt;：GPT 风格，给定左侧上下文，预测下一个 token。&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;gpt-的-next-token-prediction&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#gpt-的-next-token-prediction&#34;&gt;#&lt;/a&gt; GPT 的 Next Token Prediction&lt;/h3&gt;
&lt;p&gt;GPT 类模型训练时做的是语言模型任务：&lt;/p&gt;
&lt;p&gt;[&lt;br /&gt;
P(w_{t+1}\mid w_1,\cdots,w_t)&lt;br /&gt;
]&lt;/p&gt;
&lt;p&gt;也就是从左到右读文本，根据当前上下文预测下一个 token。&lt;/p&gt;
&lt;p&gt;训练过程：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;输入序列 (w_1,w_2,w_3,\cdots)。&lt;/li&gt;
&lt;li&gt;每个位置输出一个 hidden state (h_t)。&lt;/li&gt;
&lt;li&gt;用线性层 + softmax 得到词表上的概率分布。&lt;/li&gt;
&lt;li&gt;用 cross entropy 让模型预测真实的下一个 token (w_{t+1})。&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;这和之前 RNN-LM 的训练目标本质一样，只是 GPT 用的是带 causal mask 的 Transformer Decoder。&lt;/p&gt;
&lt;p&gt;GPT 的 self-attention 有限制：当前位置只能看左边和自己，不能偷看未来 token。&lt;/p&gt;
&lt;p&gt;所以：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;BERT：双向 encoder，更适合理解任务。&lt;/li&gt;
&lt;li&gt;GPT：单向/因果 decoder，更适合生成任务。&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;elmo-和双向语言模型&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#elmo-和双向语言模型&#34;&gt;#&lt;/a&gt; ELMo 和双向语言模型&lt;/h3&gt;
&lt;p&gt;PPT 里还提到 ELMo。&lt;/p&gt;
&lt;p&gt;ELMo 使用的是 bidirectional LSTM：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;一个 LSTM 从左往右读。&lt;/li&gt;
&lt;li&gt;一个 LSTM 从右往左读。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;这样每个词的表示同时包含左上下文和右上下文。&lt;/p&gt;
&lt;p&gt;它解决的问题是：只做 next token prediction 时，模型看到的是左上下文；但理解一个词，右上下文也很重要。&lt;/p&gt;
&lt;p&gt;这和 BERT 的动机类似：都希望得到上下文化表示。但技术路线不同：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;ELMo：BiLSTM。&lt;/li&gt;
&lt;li&gt;BERT：Transformer Encoder + MLM。&lt;/li&gt;
&lt;li&gt;GPT：Transformer Decoder + Next Token Prediction。&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;how-to-train-your-llm&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#how-to-train-your-llm&#34;&gt;#&lt;/a&gt; How to train your LLM&lt;/h3&gt;
&lt;p&gt;第 6 个 PPT 进入大模型训练工程问题。&lt;/p&gt;
&lt;p&gt;普通 PyTorch 训练循环大概是：&lt;/p&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#1E754F;--shiki-dark:#4D9375&#34;&gt;for&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt; epoch &lt;/span&gt;&lt;span style=&#34;color:#1E754F;--shiki-dark:#4D9375&#34;&gt;in&lt;/span&gt;&lt;span style=&#34;color:#998418;--shiki-dark:#B8A965&#34;&gt; range&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;(&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;num_epochs&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;)&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;:&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#1E754F;--shiki-dark:#4D9375&#34;&gt;    for&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt; batch &lt;/span&gt;&lt;span style=&#34;color:#1E754F;--shiki-dark:#4D9375&#34;&gt;in&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt; dataloader&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;:&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;        inputs&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;,&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt; targets &lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;=&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt; batch&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;        outputs &lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;=&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt; model&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;(&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;inputs&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;)&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;        loss &lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;=&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt; loss_fn&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;(&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;outputs&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;,&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt; targets&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;)&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;        optimizer&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;.&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;zero_grad&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;(&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;)&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;        loss&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;.&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;backward&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;(&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;)&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;        optimizer&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;.&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;step&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;(&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;)&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;但 LLM 太大，通常不能直接塞进单张 GPU。主要问题有三个：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;参数、梯度和 optimizer states 太大。&lt;/li&gt;
&lt;li&gt;activations 太大，尤其是长上下文 attention。&lt;/li&gt;
&lt;li&gt;低显存推理/训练需要量化等压缩手段。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;PPT 中给的对应工具：&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;问题&lt;/th&gt;
&lt;th&gt;典型工具&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;multi-GPU / 模型太大&lt;/td&gt;
&lt;td&gt;DeepSpeed&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;long context / activation 太大&lt;/td&gt;
&lt;td&gt;FlashAttention、Liger Kernel&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;small VRAM inference&lt;/td&gt;
&lt;td&gt;Quantization&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;h3 id=&#34;llm-训练需要多少显存&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#llm-训练需要多少显存&#34;&gt;#&lt;/a&gt; LLM 训练需要多少显存&lt;/h3&gt;
&lt;p&gt;假设是一个 8B 参数模型。&lt;/p&gt;
&lt;p&gt;如果参数用 fp32：&lt;/p&gt;
&lt;p&gt;[&lt;br /&gt;
8B \times 4\text{ bytes}=32\text{GB}&lt;br /&gt;
]&lt;/p&gt;
&lt;p&gt;训练时为了加速，一般 GPU 上会用 fp16/bf16 参与计算，所以模型权重本身可以是：&lt;/p&gt;
&lt;p&gt;[&lt;br /&gt;
8B \times 2\text{ bytes}=16\text{GB}&lt;br /&gt;
]&lt;/p&gt;
&lt;p&gt;但训练不只有权重，还要保存：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;fp16/bf16 model weights：约 16GB。&lt;/li&gt;
&lt;li&gt;gradients：约 16GB。&lt;/li&gt;
&lt;li&gt;Adam optimizer 的 momentum：约 32GB。&lt;/li&gt;
&lt;li&gt;Adam optimizer 的 variance：约 32GB。&lt;/li&gt;
&lt;li&gt;fp32 master weights / optimizer 相关状态：PPT 中整体算下来约 128GB 级别。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;PPT 的结论是：只看一个 8B 模型，参数、梯度、Adam 状态加起来就可能到 &lt;strong&gt;128GB&lt;/strong&gt; 左右，还没算 activations 和输入。&lt;/p&gt;
&lt;p&gt;对比常见 GPU：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;T4：约 15GB。&lt;/li&gt;
&lt;li&gt;4090：约 24GB。&lt;/li&gt;
&lt;li&gt;A100：约 40GB。&lt;/li&gt;
&lt;li&gt;H100：约 80GB。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;所以单卡训练完整 LLM 很快就不现实。&lt;/p&gt;
&lt;h3 id=&#34;activations&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#activations&#34;&gt;#&lt;/a&gt; Activations&lt;/h3&gt;
&lt;p&gt;训练时 forward 过程中会保存中间结果，backward 时要用它们算梯度。这些中间结果就是 activations。&lt;/p&gt;
&lt;p&gt;长上下文下 activations 会非常大，尤其是 attention。&lt;/p&gt;
&lt;p&gt;PPT 中的例子：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;batch size = 1。&lt;/li&gt;
&lt;li&gt;context 可以从 256 tokens 到 16k tokens。&lt;/li&gt;
&lt;li&gt;32 层模型。&lt;/li&gt;
&lt;li&gt;单层 attention activation 可能到 40GB 级别。&lt;/li&gt;
&lt;li&gt;单层 feed forward activation 约 2.2GB。&lt;/li&gt;
&lt;li&gt;32 层累积后可能到 TB 级别，PPT 图里给出约 1.35TB。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;这说明：训练 LLM 时，显存瓶颈不只是模型参数，长序列的 activations 也非常关键。&lt;/p&gt;
&lt;h4 id=&#34;activation-recomputation-gradient-checkpointing&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#activation-recomputation-gradient-checkpointing&#34;&gt;#&lt;/a&gt; Activation recomputation / Gradient checkpointing&lt;/h4&gt;
&lt;p&gt;解决 activation 太大的常见方法是 &lt;strong&gt;activation recomputation&lt;/strong&gt;，也叫 &lt;strong&gt;gradient checkpointing&lt;/strong&gt;。&lt;/p&gt;
&lt;p&gt;核心思想：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;forward 时不保存所有 activations。&lt;/li&gt;
&lt;li&gt;只保存一些关键 checkpoint。&lt;/li&gt;
&lt;li&gt;backward 需要某段中间结果时，再重新算一遍。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;优点：显著省显存。&lt;/p&gt;
&lt;p&gt;缺点：需要重复计算，所以训练会变慢。&lt;/p&gt;
&lt;h3 id=&#34;batch-size-和-gradient-accumulation&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#batch-size-和-gradient-accumulation&#34;&gt;#&lt;/a&gt; Batch Size 和 Gradient Accumulation&lt;/h3&gt;
&lt;p&gt;大模型训练需要足够大的 batch size，才能得到比较稳定的梯度。&lt;/p&gt;
&lt;p&gt;PPT 给的经验范围：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;一般是 &lt;strong&gt;4M 到 60M tokens per batch&lt;/strong&gt;。&lt;/li&gt;
&lt;li&gt;DeepSeek V3 例子：batch size 1920，context length 32K，总 token 数约 61M。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;如果单次 mini-batch 放不下，可以用 &lt;strong&gt;gradient accumulation（梯度累积）&lt;/strong&gt;。&lt;/p&gt;
&lt;p&gt;公式：&lt;/p&gt;
&lt;p&gt;[&lt;br /&gt;
\text{Global batch size}=\text{mini batch size}\times\text{gradient accumulation steps}&lt;br /&gt;
]&lt;/p&gt;
&lt;p&gt;例如：&lt;/p&gt;
&lt;p&gt;[&lt;br /&gt;
1920=16\times 120&lt;br /&gt;
]&lt;/p&gt;
&lt;p&gt;意思是每次只跑 mini batch = 16，连续累积 120 次梯度以后，再做一次 optimizer step。&lt;/p&gt;
&lt;h3 id=&#34;deepspeed-zero&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#deepspeed-zero&#34;&gt;#&lt;/a&gt; DeepSpeed ZeRO&lt;/h3&gt;
&lt;p&gt;ZeRO 的全称是 &lt;strong&gt;Zero Redundancy Optimizer&lt;/strong&gt;。&lt;/p&gt;
&lt;p&gt;它要解决的问题是：数据并行时，每张 GPU 都保存一整份模型参数、梯度和 optimizer states，这会造成大量重复。&lt;/p&gt;
&lt;p&gt;ZeRO 的思想是：&lt;strong&gt;把这些状态切分到多张 GPU 上，每张 GPU 只保存一部分，需要时再通信拿到对应部分。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;PPT 中分为三个阶段：&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;阶段&lt;/th&gt;
&lt;th&gt;切分什么&lt;/th&gt;
&lt;th&gt;显存节省&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;ZeRO-1&lt;/td&gt;
&lt;td&gt;optimizer states&lt;/td&gt;
&lt;td&gt;先减少 Adam 状态冗余&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;ZeRO-2&lt;/td&gt;
&lt;td&gt;optimizer states + gradients&lt;/td&gt;
&lt;td&gt;再减少梯度冗余&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;ZeRO-3&lt;/td&gt;
&lt;td&gt;optimizer states + gradients + parameters&lt;/td&gt;
&lt;td&gt;连模型参数也切分&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;p&gt;ZeRO-3 最省显存，但通信更多。&lt;/p&gt;
&lt;p&gt;PPT 中还强调训练速度取决于：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;网络带宽。&lt;/li&gt;
&lt;li&gt;模型大小。&lt;/li&gt;
&lt;li&gt;硬件配置。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;一般不会慢一个数量级，但通信开销一定存在。PPT 图里还提到 NVLink 约 900GB/s，意思是高速互联对 ZeRO 很重要。&lt;/p&gt;
&lt;h3 id=&#34;zero-offload&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#zero-offload&#34;&gt;#&lt;/a&gt; ZeRO-Offload&lt;/h3&gt;
&lt;p&gt;ZeRO-Offload 是把一部分状态从 GPU 挪到 CPU 内存。&lt;/p&gt;
&lt;p&gt;可以 offload 的对象包括：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;optimizer states。&lt;/li&gt;
&lt;li&gt;model parameters。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;这样能大幅减少 GPU 显存占用，但 CPU 和 GPU 之间传输数据会很慢。&lt;/p&gt;
&lt;p&gt;PPT 里明确警告：&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;using offload can be very slow&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;所以 Offload 更像是“显存不够时的救命方案”，不是默认的高性能方案。&lt;/p&gt;
&lt;p&gt;PPT 图中的直观结论：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;offload 后每张 GPU 显存可以降到很低。&lt;/li&gt;
&lt;li&gt;但 step time 可能明显变长。&lt;/li&gt;
&lt;li&gt;不 offload 时速度更快，但需要更多 GPU 显存。&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;kernel&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#kernel&#34;&gt;#&lt;/a&gt; Kernel&lt;/h3&gt;
&lt;p&gt;大模型训练中，很多耗时来自底层算子。&lt;/p&gt;
&lt;p&gt;PPT 按抽象层次列了几种实现方式：&lt;/p&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-text&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span&gt;Naive PyTorch&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;torch.compile()&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;Triton&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;CUDA&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;越往上，代码越容易写，但控制更少、速度可能较慢。&lt;/p&gt;
&lt;p&gt;越往下，越接近硬件，控制更强、速度更快，但开发难度更高。&lt;/p&gt;
&lt;p&gt;所以工程上会用 optimized kernel 来替换一些核心计算，比如 attention、RMSNorm、cross entropy 等。&lt;/p&gt;
&lt;h3 id=&#34;flashattention&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#flashattention&#34;&gt;#&lt;/a&gt; FlashAttention&lt;/h3&gt;
&lt;p&gt;FlashAttention 解决的是 attention 的速度和显存问题。&lt;/p&gt;
&lt;p&gt;它计算的数学结果和标准 scaled dot-product attention 一样，但实现方式更聪明。&lt;/p&gt;
&lt;p&gt;普通 attention 会显式生成很大的 (N\times N) attention matrix：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;MatMul。&lt;/li&gt;
&lt;li&gt;Scale。&lt;/li&gt;
&lt;li&gt;Mask。&lt;/li&gt;
&lt;li&gt;Softmax。&lt;/li&gt;
&lt;li&gt;Dropout。&lt;/li&gt;
&lt;li&gt;MatMul with V。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;这些步骤会产生大量中间张量，显存压力大。&lt;/p&gt;
&lt;p&gt;FlashAttention 的做法：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;使用 fused kernel，把多个步骤合并。&lt;/li&gt;
&lt;li&gt;分块读取 Q、K、V。&lt;/li&gt;
&lt;li&gt;尽量减少 GPU HBM 和 SRAM/缓存之间的数据搬运。&lt;/li&gt;
&lt;li&gt;不完整保存 (N\times N) 注意力矩阵。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;结果：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;训练更快。&lt;/li&gt;
&lt;li&gt;显存更少。&lt;/li&gt;
&lt;li&gt;长序列收益更明显。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;PPT 中给的直觉是：普通 attention 空间接近 (O(N^2))，FlashAttention 通过优化访存使显存更接近线性。&lt;/p&gt;
&lt;h3 id=&#34;liger-kernel&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#liger-kernel&#34;&gt;#&lt;/a&gt; Liger Kernel&lt;/h3&gt;
&lt;p&gt;Liger Kernel 是用 Triton 重新实现一些 LLM 核心计算。&lt;/p&gt;
&lt;p&gt;目标：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;提高吞吐量。&lt;/li&gt;
&lt;li&gt;降低 peak reserved memory。&lt;/li&gt;
&lt;li&gt;让长序列训练更不容易 OOM。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;PPT 里给了使用方式：把 HuggingFace 的模型类替换成 Liger 的模型类。&lt;/p&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#1E754F;--shiki-dark:#4D9375&#34;&gt;from&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt; transformers &lt;/span&gt;&lt;span style=&#34;color:#1E754F;--shiki-dark:#4D9375&#34;&gt;import&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt; AutoModelForCausalLM&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;model &lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;=&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt; AutoModelForCausalLM&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;.&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;from_pretrained&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;(&lt;/span&gt;&lt;span style=&#34;color:#B5695977;--shiki-dark:#C98A7D77&#34;&gt;&#34;&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt;/path/to/model&lt;/span&gt;&lt;span style=&#34;color:#B5695977;--shiki-dark:#C98A7D77&#34;&gt;&#34;&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;)&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#1E754F;--shiki-dark:#4D9375&#34;&gt;from&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt; liger_kernel&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;.&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;transformers &lt;/span&gt;&lt;span style=&#34;color:#1E754F;--shiki-dark:#4D9375&#34;&gt;import&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt; AutoLigerKernelForCausalLM&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;model &lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;=&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt; AutoLigerKernelForCausalLM&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;.&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;from_pretrained&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;(&lt;/span&gt;&lt;span style=&#34;color:#B5695977;--shiki-dark:#C98A7D77&#34;&gt;&#34;&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt;path/to/some/model&lt;/span&gt;&lt;span style=&#34;color:#B5695977;--shiki-dark:#C98A7D77&#34;&gt;&#34;&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;)&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;图里还显示：在更长 seq len 下，普通 HuggingFace 实现更容易 OOM，而 Liger Kernel 仍然能跑，并且吞吐量更高。&lt;/p&gt;
&lt;h3 id=&#34;quantization&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#quantization&#34;&gt;#&lt;/a&gt; Quantization&lt;/h3&gt;
&lt;p&gt;量化是有损压缩。&lt;/p&gt;
&lt;p&gt;原来模型权重可能是 32 bit 浮点数，量化后用更少 bit 表示：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;8 bit，也就是 int8。&lt;/li&gt;
&lt;li&gt;4 bit。&lt;/li&gt;
&lt;li&gt;2 bit。&lt;/li&gt;
&lt;li&gt;1 bit。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;推理时再做 dequantization，把低 bit 表示还原到可计算的近似值。&lt;/p&gt;
&lt;p&gt;常见量化工具 / 方法：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;GPTQ。&lt;/li&gt;
&lt;li&gt;AWQ。&lt;/li&gt;
&lt;li&gt;GGML family。&lt;/li&gt;
&lt;li&gt;BitsAndBytes。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;注意：有些算法不会压缩整个 LLM，而是只压缩其中一部分，以换取更好的精度。&lt;/p&gt;
&lt;p&gt;PPT 例子：&lt;/p&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-text&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span&gt;Meta-Llama-3.1-8B-Instruct-Q8_0.gguf&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;8B 模型如果每个 weight 用 8 bit：&lt;/p&gt;
&lt;p&gt;[&lt;br /&gt;
8B \times 8\text{ bit}=8\text{GB}&lt;br /&gt;
]&lt;/p&gt;
&lt;p&gt;所以只看权重，大概需要 8GB GPU RAM。PPT 里写 T4 GPU 约 15GB VRAM 可以放下这个量化模型。&lt;/p&gt;
&lt;p&gt;量化的本质权衡：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;bit 越低，显存越省、推理越容易部署。&lt;/li&gt;
&lt;li&gt;bit 越低，信息损失越大，模型效果可能下降。&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;lecture-9&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#lecture-9&#34;&gt;#&lt;/a&gt; lecture 9&lt;/h2&gt;
&lt;p&gt;这节主要讲两件事：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;&lt;strong&gt;Model Compression（模型压缩）&lt;/strong&gt;：模型已经训练好了，怎么让它推理更便宜、更快、更省显存。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Data/Parameter-Efficient Fine-tuning（数据高效 / 参数高效微调）&lt;/strong&gt;：下游任务数据少、模型又太大时，怎么用更少数据和更少参数适配任务。&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;背景是：现在 NLP 系统已经大规模部署，训练大模型很贵，但&lt;strong&gt;推理可能更贵&lt;/strong&gt;。因为训练是一次性的，而推理是每个用户、每次请求都要付成本。&lt;/p&gt;
&lt;p&gt;同时，顶尖 NLP 模型并没有变小，反而越来越大。问题就变成：&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;如何在不牺牲太多性能的情况下，更便宜、更高效、更公平地部署 NLP 系统？&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h3 id=&#34;model-compression&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#model-compression&#34;&gt;#&lt;/a&gt; Model Compression&lt;/h3&gt;
&lt;p&gt;模型压缩主要有三条路线：&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;方法&lt;/th&gt;
&lt;th&gt;核心思想&lt;/th&gt;
&lt;th&gt;改了什么&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;Quantization（量化）&lt;/td&gt;
&lt;td&gt;模型结构不变，用更少 bit 表示参数&lt;/td&gt;
&lt;td&gt;参数精度&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Pruning（剪枝）&lt;/td&gt;
&lt;td&gt;删除或置零模型中不重要的部分&lt;/td&gt;
&lt;td&gt;参数 / 结构&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Distillation（蒸馏）&lt;/td&gt;
&lt;td&gt;训练一个小模型模仿大模型&lt;/td&gt;
&lt;td&gt;重新训练学生模型&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;p&gt;为什么压缩有可能成立？&lt;/p&gt;
&lt;p&gt;一个原因是大模型通常是 &lt;strong&gt;overparameterized（过参数化）&lt;/strong&gt; 的。参数很多会让优化更容易，但最终并不是所有参数都同等重要，所以可以压缩掉一部分冗余。&lt;/p&gt;
&lt;h3 id=&#34;quantization-2&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#quantization-2&#34;&gt;#&lt;/a&gt; Quantization&lt;/h3&gt;
&lt;p&gt;量化的目标是：&lt;strong&gt;保持模型结构基本不变，但用更低精度保存和计算参数。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;比如原来权重是 fp32：&lt;/p&gt;
&lt;p&gt;[&lt;br /&gt;
32\text{ bit} = 4\text{ bytes}&lt;br /&gt;
]&lt;/p&gt;
&lt;p&gt;量化后可能变成 fp16、bf16、int8、int4，甚至二值化。&lt;/p&gt;
&lt;h4 id=&#34;post-training-quantization&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#post-training-quantization&#34;&gt;#&lt;/a&gt; Post-Training Quantization&lt;/h4&gt;
&lt;p&gt;Post-Training Quantization（PTQ）就是：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;先用正常精度训练模型。&lt;/li&gt;
&lt;li&gt;训练完后再把权重量化。&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;例如先训练一个 65B 参数模型，然后把权重从高精度变成 int8 或 int4。&lt;/p&gt;
&lt;p&gt;优点：不需要重新训练完整模型，成本较低。&lt;/p&gt;
&lt;p&gt;缺点：量化会带来误差，精度可能下降。&lt;/p&gt;
&lt;h4 id=&#34;浮点数表示&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#浮点数表示&#34;&gt;#&lt;/a&gt; 浮点数表示&lt;/h4&gt;
&lt;p&gt;浮点数一般可以写成：&lt;/p&gt;
&lt;p&gt;[&lt;br /&gt;
(-1)^s M 2^E&lt;br /&gt;
]&lt;/p&gt;
&lt;p&gt;其中：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;(s)：sign bit，符号位。&lt;/li&gt;
&lt;li&gt;(M)：fractional part，尾数 / 有效数字。&lt;/li&gt;
&lt;li&gt;(E)：exponential part，指数部分，通常是 &lt;code&gt;exp - bias&lt;/code&gt;。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;低精度浮点数就是减少这些部分的 bit 数。这样显存更省，但表示范围或精度会变差。&lt;/p&gt;
&lt;h4 id=&#34;int8-quantization&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#int8-quantization&#34;&gt;#&lt;/a&gt; Int8 Quantization&lt;/h4&gt;
&lt;p&gt;PPT 中介绍了 &lt;strong&gt;absmax quantization&lt;/strong&gt;。&lt;/p&gt;
&lt;p&gt;核心是把一组实数线性缩放到 int8 可表示的范围：&lt;/p&gt;
&lt;p&gt;[&lt;br /&gt;
[-127,127]&lt;br /&gt;
]&lt;/p&gt;
&lt;p&gt;如果一组数中绝对值最大的数是 (m)，那么可以做：&lt;/p&gt;
&lt;p&gt;[&lt;br /&gt;
x_{\text{int8}}=\text{round}\left(\frac{127}{m}x\right)&lt;br /&gt;
]&lt;/p&gt;
&lt;p&gt;PPT 例子：&lt;/p&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-text&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span&gt;[0.5, 20, -0.0001, -0.01, -0.1]&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;最大值是 20，所以：&lt;/p&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-text&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span&gt;round(127/20 * [0.5, 20, -0.0001, -0.01, -0.1])&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;= [3, 127, 0, 0, -1]&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;直觉：最大的数被映射到 127，其余数按比例缩放。&lt;/p&gt;
&lt;p&gt;问题：非常小的数可能被 round 成 0，信息会丢失。&lt;/p&gt;
&lt;h4 id=&#34;binarized-neural-networks&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#binarized-neural-networks&#34;&gt;#&lt;/a&gt; Binarized Neural Networks&lt;/h4&gt;
&lt;p&gt;二值神经网络是极端量化：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;权重只有 (-1) 或 (1)。&lt;/li&gt;
&lt;li&gt;activation 也可以二值化。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;这样模型非常省空间，计算也可以很快，但表达能力和训练稳定性会受影响。&lt;/p&gt;
&lt;p&gt;在 Quantization-Aware Training 中，二值化甚至可以参与训练：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;forward 用离散值。&lt;/li&gt;
&lt;li&gt;activation 也用随机方式二值化。&lt;/li&gt;
&lt;li&gt;backward 也要处理离散化带来的梯度问题。&lt;/li&gt;
&lt;/ul&gt;
&lt;h4 id=&#34;model-aware-quantization&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#model-aware-quantization&#34;&gt;#&lt;/a&gt; Model-Aware Quantization&lt;/h4&gt;
&lt;p&gt;简单统一量化的问题是：它不考虑模型内部不同权重的重要性和分布。&lt;/p&gt;
&lt;p&gt;Model-Aware Quantization 会利用模型权重的统计规律。&lt;/p&gt;
&lt;h4 id=&#34;gobo&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#gobo&#34;&gt;#&lt;/a&gt; GOBO&lt;/h4&gt;
&lt;p&gt;GOBO 的观察：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;BERT 每一层的权重大致服从 Gaussian 分布。&lt;/li&gt;
&lt;li&gt;大多数权重集中在分布主体。&lt;/li&gt;
&lt;li&gt;只有很少一部分权重位于尾部。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;做法：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;把分布主体中的 &lt;strong&gt;99.9%&lt;/strong&gt; 权重量化到 8 个 bucket。&lt;/li&gt;
&lt;li&gt;尾部的少量重要权重不量化。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;直觉：大部分普通权重可以粗糙表示，但极端值可能很重要，保留高精度更稳。&lt;/p&gt;
&lt;h4 id=&#34;llmint8&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#llmint8&#34;&gt;#&lt;/a&gt; LLM.int8&lt;/h4&gt;
&lt;p&gt;LLM.int8 的问题背景：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Transformer LLM 中约 95% 的参数计算来自矩阵乘法。&lt;/li&gt;
&lt;li&gt;如果每层都统一量化，可能会被 outlier 干扰。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;LLM.int8 的目标是让超大模型能在单 GPU 上推理。&lt;/p&gt;
&lt;p&gt;PPT 中的结论：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;对小于 6.7B 的模型，量化 overhead 可能让速度变慢。&lt;/li&gt;
&lt;li&gt;但它可以让 175B 级别模型在单 GPU 上推理，并且更省时间。&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;量化不能只看算法，还要看硬件是否支持。&lt;/p&gt;
&lt;p&gt;比如：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;很多硬件不支持奇怪的数据类型，如 int3。&lt;/li&gt;
&lt;li&gt;PyTorch 也只支持一部分数据类型，例如没有原生完整支持 int4。&lt;/li&gt;
&lt;li&gt;某些量化方法需要专门写硬件加速器或 custom kernel。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;所以实际部署时，量化方法必须和硬件、框架、kernel 支持一起考虑。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h4 id=&#34;quantization-aware-training&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#quantization-aware-training&#34;&gt;#&lt;/a&gt; Quantization-Aware Training&lt;/h4&gt;
&lt;p&gt;Quantization-Aware Training（QAT）不是训练后再量化，而是在训练过程中就让模型“意识到”低精度。&lt;/p&gt;
&lt;p&gt;PTQ：&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;高精度训练完，再压低精度。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;QAT：&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;训练时就模拟低精度，让模型适应量化误差。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;优点：精度通常比 PTQ 更稳。&lt;/p&gt;
&lt;p&gt;缺点：训练成本更高。&lt;/p&gt;
&lt;h5 id=&#34;zeroquant&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#zeroquant&#34;&gt;#&lt;/a&gt; ZeroQuant&lt;/h5&gt;
&lt;p&gt;ZeroQuant 是一种 layer-by-layer quantization-aware distillation。&lt;/p&gt;
&lt;p&gt;做法：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;初始化一个和原模型结构相同的量化网络。&lt;/li&gt;
&lt;li&gt;对每一层，让量化网络模仿 full-precision 模型对应层的输出。&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;这样不是只在最终输出上对齐，而是逐层对齐，能减少量化误差的累积。&lt;/p&gt;
&lt;h4 id=&#34;q-lora&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#q-lora&#34;&gt;#&lt;/a&gt; Q-LoRA&lt;/h4&gt;
&lt;p&gt;Q-LoRA 是把量化和参数高效微调结合起来。&lt;/p&gt;
&lt;p&gt;它进一步压缩训练显存：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;把基础模型做 4-bit quantization。&lt;/li&gt;
&lt;li&gt;用 GPU memory paging 防止 OOM。&lt;/li&gt;
&lt;li&gt;在量化模型上加 LoRA 参数，只训练很小的低秩增量。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;PPT 里强调：Q-LoRA 可以在 &lt;strong&gt;48GB GPU 上训练 65B 模型&lt;/strong&gt;。&lt;/p&gt;
&lt;p&gt;直觉：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;base model：冻结，4-bit 保存，省显存。&lt;/li&gt;
&lt;li&gt;LoRA adapter：可训练，参数少。&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;pruning&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#pruning&#34;&gt;#&lt;/a&gt; Pruning&lt;/h3&gt;
&lt;p&gt;剪枝是在模型训练后，删除或置零一部分参数。&lt;/p&gt;
&lt;p&gt;和量化的区别：&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;方法&lt;/th&gt;
&lt;th&gt;参数数量&lt;/th&gt;
&lt;th&gt;参数值&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;Quantization&lt;/td&gt;
&lt;td&gt;参数还在&lt;/td&gt;
&lt;td&gt;精度变低&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Pruning&lt;/td&gt;
&lt;td&gt;一部分参数被删掉或置零&lt;/td&gt;
&lt;td&gt;剩下的参数值通常不变&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;h4 id=&#34;magnitude-pruning&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#magnitude-pruning&#34;&gt;#&lt;/a&gt; Magnitude Pruning&lt;/h4&gt;
&lt;p&gt;Magnitude Pruning 的规则很简单：&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;把绝对值最小的 (X%) 参数置零。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;原因是权重绝对值小，通常被认为对输出影响小。&lt;/p&gt;
&lt;p&gt;这是 &lt;strong&gt;unstructured pruning（非结构化剪枝）&lt;/strong&gt;：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;不关心参数属于哪个 head、layer 或 hidden dimension。&lt;/li&gt;
&lt;li&gt;只看单个权重大小。&lt;/li&gt;
&lt;/ul&gt;
&lt;h4 id=&#34;lottery-ticket-hypothesis&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#lottery-ticket-hypothesis&#34;&gt;#&lt;/a&gt; Lottery Ticket Hypothesis&lt;/h4&gt;
&lt;p&gt;Lottery Ticket Hypothesis 的核心观点：&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;在一个随机初始化的大网络中，存在一些较小的子网络。只训练这些子网络，可能比训练完整随机初始化网络更好。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;这些子网络被叫做 winning tickets。&lt;/p&gt;
&lt;p&gt;它说明：大模型里可能天然存在高效的小结构，剪枝不一定只是“删废物”，也可能是在寻找更好的子网络。&lt;/p&gt;
&lt;h4 id=&#34;wanda&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#wanda&#34;&gt;#&lt;/a&gt; Wanda&lt;/h4&gt;
&lt;p&gt;Wanda 是一种面向大模型的剪枝方法。&lt;/p&gt;
&lt;p&gt;&amp;lt;img src=&amp;quot;/assets/图片/image-20260428104530930.png&amp;quot; alt=&amp;quot;image-20260428104530930&amp;quot; style=&amp;quot;zoom: 33%;&amp;quot; /&amp;gt;&lt;/p&gt;
&lt;p&gt;它不只看权重大小，还会结合 activation 信息。直觉上，一个权重是否重要，不只取决于它自己大不大，也取决于它连接的输入 activation 是否常用、是否重要。&lt;/p&gt;
&lt;p&gt;可以粗略理解为：&lt;/p&gt;
&lt;p&gt;[&lt;br /&gt;
\text{importance} \approx |w|\cdot |x|&lt;br /&gt;
]&lt;/p&gt;
&lt;p&gt;权重大且对应 activation 重要的连接，更不应该被剪掉。&lt;/p&gt;
&lt;h4 id=&#34;非结构化剪枝的问题&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#非结构化剪枝的问题&#34;&gt;#&lt;/a&gt; 非结构化剪枝的问题&lt;/h4&gt;
&lt;p&gt;非结构化稀疏不一定真的带来速度提升。原因：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;参数虽然很多变成 0，但矩阵形状没变。&lt;/li&gt;
&lt;li&gt;普通 GPU 的 dense matrix multiplication 不会自动因为很多 0 就变快。&lt;/li&gt;
&lt;li&gt;需要支持 sparse data structure 和 sparse multiplication 的硬件 / kernel。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;所以非结构化剪枝可能减少参数量，但不一定减少真实推理时间。&lt;/p&gt;
&lt;h4 id=&#34;structured-pruning&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#structured-pruning&#34;&gt;#&lt;/a&gt; Structured Pruning&lt;/h4&gt;
&lt;p&gt;Structured Pruning（结构化剪枝）不是删零散权重，而是删完整组件。例如：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;删除整个 attention head。&lt;/li&gt;
&lt;li&gt;删除 FFN 中某些 hidden dimensions。&lt;/li&gt;
&lt;li&gt;删除某些 layer 或 module。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;lt;img src=&amp;quot;/assets/图片/image-20260428105127508.png&amp;quot; alt=&amp;quot;image-20260428105127508&amp;quot; style=&amp;quot;zoom:33%;&amp;quot; /&amp;gt;&lt;/p&gt;
&lt;p&gt;优点：删掉的是完整结构，硬件更容易加速。&lt;/p&gt;
&lt;p&gt;缺点：粒度更粗，剪错了影响更大。&lt;/p&gt;
&lt;h5 id=&#34;coarse-to-fine-structured-pruning&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#coarse-to-fine-structured-pruning&#34;&gt;#&lt;/a&gt; Coarse-to-Fine Structured Pruning&lt;/h5&gt;
&lt;p&gt;这是由粗到细的Pruning。&lt;/p&gt;
&lt;p&gt;Transformer layer 通常由两大块组成：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;self-attention。&lt;/li&gt;
&lt;li&gt;feed-forward network。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;Coarse-to-Fine Structured Pruning 的思路是学习 mask，控制哪些组件关闭。&lt;/p&gt;
&lt;p&gt;两种粒度：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Coarse masks&lt;/strong&gt;：关掉整个 self-attention 或 feed-forward component。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Fine masks&lt;/strong&gt;：关掉某些 attention heads 或 hidden state dimensions。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;这样先粗后细，能在较大结构和细粒度结构之间平衡。&lt;/p&gt;
&lt;h3 id=&#34;distillation&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#distillation&#34;&gt;#&lt;/a&gt; Distillation&lt;/h3&gt;
&lt;p&gt;Knowledge Distillation（知识蒸馏）是：&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;训练一个 student model，让它模仿 teacher model 的行为。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;通常 teacher 是大模型，student 是小模型。和量化、剪枝对比：&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;方法&lt;/th&gt;
&lt;th&gt;发生了什么&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;Quantization&lt;/td&gt;
&lt;td&gt;参数还在，只是精度变低&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Pruning&lt;/td&gt;
&lt;td&gt;一部分参数变成 0 或被删掉&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Distillation&lt;/td&gt;
&lt;td&gt;student 的几乎所有参数都会重新学习&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;p&gt;蒸馏和弱监督（ Weak Supervision ）关系很近。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Pseudo-label（伪标签）&lt;/strong&gt; 是模型给无标注数据生成的标签。之后我们把这些伪标签当作真实标签来训练。&lt;/p&gt;
&lt;p&gt;这个思想很早就有，比如：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Self-training。&lt;/li&gt;
&lt;li&gt;Co-training。&lt;/li&gt;
&lt;li&gt;Meta Pseudo Labels。想办法生成规则来打标签。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;在 LLM 时代，很多 synthetic data / instruction tuning 也可以看成更复杂的 pseudo-label 生成。&lt;/p&gt;
&lt;h4 id=&#34;hard-targets-和-soft-targets&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#hard-targets-和-soft-targets&#34;&gt;#&lt;/a&gt; Hard Targets 和 Soft Targets&lt;/h4&gt;
&lt;p&gt;普通监督学习通常用 hard target。&lt;/p&gt;
&lt;p&gt;&amp;lt;img src=&amp;quot;/assets/图片/image-20260428112213736.png&amp;quot; alt=&amp;quot;image-20260428112213736&amp;quot; style=&amp;quot;zoom:33%;&amp;quot; /&amp;gt;&lt;/p&gt;
&lt;p&gt;例如三分类：&lt;/p&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-text&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span&gt;真实标签 = [0, 1, 0]&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;它只告诉模型正确类别是什么。&lt;/p&gt;
&lt;p&gt;蒸馏更常用 soft target：&lt;/p&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-text&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span&gt;teacher 输出 = [0.05, 0.80, 0.15]&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;soft target 不只告诉 student 正确答案，还告诉它 teacher 对其他类别的相对判断。&lt;/p&gt;
&lt;p&gt;这包含了更多“暗知识”：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;哪些错误类别比较像正确类别。&lt;/li&gt;
&lt;li&gt;哪些类别几乎不可能。&lt;/li&gt;
&lt;li&gt;teacher 的决策边界更平滑。&lt;/li&gt;
&lt;/ul&gt;
&lt;h4 id=&#34;born-again-neural-networks&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#born-again-neural-networks&#34;&gt;#&lt;/a&gt; Born Again Neural Networks&lt;/h4&gt;
&lt;p&gt;Born Again Neural Networks 的有趣点是：student 不一定比 teacher 小。&lt;/p&gt;
&lt;p&gt;它可以训练一个和 teacher 架构一样的 student，让 student 学 teacher 的 soft targets。有时候 student 甚至能超过 teacher。&lt;/p&gt;
&lt;p&gt;这说明蒸馏不只是压缩，也可能是一种训练正则化。&lt;/p&gt;
&lt;h4 id=&#34;sequence-level-distillation&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#sequence-level-distillation&#34;&gt;#&lt;/a&gt; Sequence-Level Distillation&lt;/h4&gt;
&lt;p&gt;对于序列生成任务，只做单步 soft target 还不够，因为输出是整个序列。&lt;/p&gt;
&lt;p&gt;两种做法：&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;1. Word-level distillation&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;每个时间步都让 student 匹配 teacher 的词分布。&lt;/p&gt;
&lt;p&gt;也就是：&lt;/p&gt;
&lt;p&gt;[&lt;br /&gt;
P_{\text{student}}(y_t \mid y_{&amp;lt;t},x)&lt;br /&gt;
]&lt;/p&gt;
&lt;p&gt;去模仿：&lt;/p&gt;
&lt;p&gt;[&lt;br /&gt;
P_{\text{teacher}}(y_t \mid y_{&amp;lt;t},x)&lt;br /&gt;
]&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;2. Sequence-level distillation&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;先让 teacher 生成完整输出序列，然后 student 最大化这个 teacher-generated output 的概率。&lt;/p&gt;
&lt;p&gt;直觉：teacher 先给出“标准答案”，student 再学习生成这条答案。&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;Word-level：“老师每一步怎么选词，你都要学”&lt;/p&gt;
&lt;p&gt;Sequence-level：“老师最终写了一整句话，你直接背下来”&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h4 id=&#34;distilbert&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#distilbert&#34;&gt;#&lt;/a&gt; DistilBERT&lt;/h4&gt;
&lt;p&gt;DistilBERT 是 BERT 的蒸馏版本。特点：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;层数约为 BERT 的一半。&lt;/li&gt;
&lt;li&gt;参数量约为 BERT 的 60%。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;技巧：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;用 BERT 的交替层初始化 DistilBERT。&lt;/li&gt;
&lt;li&gt;同时使用 supervised loss 和 distillation loss。&lt;/li&gt;
&lt;li&gt;PPT 里提到 supervised loss 帮助不大。&lt;/li&gt;
&lt;li&gt;加入 teacher 和 student hidden states 的 cosine similarity loss。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;所以 DistilBERT 不只是模仿最终分类结果，还会让中间表示也接近 teacher。&lt;/p&gt;
&lt;h3 id=&#34;self-instruct-和-synthetic-data&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#self-instruct-和-synthetic-data&#34;&gt;#&lt;/a&gt; Self-Instruct 和 Synthetic Data&lt;/h3&gt;
&lt;p&gt;Self-Instruct 的思路：&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;用语言模型自己合成指令和答案，再用这些合成数据训练模型学会 follow instructions。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;这也是一种蒸馏 / 自训练：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;teacher 生成 instruction data。&lt;/li&gt;
&lt;li&gt;student 在这些 pseudo-labeled instruction data 上训练。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;后面的 Prompt2Model、Synthetic Data Generation Toolkit 也是类似方向：用大模型或提示方法生成数据，再训练更小、更专门的模型。&lt;/p&gt;
&lt;h3 id=&#34;data-efficient-fine-tuning&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#data-efficient-fine-tuning&#34;&gt;#&lt;/a&gt; Data-Efficient Fine-tuning&lt;/h3&gt;
&lt;p&gt;预训练语言模型（PLM）面临两个问题：&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;问题 1：下游任务标注数据少。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;每个任务都拿到大量人工标注数据并不现实。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;问题 2：PLM 太大，而且还在变大。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;如果每个下游任务都保存一份完整 fine-tuned 模型，成本很高。&lt;/p&gt;
&lt;p&gt;例如 BERT-base 有 110M 参数，如果 4 个任务都全量 fine-tune，就要保存 4 份 110M 参数。&lt;/p&gt;
&lt;h3 id=&#34;parameter-efficient-fine-tuning&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#parameter-efficient-fine-tuning&#34;&gt;#&lt;/a&gt; Parameter-Efficient Fine-tuning&lt;/h3&gt;
&lt;p&gt;Parameter-Efficient Fine-tuning（PEFT）的目标是：&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;冻结大部分预训练模型，只为每个任务训练少量 task-specific parameters。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;原模型 hidden representation 是：&lt;/p&gt;
&lt;p&gt;[&lt;br /&gt;
h&lt;br /&gt;
]&lt;/p&gt;
&lt;p&gt;微调后的表示可以写成：&lt;/p&gt;
&lt;p&gt;[&lt;br /&gt;
h&#39;=h+\Delta h&lt;br /&gt;
]&lt;/p&gt;
&lt;p&gt;其中 (\Delta h) 由少量新增参数产生。&lt;/p&gt;
&lt;p&gt;直觉：不要改整个大模型，只学一个小的“任务增量”。&lt;/p&gt;
&lt;h3 id=&#34;adapter&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#adapter&#34;&gt;#&lt;/a&gt; Adapter&lt;/h3&gt;
&lt;p&gt;Adapter 是 PEFT 的经典方法。&lt;/p&gt;
&lt;p&gt;做法是在 Transformer layer 内部插入小模块：&lt;/p&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-text&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span&gt;hidden representation h&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;        ↓&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;down-project&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;        ↓&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;nonlinearity&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;        ↓&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;up-project&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;        ↓&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;加回原表示&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;也就是：&lt;/p&gt;
&lt;p&gt;[&lt;br /&gt;
h&#39;=h+\Delta h&lt;br /&gt;
]&lt;/p&gt;
&lt;p&gt;训练时：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;原 Transformer 参数冻结。&lt;/li&gt;
&lt;li&gt;只更新 Adapter 参数。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;优点：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;每个任务只需要存一小份 Adapter。&lt;/li&gt;
&lt;li&gt;原模型可以共享。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;缺点：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;推理时多了额外模块，可能有一点延迟。&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;lora&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#lora&#34;&gt;#&lt;/a&gt; LoRA&lt;/h3&gt;
&lt;p&gt;LoRA 全称是 &lt;strong&gt;Low-Rank Adaptation&lt;/strong&gt;。&lt;/p&gt;
&lt;p&gt;它的核心思想是：不要直接更新原来的大矩阵 (W)，而是给它加一个低秩增量：&lt;/p&gt;
&lt;p&gt;[&lt;br /&gt;
W&#39; = W + \Delta W&lt;br /&gt;
]&lt;/p&gt;
&lt;p&gt;其中：&lt;/p&gt;
&lt;p&gt;[&lt;br /&gt;
\Delta W = BA&lt;br /&gt;
]&lt;/p&gt;
&lt;p&gt;如果原矩阵很大，比如：&lt;/p&gt;
&lt;p&gt;[&lt;br /&gt;
W \in \mathbb&lt;ruby&gt;R}&lt;rp&gt;(&lt;/rp&gt;&lt;rt&gt;{d_{\text{out&lt;/rt&gt;&lt;rp&gt;)&lt;/rp&gt;&lt;/ruby&gt;}\times d_{\text{in}}}&lt;br /&gt;
]&lt;/p&gt;
&lt;p&gt;LoRA 用两个小矩阵：&lt;/p&gt;
&lt;p&gt;[&lt;br /&gt;
A \in \mathbb&lt;ruby&gt;R}&lt;rp&gt;(&lt;/rp&gt;&lt;rt&gt;{r\times d_{\text{in&lt;/rt&gt;&lt;rp&gt;)&lt;/rp&gt;&lt;/ruby&gt;}},\quad B \in \mathbb&lt;ruby&gt;R}&lt;rp&gt;(&lt;/rp&gt;&lt;rt&gt;{d_{\text{out&lt;/rt&gt;&lt;rp&gt;)&lt;/rp&gt;&lt;/ruby&gt;}\times r}&lt;br /&gt;
]&lt;/p&gt;
&lt;p&gt;其中 (r) 很小。&lt;/p&gt;
&lt;p&gt;参数量从：&lt;/p&gt;
&lt;p&gt;[&lt;br /&gt;
d_{\text{out}}\times d_{\text{in}}&lt;br /&gt;
]&lt;/p&gt;
&lt;p&gt;变成：&lt;/p&gt;
&lt;p&gt;[&lt;br /&gt;
r(d_{\text{out}}+d_{\text{in}})&lt;br /&gt;
]&lt;/p&gt;
&lt;p&gt;训练时：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;冻结原始 (W)。&lt;/li&gt;
&lt;li&gt;只训练 (A,B)。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;直觉：任务适配需要的变化可能本来就是低秩的，所以不必更新整个大矩阵。&lt;/p&gt;
&lt;h3 id=&#34;prefix-tuning-和-prompt-tuning&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#prefix-tuning-和-prompt-tuning&#34;&gt;#&lt;/a&gt; Prefix Tuning 和 Prompt Tuning&lt;/h3&gt;
&lt;p&gt;这两类方法都冻结 Transformer 主体参数，优化 prompt 相关参数。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Prompt Tuning&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;只优化输入层的 soft prompt embedding。&lt;/p&gt;
&lt;p&gt;注意这里优化的不是自然语言词本身，而是一组可训练向量。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Prefix Tuning&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;优化每一层的 prefix 表示，相当于在每层 attention 前都加一段可训练上下文。&lt;/p&gt;
&lt;p&gt;区别：&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;方法&lt;/th&gt;
&lt;th&gt;优化哪里&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;Prompt Tuning&lt;/td&gt;
&lt;td&gt;只优化 embedding layer 的 prompt 向量&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Prefix Tuning&lt;/td&gt;
&lt;td&gt;优化所有层的 prefix&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;h3 id=&#34;prompt-tuning-做分类&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#prompt-tuning-做分类&#34;&gt;#&lt;/a&gt; Prompt Tuning 做分类&lt;/h3&gt;
&lt;p&gt;标准 fine-tuning 做分类通常是：&lt;/p&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-text&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span&gt;[CLS] Premise [SEP] Hypothesis&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;        ↓&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;BERT&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;        ↓&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;Classifier Head&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;Prompt tuning 会把任务改造成完形填空：&lt;/p&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-text&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span&gt;Premise ? [MASK], Hypothesis&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;然后用 LM Head 预测 &lt;code&gt;[MASK]&lt;/code&gt;。&lt;/p&gt;
&lt;p&gt;比如自然语言推理中，可以把 label 映射成 verbalizer：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;entailment -&amp;gt; yes / true。&lt;/li&gt;
&lt;li&gt;neutral -&amp;gt; maybe / inconclusive。&lt;/li&gt;
&lt;li&gt;contradiction -&amp;gt; no / false。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;优点：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;复用预训练时的 MLM 形式。&lt;/li&gt;
&lt;li&gt;在数据很少时可以注入人工设计的任务知识。&lt;/li&gt;
&lt;li&gt;可能不需要新增分类头。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;PPT 中强调：在数据稀缺时，prompt tuning 往往更好，因为它：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;incorporates human knowledge。&lt;/li&gt;
&lt;li&gt;introduces no new parameters。&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;peft-的好处&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#peft-的好处&#34;&gt;#&lt;/a&gt; PEFT 的好处&lt;/h3&gt;
&lt;p&gt;&lt;strong&gt;Benefit 1：大幅减少 task-specific parameters。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;多个任务共享同一个大模型，每个任务只保存少量 Adapter / LoRA / prompt 参数。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Benefit 2：不容易在训练数据上过拟合，OOD 表现可能更好。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;因为可训练参数少，模型不太容易把小训练集记死。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Benefit 3：适合小数据训练。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;下游数据很少时，更新全部参数风险很高；只调少量参数更稳定。&lt;/p&gt;
&lt;h3 id=&#34;early-exit&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#early-exit&#34;&gt;#&lt;/a&gt; Early Exit&lt;/h3&gt;
&lt;p&gt;Early Exit 是另一种提高推理效率的方法。&lt;/p&gt;
&lt;p&gt;做法：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;在每一层或若干层后面加 classifier head。&lt;/li&gt;
&lt;li&gt;推理时不一定跑完整个模型。&lt;/li&gt;
&lt;li&gt;如果中间某层已经足够 confident，就提前输出。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;例如输入：&lt;/p&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-text&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span&gt;This movie is crap ...&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;模型经过前几层后，如果分类器已经很确定是负面情感，就不用继续跑后面的 Transformer layer。&lt;/p&gt;
&lt;p&gt;优点：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;减少平均推理时间。&lt;/li&gt;
&lt;li&gt;简单样本可以早退出。&lt;/li&gt;
&lt;li&gt;尽量保持整体性能。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;风险：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;退出太早可能影响准确率。&lt;/li&gt;
&lt;li&gt;需要设计 confidence predictor / threshold。&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;prompting-methods-的训练策略&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#prompting-methods-的训练策略&#34;&gt;#&lt;/a&gt; Prompting Methods 的训练策略&lt;/h3&gt;
&lt;p&gt;可以从两个角度看 prompting 方法。&lt;/p&gt;
&lt;h4 id=&#34;data-perspective&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#data-perspective&#34;&gt;#&lt;/a&gt; Data Perspective&lt;/h4&gt;
&lt;p&gt;看下游任务用了多少训练样本：&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;类型&lt;/th&gt;
&lt;th&gt;含义&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;Zero-shot&lt;/td&gt;
&lt;td&gt;不用显式下游训练样本&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Few-shot&lt;/td&gt;
&lt;td&gt;只有少量样本，例如 1-100&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Full-data&lt;/td&gt;
&lt;td&gt;有大量样本，例如 10K&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;h4 id=&#34;parameter-perspective&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#parameter-perspective&#34;&gt;#&lt;/a&gt; Parameter Perspective&lt;/h4&gt;
&lt;p&gt;看参数是否更新，以及更新哪些参数：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Tuning-free Prompting&lt;/strong&gt;：不更新模型，只写 prompt。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Fixed-LM Prompt Tuning&lt;/strong&gt;：冻结 LM，只调 prompt 参数。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Prompt + LM Fine-tuning&lt;/strong&gt;：prompt 和 LM 都调。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Promptless Fine-tuning&lt;/strong&gt;：不用 prompt，直接标准 fine-tune。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Fixed-Prompt Tuning&lt;/strong&gt;：prompt 固定，只调模型或任务头。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;PPT 最后给的选择直觉：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;如果有超大预训练模型，比如 GPT-3，可以优先考虑 tuning-free prompting。&lt;/li&gt;
&lt;li&gt;如果训练样本很少，可以考虑 prompt tuning / PEFT。&lt;/li&gt;
&lt;li&gt;如果训练样本很多，标准 fine-tuning 或 prompt + LM fine-tuning 也可行。&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;semi-supervised-learning&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#semi-supervised-learning&#34;&gt;#&lt;/a&gt; Semi-supervised Learning&lt;/h3&gt;
&lt;p&gt;半监督学习的设定：&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;有少量 labeled data，同时有大量 unlabeled data。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;目标是利用无标注数据提升模型。&lt;/p&gt;
&lt;h3 id=&#34;pattern-exploiting-trainingpet&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#pattern-exploiting-trainingpet&#34;&gt;#&lt;/a&gt; Pattern-Exploiting Training（PET）&lt;/h3&gt;
&lt;p&gt;PET 是 prompt tuning + semi-supervised learning 的代表方法。&lt;/p&gt;
&lt;p&gt;它把分类任务转成 cloze-style prompt，然后用 verbalizer 把 &lt;code&gt;[MASK]&lt;/code&gt; 的词映射回类别。&lt;/p&gt;
&lt;p&gt;例如 NLI：&lt;/p&gt;
&lt;p&gt;Prompt 1：&lt;/p&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-text&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span&gt;Premise ? [MASK], Hypothesis&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;verbalizer：&lt;/p&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-text&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span&gt;yes / maybe / no&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;Prompt 2：&lt;/p&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-text&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span&gt;&#34;Premise&#34;? [MASK]. &#34;Hypothesis&#34;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;verbalizer：&lt;/p&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-text&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span&gt;true / inconclusive / false&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;h4 id=&#34;pet-step-1&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#pet-step-1&#34;&gt;#&lt;/a&gt; PET Step 1&lt;/h4&gt;
&lt;p&gt;使用不同 prompt 和 verbalizer，在 labeled dataset 上 prompt-tune 多个 PLM。&lt;/p&gt;
&lt;p&gt;也就是训练多个不同视角的模型。&lt;/p&gt;
&lt;h4 id=&#34;pet-step-2&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#pet-step-2&#34;&gt;#&lt;/a&gt; PET Step 2&lt;/h4&gt;
&lt;p&gt;用这些模型去预测 unlabeled dataset。&lt;/p&gt;
&lt;p&gt;然后组合不同模型的预测，得到 soft label。&lt;/p&gt;
&lt;h4 id=&#34;pet-step-3&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#pet-step-3&#34;&gt;#&lt;/a&gt; PET Step 3&lt;/h4&gt;
&lt;p&gt;用原本无标注、现在带 soft label 的数据，训练一个带 classifier head 的 PLM。&lt;/p&gt;
&lt;p&gt;所以 PET 的流程是：&lt;/p&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-text&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span&gt;少量标注数据&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;    ↓&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;多个 prompt/verbalizer 模型&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;    ↓&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;预测大量无标注数据&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;    ↓&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;组合成 soft labels&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;    ↓&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;训练最终分类模型&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;它利用了：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;prompt 的任务知识。&lt;/li&gt;
&lt;li&gt;多 prompt 集成的稳定性。&lt;/li&gt;
&lt;li&gt;大量无标注数据。&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;lecture-10&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#lecture-10&#34;&gt;#&lt;/a&gt; lecture 10&lt;/h2&gt;
&lt;blockquote&gt;
&lt;p&gt;深度强化学习&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;强化学习在16、17年是非常热门的一个点，deepmind公司的成名就由于deepmind。&lt;/p&gt;
&lt;p&gt;在机器学习中，强化学习的地位。&lt;/p&gt;
&lt;p&gt;&amp;lt;img src=&amp;quot;/assets/图片/image-20260512103201801.png&amp;quot; alt=&amp;quot;image-20260512103201801&amp;quot; style=&amp;quot;zoom: 33%;&amp;quot; /&amp;gt;&lt;/p&gt;
&lt;p&gt;老师不告诉你哪里错了，只是告诉你考了多少分，然后自己去学习。这个反馈信号是很稀疏的。Agent最早的概念就是在强化学习中出现的，我们人也是强化学习。&lt;/p&gt;
&lt;h3 id=&#34;强化学习简介&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#强化学习简介&#34;&gt;#&lt;/a&gt; 强化学习简介&lt;/h3&gt;
&lt;p&gt;个体如何在环境给予的奖励或惩罚的刺激(Reward -- r)下，逐步形成对刺激的预期，产生能获得最大利益的习惯性行为(Actions -- a)。&lt;/p&gt;
&lt;p&gt;&amp;lt;img src=&amp;quot;/assets/图片/image-20260512104448509.png&amp;quot; alt=&amp;quot;image-20260512104448509&amp;quot; style=&amp;quot;zoom:50%;&amp;quot; /&amp;gt;&lt;/p&gt;
&lt;p&gt;Agent的名词就是这么来的（上面那个大脑）&lt;/p&gt;
&lt;h3 id=&#34;基本构成&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#基本构成&#34;&gt;#&lt;/a&gt; 基本构成&lt;/h3&gt;
&lt;p&gt;&lt;strong&gt;Experience（经验）&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;强化学习中，智能体不断与环境交互：&lt;/p&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-text&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span&gt;observation → action → reward&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;经验（Experience）是一系列历史记录：&lt;/p&gt;
&lt;p&gt;&lt;span class=&#34;katex-display&#34;&gt;&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34; display=&#34;block&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;msub&gt;&lt;mi&gt;o&lt;/mi&gt;&lt;mn&gt;1&lt;/mn&gt;&lt;/msub&gt;&lt;mo separator=&#34;true&#34;&gt;,&lt;/mo&gt;&lt;msub&gt;&lt;mi&gt;r&lt;/mi&gt;&lt;mn&gt;1&lt;/mn&gt;&lt;/msub&gt;&lt;mo separator=&#34;true&#34;&gt;,&lt;/mo&gt;&lt;msub&gt;&lt;mi&gt;a&lt;/mi&gt;&lt;mn&gt;1&lt;/mn&gt;&lt;/msub&gt;&lt;mo separator=&#34;true&#34;&gt;,&lt;/mo&gt;&lt;mo&gt;…&lt;/mo&gt;&lt;mo separator=&#34;true&#34;&gt;,&lt;/mo&gt;&lt;msub&gt;&lt;mi&gt;a&lt;/mi&gt;&lt;mrow&gt;&lt;mi&gt;t&lt;/mi&gt;&lt;mo&gt;−&lt;/mo&gt;&lt;mn&gt;1&lt;/mn&gt;&lt;/mrow&gt;&lt;/msub&gt;&lt;mo separator=&#34;true&#34;&gt;,&lt;/mo&gt;&lt;msub&gt;&lt;mi&gt;o&lt;/mi&gt;&lt;mi&gt;t&lt;/mi&gt;&lt;/msub&gt;&lt;mo separator=&#34;true&#34;&gt;,&lt;/mo&gt;&lt;msub&gt;&lt;mi&gt;r&lt;/mi&gt;&lt;mi&gt;t&lt;/mi&gt;&lt;/msub&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;o_1,r_1,a_1,\dots,a_{t-1},o_t,r_t
&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6389em;vertical-align:-0.2083em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;o&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.3011em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:0em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;1&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mpunct&#34;&gt;,&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.1667em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.02778em;&#34;&gt;r&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.3011em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;1&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mpunct&#34;&gt;,&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.1667em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;a&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.3011em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:0em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;1&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mpunct&#34;&gt;,&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.1667em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;minner&#34;&gt;…&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.1667em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mpunct&#34;&gt;,&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.1667em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;a&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.3011em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:0em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;t&lt;/span&gt;&lt;span class=&#34;mbin mtight&#34;&gt;−&lt;/span&gt;&lt;span class=&#34;mord mtight&#34;&gt;1&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.2083em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mpunct&#34;&gt;,&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.1667em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;o&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.2806em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:0em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;t&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mpunct&#34;&gt;,&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.1667em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.02778em;&#34;&gt;r&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.2806em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;t&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;其中：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;msub&gt;&lt;mi&gt;o&lt;/mi&gt;&lt;mi&gt;t&lt;/mi&gt;&lt;/msub&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;o_t&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.5806em;vertical-align:-0.15em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;o&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.2806em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:0em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;t&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;：observation，环境观察&lt;/li&gt;
&lt;li&gt;&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;msub&gt;&lt;mi&gt;a&lt;/mi&gt;&lt;mi&gt;t&lt;/mi&gt;&lt;/msub&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;a_t&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.5806em;vertical-align:-0.15em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;a&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.2806em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:0em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;t&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;：action，动作&lt;/li&gt;
&lt;li&gt;&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;msub&gt;&lt;mi&gt;r&lt;/mi&gt;&lt;mi&gt;t&lt;/mi&gt;&lt;/msub&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;r_t&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.5806em;vertical-align:-0.15em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.02778em;&#34;&gt;r&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.2806em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;t&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;：reward，奖励&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;State（状态）&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;状态是对历史经验的总结：&lt;/p&gt;
&lt;p&gt;&lt;span class=&#34;katex-display&#34;&gt;&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34; display=&#34;block&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;msub&gt;&lt;mi&gt;S&lt;/mi&gt;&lt;mi&gt;t&lt;/mi&gt;&lt;/msub&gt;&lt;mo&gt;=&lt;/mo&gt;&lt;mi&gt;f&lt;/mi&gt;&lt;mo stretchy=&#34;false&#34;&gt;(&lt;/mo&gt;&lt;msub&gt;&lt;mi&gt;o&lt;/mi&gt;&lt;mn&gt;1&lt;/mn&gt;&lt;/msub&gt;&lt;mo separator=&#34;true&#34;&gt;,&lt;/mo&gt;&lt;msub&gt;&lt;mi&gt;r&lt;/mi&gt;&lt;mn&gt;1&lt;/mn&gt;&lt;/msub&gt;&lt;mo separator=&#34;true&#34;&gt;,&lt;/mo&gt;&lt;msub&gt;&lt;mi&gt;a&lt;/mi&gt;&lt;mn&gt;1&lt;/mn&gt;&lt;/msub&gt;&lt;mo separator=&#34;true&#34;&gt;,&lt;/mo&gt;&lt;mo&gt;…&lt;/mo&gt;&lt;mo separator=&#34;true&#34;&gt;,&lt;/mo&gt;&lt;msub&gt;&lt;mi&gt;a&lt;/mi&gt;&lt;mrow&gt;&lt;mi&gt;t&lt;/mi&gt;&lt;mo&gt;−&lt;/mo&gt;&lt;mn&gt;1&lt;/mn&gt;&lt;/mrow&gt;&lt;/msub&gt;&lt;mo separator=&#34;true&#34;&gt;,&lt;/mo&gt;&lt;msub&gt;&lt;mi&gt;o&lt;/mi&gt;&lt;mi&gt;t&lt;/mi&gt;&lt;/msub&gt;&lt;mo separator=&#34;true&#34;&gt;,&lt;/mo&gt;&lt;msub&gt;&lt;mi&gt;r&lt;/mi&gt;&lt;mi&gt;t&lt;/mi&gt;&lt;/msub&gt;&lt;mo stretchy=&#34;false&#34;&gt;)&lt;/mo&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;S_t=f(o_1,r_1,a_1,\dots,a_{t-1},o_t,r_t)
&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.8333em;vertical-align:-0.15em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.05764em;&#34;&gt;S&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.2806em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;t&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1em;vertical-align:-0.25em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.10764em;&#34;&gt;f&lt;/span&gt;&lt;span class=&#34;mopen&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;o&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.3011em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:0em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;1&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mpunct&#34;&gt;,&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.1667em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.02778em;&#34;&gt;r&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.3011em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;1&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mpunct&#34;&gt;,&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.1667em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;a&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.3011em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:0em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;1&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mpunct&#34;&gt;,&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.1667em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;minner&#34;&gt;…&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.1667em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mpunct&#34;&gt;,&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.1667em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;a&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.3011em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:0em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;t&lt;/span&gt;&lt;span class=&#34;mbin mtight&#34;&gt;−&lt;/span&gt;&lt;span class=&#34;mord mtight&#34;&gt;1&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.2083em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mpunct&#34;&gt;,&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.1667em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;o&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.2806em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:0em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;t&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mpunct&#34;&gt;,&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.1667em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.02778em;&#34;&gt;r&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.2806em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;t&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mclose&#34;&gt;)&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;即：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;不一定保存全部历史&lt;/li&gt;
&lt;li&gt;而是提取“对决策有用的信息”&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;核心：&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;state 是 experience 的压缩表示。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h3 id=&#34;q-learning&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#q-learning&#34;&gt;#&lt;/a&gt; Q-Learning&lt;/h3&gt;
&lt;p&gt;&lt;strong&gt;Q-Learning 是什么&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Q-Learning 是一种基于价值的强化学习方法。&lt;/p&gt;
&lt;p&gt;核心思想：学习在某个状态下执行某个动作的长期价值。&lt;/p&gt;
&lt;p&gt;也就是学习：$$&lt;br /&gt;
Q(s,a)&lt;/p&gt;
，其中：

- $s$：状态
- $a$：动作
- $Q(s,a)$：在状态 $s$ 下执行动作 $a$ 的价值

**Q 值的含义**

&lt;p&gt;Q^\pi(s,a)=E[r_&lt;ruby&gt;t+1}+\gamma r_{t+2}+\gamma&lt;rp&gt;(&lt;/rp&gt;&lt;rt&gt;2r_{t+3&lt;/rt&gt;&lt;rp&gt;)&lt;/rp&gt;&lt;/ruby&gt;+\cdots]&lt;/p&gt;
含义是：在状态 $s$ 下执行动作 $a$，之后按照策略 $\pi$ 行动，未来能获得的累计奖励期望。

**折扣因子 $\gamma$**

$\gamma$ 是 discount factor，取值范围一般是：

&lt;p&gt;0 \leq \gamma \leq 1&lt;/p&gt;
它表示未来奖励的重要程度。$\gamma$ 越大，越重视长期收益；$\gamma$ 越小，越重视眼前收益。

**Bellman Equation**

&lt;p&gt;Q^\pi(s,a)=E[r+\gamma Q^\pi(s&#39;,a&#39;)]&lt;/p&gt;
&lt;p&gt;&lt;span class=&#34;katex-display&#34;&gt;&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34; display=&#34;block&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mtext&gt;含义：&lt;/mtext&gt;&lt;mo&gt;&amp;gt;&lt;/mo&gt;&lt;mtext&gt;当前价值&lt;/mtext&gt;&lt;mo&gt;=&lt;/mo&gt;&lt;mtext&gt;当前奖励&lt;/mtext&gt;&lt;mo&gt;+&lt;/mo&gt;&lt;mtext&gt;下一状态的未来价值这是&lt;/mtext&gt;&lt;mi&gt;Q&lt;/mi&gt;&lt;mo&gt;−&lt;/mo&gt;&lt;mi&gt;L&lt;/mi&gt;&lt;mi&gt;e&lt;/mi&gt;&lt;mi&gt;a&lt;/mi&gt;&lt;mi&gt;r&lt;/mi&gt;&lt;mi&gt;n&lt;/mi&gt;&lt;mi&gt;i&lt;/mi&gt;&lt;mi&gt;n&lt;/mi&gt;&lt;mi&gt;g&lt;/mi&gt;&lt;mtext&gt;更新的理论基础。&lt;/mtext&gt;&lt;mo&gt;∗&lt;/mo&gt;&lt;mo&gt;∗&lt;/mo&gt;&lt;mtext&gt;最优&lt;/mtext&gt;&lt;mi&gt;Q&lt;/mi&gt;&lt;mtext&gt;函数&lt;/mtext&gt;&lt;mo&gt;∗&lt;/mo&gt;&lt;mo&gt;∗&lt;/mo&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;
含义：

&amp;gt; 当前价值 = 当前奖励 + 下一状态的未来价值

这是 Q-Learning 更新的理论基础。

**最优 Q 函数**

&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.7224em;vertical-align:-0.0391em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord cjk_fallback&#34;&gt;含义：&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;&amp;gt;&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord cjk_fallback&#34;&gt;当前价值&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.7667em;vertical-align:-0.0833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord cjk_fallback&#34;&gt;当前奖励&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mbin&#34;&gt;+&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.8778em;vertical-align:-0.1944em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord cjk_fallback&#34;&gt;下一状态的未来价值这是&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;Q&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mbin&#34;&gt;−&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.8778em;vertical-align:-0.1944em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;L&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;e&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;a&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.02778em;&#34;&gt;r&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;nin&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.03588em;&#34;&gt;g&lt;/span&gt;&lt;span class=&#34;mord cjk_fallback&#34;&gt;更新的理论基础。&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mbin&#34;&gt;∗&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.8778em;vertical-align:-0.1944em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;∗&lt;/span&gt;&lt;span class=&#34;mord cjk_fallback&#34;&gt;最优&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;Q&lt;/span&gt;&lt;span class=&#34;mord cjk_fallback&#34;&gt;函数&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mbin&#34;&gt;∗&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.4653em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;∗&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;Q^*(s,a)=\max_\pi Q^\pi(s,a)&lt;/p&gt;
&lt;p&gt;&lt;span class=&#34;katex-display&#34;&gt;&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34; display=&#34;block&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mtext&gt;表示所有策略中能达到的最大价值。最优策略为：&lt;/mtext&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;
表示所有策略中能达到的最大价值。

最优策略为：
&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord cjk_fallback&#34;&gt;表示所有策略中能达到的最大价值。最优策略为：&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;\pi^&lt;em&gt;(s)=\arg\max_a Q^&lt;/em&gt;(s,a)&lt;/p&gt;
&lt;p&gt;&lt;span class=&#34;katex-display&#34;&gt;&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34; display=&#34;block&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mtext&gt;也就是在当前状态下选择&lt;/mtext&gt;&lt;mi&gt;Q&lt;/mi&gt;&lt;mtext&gt;值最大的动作。&lt;/mtext&gt;&lt;mo&gt;∗&lt;/mo&gt;&lt;mo&gt;∗&lt;/mo&gt;&lt;mi&gt;Q&lt;/mi&gt;&lt;mo&gt;−&lt;/mo&gt;&lt;mi&gt;L&lt;/mi&gt;&lt;mi&gt;e&lt;/mi&gt;&lt;mi&gt;a&lt;/mi&gt;&lt;mi&gt;r&lt;/mi&gt;&lt;mi&gt;n&lt;/mi&gt;&lt;mi&gt;i&lt;/mi&gt;&lt;mi&gt;n&lt;/mi&gt;&lt;mi&gt;g&lt;/mi&gt;&lt;mtext&gt;更新公式&lt;/mtext&gt;&lt;mo&gt;∗&lt;/mo&gt;&lt;mo&gt;∗&lt;/mo&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;也就是在当前状态下选择 Q 值最大的动作。

**Q-Learning 更新公式**

&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.8778em;vertical-align:-0.1944em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord cjk_fallback&#34;&gt;也就是在当前状态下选择&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;Q&lt;/span&gt;&lt;span class=&#34;mord cjk_fallback&#34;&gt;值最大的动作。&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mbin&#34;&gt;∗&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.8778em;vertical-align:-0.1944em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;∗&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;Q&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mbin&#34;&gt;−&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.8778em;vertical-align:-0.1944em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;L&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;e&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;a&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.02778em;&#34;&gt;r&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;nin&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.03588em;&#34;&gt;g&lt;/span&gt;&lt;span class=&#34;mord cjk_fallback&#34;&gt;更新公式&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mbin&#34;&gt;∗&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.4653em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;∗&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;Q_{t+1}(s_t,a_t)=&lt;br /&gt;
Q_t(s_t,a_t) + \alpha \left[ R_{t+1} + \gamma \max_a Q_t(s_{t+1},a)-&lt;br /&gt;
Q_t(s_t,a_t)&lt;br /&gt;
\right]&lt;/p&gt;

可以理解为：

&gt; 新 Q 值 = 旧 Q 值 + 学习率 × 误差修正

其中：

- $\alpha$：learning rate，学习率
- $R_{t+1}$：执行动作后得到的奖励
- $\gamma$：折扣因子
- $\max_a Q_t(s_{t+1},a)$：下一状态下能取得的最大 Q 值

**Q 表**

Q-Learning 通常用一个表来存储 Q 值：

| State | A1   | A2   | A3   |
| ----- | ---- | ---- | ---- |
| S1    | 1    | 2    | -1   |
| S2    | 0    | 3    | 1    |

行表示状态，列表示动作，表中的数值就是对应的 Q 值。

决策时，选择当前状态下 Q 值最大的动作。

Q-Learning 的本质是：

&gt; 通过不断试错，根据奖励更新状态-动作价值，最终学会在每个状态下选择最优动作。



### DQN

&gt;Deepmind公司做出来的深度强化学习 

人们很早就试图结合起来，但是这个强化学习当时只是在控制上使用，因为是维度灾难。从采样来估计、调整分布，每一步依赖上一步，所以一个词一个词变，但是这种方法太慢了。

在 DQN 出现之前，传统强化学习，尤其是 **Q-learning**，虽然理论上可以让智能体通过试错学习策略，但在实际复杂任务里遇到了瓶颈。核心问题是：**状态空间太大、太复杂**。

在DQN之前，直接用深度神经网络（DNN）来拟合Q-learning极不稳定，主要有三大原因：

- **尺度问题（梯度消失/爆炸）：** Reward（奖励）和 Q-value 的大小范围未知且不可控，直接输入神经网络会导致反向传播时梯度计算失败。
- **数据相关性太强：** 强化学习通常是按时间顺序输入连续的数据（如连续的视频帧图像），这些数据之间差异极小且**强相关**，违背了深度学习要求数据独立同分布（i.i.d）的假设，容易导致网络“陷入局部最优”或错误收敛。
- **目标不断移动（牵一发而动全身）：** Q-value 极其微小的变化，可能会导致策略（Policy）发生剧烈变动，在两个极端之间来回震荡，无法稳定学习。

比如玩 Atari 游戏时，智能体看到的不是几个简单数字，而是一帧帧游戏画面。画面里有像素、物体、位置、速度等大量信息。如果还像传统 Q-learning 那样手工设计状态特征，就会非常困难。所以页中引用 Nature 论文的话，大意是：

&gt; 过去强化学习能成功的场景，往往依赖人工设计好的特征，或者状态空间本身比较低维、完全可观测。

也就是说，之前的强化学习更适合这种情况：

```
状态比较简单 → 人能设计特征 → Q-learning 可以学
```

但面对游戏画面这种高维输入时，就很难了。

#### 基本思想

**DQN 的基本思想**就是把 **深度神经网络** 和 **Q-learning** 结合起来。

传统 Q-learning 要学习的是一个 Q 表：

```
Q(s, a)
```

意思是：在状态 `s` 下采取动作 `a`，未来大概能获得多少累计奖励。

但是状态很多时，Q 表根本存不下，也没法穷举。所以 DQN 用一个神经网络来近似 Q 函数：

```
输入：游戏画面 / 状态 s
输出：每个动作对应的 Q 值
```

比如输入一张游戏画面，网络输出：

```
向上：3.2
向下：1.5
向左：0.8
向右：5.6
开火：4.1
```

那智能体就会选择 Q 值最大的动作，比如“向右”。

&lt;img loading=&#34;lazy&#34; src=&#34;/assets/图片/image-20260514164209212.png&#34; alt=&#34;image-20260514164209212&#34; style=&#34;zoom: 33%;&#34; /&gt;

#### DeepMind 的解决方案

针对上述痛点，DeepMind 提出了三个关键机制来稳定训练过程：

1. **Reward Clipping (奖励截断) / 归一化：**针对痛点1。将所有的 Reward 限制在一个固定的合理范围内（例如统一定义为 -1, 0, 1），或者自适应归一化，从而稳定梯度的反向传播。
2. **Experience Replay (经验回放机制)：**针对痛点2。构建一个“经验池”，将智能体探索环境产生的数据 `(s,a,r,s′)(s,a,r,s′)` 存起来。训练时，**打乱顺序随机抽取**一小批（mini-batch）数据进行学习。这打破了连续数据间的强相关性，让数据更符合独立同分布。*(此项技术在他们早期的 NIPS 论文中首次引入)*
3. **Freeze Target Q-network (冻结目标网络/固定Q目标)：**针对痛点3。使用两个结构一样的神经网络。一个**当前网络**（参数不断更新），一个**目标网络**（参数冻结，每隔一段时间才把当前网络的参数同步给它）。这使得计算目标值时有一个相对稳定的参照物，防止策略剧烈抖动。*(此项是 Nature 论文的关键创新)*



## lecture 11

### Policy-based RL

基于策略的强化学习。什么是策略呢，就是一个人的行动轨迹。

加入你的目标是成为一个好人，我们让你不带着记忆投胎转世100次，把100次中做的好的轨迹概率提升，这样就让你尽量变成一个好人。

所以建立一个状态空间到行动空间的映射。

![image-20260519102450727](/assets/图片/image-20260519102450727.png)

确定策略和随即策略。

比如说玩游戏，每局游戏按照结果打分。我们的目标是最大化这个分数，所以我们可以用梯度上升。所以我们对模型的参数求偏导，提升得100分的轨迹的概率，降低得低分的游戏的概率。

### A3C

Asynchronous Advantage Actor-Critic，中文可以翻成：**异步优势 Actor-Critic 算法**。

它属于 **Value + Policy** 方法，也就是同时结合：

**Policy / Actor：负责选动作**

&lt;p&gt;\pi(a|s)&lt;/p&gt;
&lt;p&gt;&lt;span class=&#34;katex-display&#34;&gt;&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34; display=&#34;block&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mo&gt;∗&lt;/mo&gt;&lt;mo&gt;∗&lt;/mo&gt;&lt;mi&gt;V&lt;/mi&gt;&lt;mi&gt;a&lt;/mi&gt;&lt;mi&gt;l&lt;/mi&gt;&lt;mi&gt;u&lt;/mi&gt;&lt;mi&gt;e&lt;/mi&gt;&lt;mi mathvariant=&#34;normal&#34;&gt;/&lt;/mi&gt;&lt;mi&gt;C&lt;/mi&gt;&lt;mi&gt;r&lt;/mi&gt;&lt;mi&gt;i&lt;/mi&gt;&lt;mi&gt;t&lt;/mi&gt;&lt;mi&gt;i&lt;/mi&gt;&lt;mi&gt;c&lt;/mi&gt;&lt;mtext&gt;：负责评价状态或动作好坏&lt;/mtext&gt;&lt;mo&gt;∗&lt;/mo&gt;&lt;mo&gt;∗&lt;/mo&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;**Value / Critic：负责评价状态或动作好坏**
&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.4653em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;∗&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mbin&#34;&gt;∗&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1em;vertical-align:-0.25em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;Va&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.01968em;&#34;&gt;l&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;u&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;e&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;/&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.07153em;&#34;&gt;C&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.02778em;&#34;&gt;r&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;i&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;t&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;i&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;c&lt;/span&gt;&lt;span class=&#34;mord cjk_fallback&#34;&gt;：负责评价状态或动作好坏&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mbin&#34;&gt;∗&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.4653em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;∗&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;V^\pi(s)&lt;/p&gt;

| 角色   | 作用     | 输入     | 输出                |
| ------ | -------- | -------- | ------------------- |
| Actor  | 负责行动 | 状态 $s$ | 动作 $a$ 或动作概率 |
| Critic | 负责评价 | 状态 $s$ | 价值 $V^\pi(s)$     |

这个优化目标/奖励也在不断变化。比如我们人生中的目标也不断改变、事业结婚生子。

我们可以用temporal-Difference approach。我们一般估计的价值可以通过一局游戏结束来评估，但是效率太低。

#### MC

**MC 一般就是 Monte Carlo，蒙特卡洛方法**。在强化学习里，**MC 估计 $V^\pi(s)$** 的意思是：

&gt; 从状态 $s$ 开始，按照策略 $\pi$ 一直玩到这一局结束，然后把后面实际拿到的奖励加起来，用这个真实回报来估计 $V^\pi(s)$。

比如一条轨迹是：

&lt;p&gt;s_t,a_t,r_t,s_{t+1},a_{t+1},r_{t+1},\cdots,s_T&lt;/p&gt;
那么从 $s_t$ 开始的回报是：

&lt;p&gt;G_t = r_t + r_{t+1} + r_{t+2}+\cdots+r_T&lt;/p&gt;
&lt;p&gt;&lt;span class=&#34;katex-display&#34;&gt;&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34; display=&#34;block&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mtext&gt;如果考虑折扣因子：&lt;/mtext&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;如果考虑折扣因子：
&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord cjk_fallback&#34;&gt;如果考虑折扣因子：&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;G_t = r_t+\gamma r_&lt;ruby&gt;t+1}+\gamma&lt;rp&gt;(&lt;/rp&gt;&lt;rt&gt;2 r_{t+2&lt;/rt&gt;&lt;rp&gt;)&lt;/rp&gt;&lt;/ruby&gt;+\cdots&lt;/p&gt;
&lt;p&gt;&lt;span class=&#34;katex-display&#34;&gt;&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34; display=&#34;block&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mtext&gt;然后用很多次采样的平均值估计：&lt;/mtext&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;然后用很多次采样的平均值估计：
&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord cjk_fallback&#34;&gt;然后用很多次采样的平均值估计：&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p N=&#34;&#34;&gt;V^\pi(s_t) \approx \frac&lt;ruby&gt;G_t&lt;rp&gt;(&lt;/rp&gt;&lt;rt&gt;{(1)&lt;/rt&gt;&lt;rp&gt;)&lt;/rp&gt;&lt;/ruby&gt;+G_t^&lt;ruby&gt;(2)}+\cdots+G_t&lt;rp&gt;(&lt;/rp&gt;&lt;rt&gt;{(N)&lt;/rt&gt;&lt;rp&gt;)&lt;/rp&gt;&lt;/ruby&gt;}&lt;/p&gt;
所以 MC 的特点是：

**优点：** 用的是一整局真实奖励，不依赖自己对 $V(s_{t+1})$ 的估计，比较“真实”。

**缺点：** 必须等 episode 结束才能更新，游戏很长时学习很慢；而且随机性大，方差较高。

#### TD

我们可以通过TD ：不用等游戏结束，走一步就可以学

当前有一段经验：

&lt;p&gt;\cdots, s_t, a_t, r_t, s_{t+1}, \cdots&lt;/p&gt;
意思是：

```
当前状态是 s_t
采取动作 a_t
得到即时奖励 r_t
进入下一个状态 s_{t+1}
```

TD 方法说：

如果我知道下一个状态的价值 $V^\pi(s_{t+1})$，那么当前状态的价值应该接近：

&lt;p&gt;r_t + V^\pi(s_{t+1})&lt;/p&gt;
&lt;p&gt;&lt;span class=&#34;katex-display&#34;&gt;&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34; display=&#34;block&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mtext&gt;如果加上折扣因子，一般写成：&lt;/mtext&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;如果加上折扣因子，一般写成：
&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord cjk_fallback&#34;&gt;如果加上折扣因子，一般写成：&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;V^\pi(s_t) \approx r_t + \gamma V^\pi(s_{t+1})&lt;/p&gt;



## lecture 12

最早可以从图灵测试说起：如果一个测试者只通过文字和被测试对象交流，最后分不清对面是人还是机器，那么机器就表现出了某种智能。图灵当年举的例子包括写诗、算术、下棋，这和今天 ChatGPT 的体验很像：不是给一个固定输入输出格式，而是用自然语言承接各种任务。

但 GPT 不是凭空出现的。前面几节课讲过，NLP 先有词向量，把词从离散符号变成连续空间里的点；又有 RNN/LSTM，用序列结构处理上下文；再到 Transformer，用 attention 高效捕捉长距离依赖。GPT 的关键不是发明了一个完全陌生的部件，而是把 Transformer、海量数据、next token prediction、规模化训练和后训练对齐组合成了一个统一系统。

### 从填词到接龙

#### BERT 与 GPT 的任务差异

BERT 和 GPT 都建立在 Transformer 上，但训练游戏不同。BERT 更像“填词”：给定左右上下文，让模型猜中间缺掉的词。例如“小明扶了摔倒的老奶奶，他是一个 [MASK] 人”，模型要利用前后信息猜出“好”。这种方式适合理解类任务，比如分类、抽取、阅读理解、句子匹配。

GPT 更像“接龙”：给定前文，让模型继续往后写。例如“小明扶了摔倒的老奶奶，……”，模型只能看已经出现的 token，然后预测下一个 token。看起来这个目标很简单，但它的优势也正在这里：写文章、翻译、问答、总结、代码补全，都可以被转化成“在这段上下文后继续生成合理内容”。

所以 GPT 的应用范式和传统 NLP 很不一样。传统做法通常是为每个任务准备数据，再微调一个专门模型；GPT 则可以把任务写进 prompt，让模型在上下文里临时理解任务。这就是语境学习（In-Context Learning）。zero-shot 是不给例子，只给指令；one-shot 是给一个例子；few-shot 是给少量例子。模型参数没有变化，但模型行为会被 prompt 临时“配置”。

#### Scaling Laws 与涌现能力

GPT-3 是一个重要节点。课件里提到 GPT-3 达到 1750 亿参数，训练成本很高，但它展示了明显的 few-shot 能力。它不一定在所有任务上都完美，但它说明了一件事：当模型规模、数据规模和计算量足够大时，语言模型不再只是能写顺畅句子，而是开始表现出跨任务迁移、简单推理、代码生成、复杂指令跟随等能力。

Scaling Laws 可以理解为大模型时代的经验规律：模型参数、训练数据和计算量一起变大，模型损失通常会下降，任务表现通常会提高。涌现能力（Emergent Ability）则是更有意思的现象：某些能力在小模型上几乎看不到，等模型跨过一定规模后突然明显出现。这里的“突然”不一定是魔法，更像是能力原本很弱，弱到不可用；规模上去以后，能力才进入可观察、可使用的范围。

### 大模型训练：先学语言，再学做人

#### 预训练学到什么

一个可用的 ChatGPT 类模型通常不是只靠预训练得到的。预训练阶段的目标很朴素：给模型大量文本，让它预测下一个 token。这个阶段学到的是语言统计规律、事实知识、代码模式、文本结构，以及一部分隐含推理能力。可以把 base model 理解成一个“读了很多东西、很会续写文本”的模型。

![大模型训练的三个阶段](/assets/图片/ppt9_gpts/training_stages.png)

但是 base model 直接拿来聊天通常不好用。课件里用 LLaMA-2-7b-base 的例子说明：问它 “What is Machine Learning?”，它可能给出百科式定义，然后继续重复或发散。这不是模型完全不会，而是它没有被训练成“听用户问题，然后给出清晰回答”的助手。预训练只学到了文本分布，没有明确学到对话规范。

预训练的数据工程也很重。语料可能来自百科、电子书、新闻、网页、Common Crawl 等，里面会有垃圾文本、广告、乱码、重复内容、敏感内容、网页导航栏和低质量短文本。如果不过滤，模型会把这些噪声也学进去。盘古语料平台的思路是先做规则清洗，再用小模型快速评估数据质量，最后抽样成训练数据。

![盘古语料建设平台](/assets/图片/ppt9_gpts/data_pipeline.png)

#### SFT：从续写模型到助手模型

SFT（Supervised Fine-tuning，监督/指令微调）是 post-training 的第一步。它把数据组织成“用户输入 -&gt; 助手输出”的格式，例如输入是 `USER: 你是谁？ AI:`，输出是“我是……”。这一步让模型学会按照人的指令回答，学会对话格式、任务格式和一些基本行为边界。简单说，预训练让模型“会说话”，SFT 让模型“像助手一样说话”。

SFT 数据不是越多越好。课件里反复强调 “Quality is all you need”。LIMA 的 Less Is More for Alignment 也说明，少量高质量、多样、干净的数据可能比大量低质量数据更有效。低质量 SFT 数据会让模型学到空洞、啰嗦、机械、逻辑混乱甚至不安全的回答风格。

SFT 数据可以来自人工标注，也可以来自知识蒸馏。比如 Alpaca、Vicuna 这类模型，就是让 ChatGPT 之类已经对齐的强模型先回答问题，再用这些回答训练学生模型。这样成本比完全人工标注低很多，但老师模型的偏差、幻觉和语言风格也可能被学生继承。

课件里提到的 ruozhiba（弱智吧）数据很有意思。它的问题看起来荒诞，但实际考察常识和语言陷阱。例如“银行卡在高压锅里煮了一晚上，为什么还是冻结状态”，模型不能把“冻结”理解成物理低温，而要知道这是银行账户状态。这类数据能提升模型处理反常识提问、隐含前提和歧义表达的能力。

还有一种 non-instructional fine-tuning。它不一定构造成明确问答，而是给模型普通句子的前半句，让模型学习续写后半句。它的思路是：很多能力本来就来自语言建模，不是所有后训练数据都要写成“请你做某事”的指令格式。对领域语言、写作风格、自然续写能力，非指令式微调也能发挥作用。

#### RLHF：让模型更符合人类偏好

SFT 能让模型像助手，但开放问题往往没有唯一标准答案。比如同一个问题，哪个回答更有帮助、更安全、更不啰嗦，只能比较偏好。RLHF（Reinforcement Learning from Human Feedback）就是让人类或奖励模型比较多个回答，然后用强化学习把模型往更受偏好的方向推。

PPO 是 RLHF 里常用的算法。普通 policy gradient 有两个主要问题：样本效率低，因为每次策略更新后都要重新采样；更新不稳定，因为步子太大可能让策略突然变坏，后面采到的数据也跟着变差。PPO 的做法是限制新旧策略的差距，通过 KL regularization 和 clip objective 控制每次更新不要太激进，同时用 mini-batch 提高数据利用率。直观理解，PPO 不是让模型大改，而是在当前行为附近稳一点地变好。

#### 训练工程：显存、并行与故障恢复

大模型训练的难点不只是 loss。参数、梯度、优化器状态、activation、反向传播中间结果都要占显存。一个千亿级模型，单卡根本放不下，必须用数据并行、模型并行、流水线并行、优化器并行、重计算、通信融合等技术。

![模型训练中的计算流程和存储开销](/assets/图片/ppt9_gpts/training_memory.png)

课件里的盘古例子说明，真正的大模型训练是算法、数据、系统、硬件和集群调度一起解决的问题。大集群训练几十天，硬件故障、节点错误、网络错误都很正常，所以还需要定期保存 checkpoint、故障检测隔离、资源重调度和快速恢复。模型越大，工程可靠性越重要。

Codex 是预训练和后训练结合的典型例子。微软收购 GitHub 后，OpenAI 在 GPT-3 基础上使用大量代码数据继续训练，得到能根据函数名、注释、自然语言描述补全代码的 Codex。代码也是文本，但比普通语言更强调语法、结构和可执行性，所以代码预训练会明显增强程序生成能力。HumanEval 这类数据集就是用来测试模型能不能写出通过单元测试的代码。

### 对齐之后的问题：遗忘与安全

#### 灾难性遗忘

Post-training 能让模型更符合人的使用习惯，但它也会带来副作用。课件里把它比作给模型“大脑动手术”：目标任务可能变强，但其他能力可能被破坏。这就是灾难性遗忘（Catastrophic Forgetting）。例如一个主要用英文数据预训练的模型，再用中文数据做 post-training，中文能力可能提高，但英文能力、安全拒答能力或其他通用能力可能下降。

![灾难性遗忘示意](/assets/图片/ppt9_gpts/catastrophic_forgetting.png)

这个问题在安全上尤其麻烦。一个已经对齐好的模型，原本遇到危险请求会拒答；但如果后来用某个领域数据继续微调，而数据里没有足够安全样本，模型可能忘掉原来的拒答边界。课件中的例子是，模型原本会拒绝回答如何获取银行密码，微调后却可能开始给出攻击性建议。这里不是模型突然“想作恶”，而是训练目标把它往“尽量回答用户问题”的方向拉，却没有同时保留安全约束。

#### 缓解思路

解决思路之一是 experience replay。人在学新知识时，如果完全不复习旧知识，也会遗忘；模型也类似。训练新任务时混入一小部分旧任务数据，就能显著缓解遗忘。问题是旧数据未必总能拿到，尤其是商业模型、隐私数据或历史训练集不可访问时。

因此可以做 pseudo experience replay：让基础模型或旧模型自己生成旧任务样本，或者把新任务输入改写成旧任务风格，再用这些伪数据维持旧能力。LAMOL 的思路也是类似的：模型不仅学任务，还学会生成任务数据。当旧任务数据不可用时，让模型自己生成近似样本，在后续训练中回放。

LoRA 这类 PEFT 方法也和遗忘有关。全量微调会改动大量参数，目标任务可能学得更充分，但破坏原能力的风险也更大。LoRA 只训练低秩增量，相当于在原模型旁边加一小块可调结构，因此“学得少，也忘得少”。如果目标是低成本适配并尽量保留原模型能力，LoRA 很有价值；但如果需要强烈改变模型能力，它可能不如全量微调。

所以对齐不是一次完成的事情。模型上线后还会遇到新领域、新语言、新政策、新安全风险。每一次继续训练都可能带来遗忘和偏移，因此评测不能只看目标任务有没有变好，还要看原来的通用能力、安全能力、拒答能力和多语言能力有没有下降。

### DeepSeek 与推理模型

#### V3：高效的大模型工程

DeepSeek 这一部分可以分两层看：一层是模型工程，另一层是推理范式。DeepSeek-V3 更偏通用非推理模型，适合规范清楚、输出形式明确的任务；DeepSeek-R1 更偏推理模型，适合路径开放、需要探索的问题。课件里把 V3 和 R1 的差异概括为：V3 的响应更像按规则执行，结果更稳定；R1 会主动探索多条路径，结果更开放，但不确定性也更高。

从架构上看，DeepSeek-V3 的一个重要特点是 MoE。传统 dense model 每个 token 都会经过几乎所有参数，而 MoE 有很多专家，每个 token 只激活其中一部分。课件里提到 671B 模型每个 token 只激活约 37B 参数，这样模型总容量很大，但单次计算量可控。它还引入共享专家和路由专家，既保留通用能力，也让不同 token 可以走不同专家。

另一个特点是 MLA（Multi-Head Latent Attention）。Transformer 推理时 KV cache 很占内存，尤其上下文变长后，缓存压力非常大。MLA 的思路是把 QKV 相关信息压到 latent space 里存储，减少 cache 开销，从而提升长上下文推理效率。MTP（Multi-Token Prediction）则让模型不只预测下一个 token，也尝试预测后面多个 token，帮助训练更有效。

DeepSeek 的工程优化还包括 FP8 量化训练、混合精度、DualPipe、专家并行、流水线并行、数据并行等。FP8 的意义是降低显存和带宽压力，但它也会带来精度风险，所以需要分组量化、提高累加精度、处理 outlier。DualPipe 的目标是减少流水线气泡，让计算和通信尽量重叠。这里可以看到，大模型性能不是单靠算法论文堆出来的，硬件利用率、通信调度、显存管理都很关键。

#### R1：用测试时计算换推理能力

推理模型的核心变化是 test-time compute。普通模型回答问题时，通常直接给答案；推理模型会在测试时花更多 token 做中间思考，比如验证、尝试不同路径、计划步骤。课件里说“深度不够，长度来凑”，意思是：如果模型一次前向的能力有限，可以让它生成更长的思考过程，用更多计算换更好的答案。

![推理模型的基本形态](/assets/图片/ppt9_gpts/reasoning_model.png)

CoT（Chain-of-Thought）是最基本的方法：让模型写出中间推理步骤。Few-shot CoT 是在 prompt 里给带推理过程的例子；zero-shot CoT 则用类似“Let&#39;s think step by step”的提示引导模型展开推理。现在推理模型做的是更长的 Long CoT，不只是两三步解释，而是可能包含检查、反思、换思路、验证答案等过程。

除了让一个答案更长，也可以让模型多试几次。Majority Vote 或 Self-consistency 的做法是同一个问题采样多个推理路径，最后投票选答案。Best-of-N 则是生成多个候选答案，再用 verifier 给分，选最高分的一个。Verifier 本身也可以是语言模型，它不一定生成答案，而是判断哪个答案更可信。

![DeepSeek-R1-Zero 的强化学习思路](/assets/图片/ppt9_gpts/reasoning_rl.png)

推理能力还可以通过知识蒸馏得到。强推理模型生成“问题、推理过程、答案”，小模型学习这些数据，就能继承一部分推理行为。Sky-T1、s1 这类工作都属于用较少高质量推理数据蒸馏能力的方向。

DeepSeek-R1-Zero 更有代表性：它直接从 base model 出发，用强化学习按最终答案正确性给 reward。也就是说，推理过程写得是否像人类不是最重要的，最后答案对才是关键。这会让模型自己探索出一些有用行为，比如反思、验证、重新尝试，课件里称为 Aha Moment。之后的 DeepSeek-R1 又加入少量人工/模型生成的长 CoT 数据做冷启动，再进行 RL，并用更多数据做蒸馏和安全有用性优化。

### 趋势：多模态、智能体与具身智能

#### 模型、算力和领域化

课件后半部分把大模型趋势分成几个方向看。第一是模型本身：开源通用模型快速发展，DeepSeek、LLaMA、Qwen 等模型让大模型能力不再只集中在少数闭源系统里。开源模型的价值不只是“免费可用”，更重要的是方便私有化部署、领域微调、教学研究和系统集成。比如 DeepSeek-R1 可以通过 Ollama、vLLM 等工具部署，本地部署时要考虑显卡显存、模型参数量、量化版本和推理速度。

第二是领域模型。通用大模型会越来越强，但很多行业仍然需要自己的专业模型，因为行业任务有专业术语、业务流程、合规要求和私有数据。课件里举了司法、教育、金融等例子：司法模型要能理解案由、庭审记录、裁判文书；教育模型要能结合教材知识点做问答、出题和学习导航；金融模型要能做知识问答、文本生成、风险分析，还要满足私有化和数据安全要求。也就是说，未来可能不是一个模型解决所有问题，而是通用大模型提供底座，行业模型在底座上加入专业知识和业务约束。

第三是算力。大模型能力提升离不开硬件。课件里提到 GPU 算力持续提升，例如 Blackwell、Rubin 这类架构继续提高推理性能、显存容量和互联带宽；Groq 的 LPU、Google 的 TPU Ironwood、存算一体芯片等也说明，AI 硬件不只是在做更快的 GPU，而是在围绕大模型的训练和推理特点重新设计。训练需要高吞吐和大规模并行，推理则越来越重视低延迟、高并发、长上下文和能效。

所以大模型的发展不是单线条的“模型越来越大”。模型架构、数据质量、后训练方法、硬件算力、部署工具和行业数据会一起决定最终效果。一个模型能不能真正落地，往往取决于它是否能在具体成本、具体延迟、具体安全要求下稳定工作。

#### 多模态：从文字扩展到图像、语音和视频

大模型后续发展不只是文本模型继续变大。一个方向是多模态：把图像、语音、视频、3D 点云等信息也接入模型。这样模型不只是“会说话”，还要能看、能听、能理解时间变化，甚至能生成图片、语音和视频。

课件里提到的联觉（Cheetah）属于图文交错多模态模型。它不只处理一张图片加一个问题，而是能处理复杂的图文混排指令，理解多张图之间的关系。比如用户给几张图片和一段指令，模型要找到它们之间的相似点、差异、时序或语义关联。这比普通 VQA 更接近真实场景，因为真实任务往往不是“看一张图回答一个短问题”。

![联觉多模态大模型](/assets/图片/ppt9_gpts/multimodal_cheetah.png)

Momentor 则面向视频。视频比图像更难，因为它包含时间结构。普通视频语言模型可能只做整体理解，比如“这个视频讲了什么”；但很多任务需要细粒度时间定位，比如用户问“从第几秒开始发生了某个动作”，模型要输出对应片段。Momentor 通过 Temporal Perception Module 和事件序列建模，把精确时间信息注入视觉特征，实现更细粒度的视频问答、片段定位和事件预测。

语音方向也很重要。NaturalSpeech 3 关注高质量语音合成，可以控制语速、韵律、音色。GPT-4o 代表的是更统一的实时语音交互：不再是先语音识别成文字、再让 ChatGPT 回答、最后文字转语音这么简单的流水线，而是更接近端到端地处理声音单位。这样模型可以保留笑声、语气、停顿、情绪等纯文本难以表达的信息。

图像理解和图像生成之间还有一个矛盾：理解任务需要抽象，可能丢掉细节；生成任务需要保留细节，才能还原图像。课件里提到 Auto-Encoding Morph-Tokens，就是试图用不同 token 表示理解所需的抽象语义和生成所需的完整视觉信息，从而缓解理解和生成目标冲突。

#### Agent：让模型从回答者变成调度者

另一个方向是 Agent。大模型如果只输出文本，本质上还是一个聊天系统；如果它能调用工具、规划步骤、执行子任务，它就更像一个智能体。Toolformer、GPT-4 工具调用、Coze 这类平台，都属于这个趋势。工具调用的关键是让模型知道什么时候该自己回答，什么时候该调用搜索、计算器、代码执行器、图像模型、语音模型或外部 API。

![HuggingGPT 智能体流程](/assets/图片/ppt9_gpts/hugginggpt_agent.png)

HuggingGPT 的思路很典型：大模型负责理解用户请求、拆分任务、选择 Hugging Face 上合适的小模型、组织执行顺序，最后再整合结果。比如用户要求“生成一张姿势和参考图相同的女孩读书图片，并用语音描述它”，系统需要先做姿态估计，再做姿态控图生成，再做图像描述，再做文字转语音。大模型在这里不是亲自完成每个感知任务，而是做规划和调度。

再往后是 GUI Agent、推荐系统 Agent 和具身机器人。GUI Agent 把屏幕截图作为输入，把鼠标键盘操作作为动作输出；推荐系统 Agent 可以结合用户画像、长期记忆、短期事件和上下文需求来调度推荐；具身机器人则要把视觉、语言和动作控制连接起来，在真实世界执行任务。Helix 这类 VLA（Vision-Language-Action）模型，以及 Nvidia Cosmos 这类世界模型，都指向这个方向。

#### 最后的思考：认知与感知

早期 AI 更偏认知系统，例如逻辑、程序、搜索、数据库；深度学习时代更偏感知系统，例如图像识别、语音识别、语言建模。现在很多问题来自两者没有真正协调：感知模型很会从数据里学模式，但缺乏常识、可解释性和稳健性；认知系统擅长规则和推理，但不擅长处理复杂真实世界输入。

未来的大模型可能会让大的认知模型控制许多小的感知模型，自动写代码、生成数据、训练模型、调用工具，形成更强的自我扩展能力。这个方向也带来担忧：生成式 AI 可能替代大量文本、代码、客服、设计、分析类工作的初级环节。对学习者来说，关键不只是会不会用某个模型，而是要理解模型背后的数据、训练、对齐、推理和系统能力，这样才知道它能做什么、不能做什么、为什么会错，以及如何把它接入真实任务。

 &lt;h2 id=&#34;lecture-1a&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#lecture-1a&#34;&gt;#&lt;/a&gt; lecture 1a&lt;/h2&gt;
&lt;p&gt;&lt;img loading=&#34;lazy&#34; src=&#34;/assets/%E5%9B%BE%E7%89%87/image-20260709110353991.png&#34; alt=&#34;image-20260709110353991&#34; /&gt;&lt;/p&gt;
&lt;h3 id=&#34;kinds-of-ml&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#kinds-of-ml&#34;&gt;#&lt;/a&gt; kinds of ML&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;supervised learining：监督学习&lt;/li&gt;
&lt;li&gt;无监督学习&lt;/li&gt;
&lt;li&gt;强化学习&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;机器学习系统的组成部分&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#机器学习系统的组成部分&#34;&gt;#&lt;/a&gt; 机器学习系统的组成部分&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;The data that we can learn from.&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Characterized by Size, type, dimensionality, etc.&lt;/li&gt;
&lt;li&gt;&lt;em&gt;garbage in, garbage out&lt;/em&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;A model of how to transform the data.&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;By model, we denote the computational machinery for ingesting data of one type and spitting out predictions of a possibly different type.&lt;/li&gt;
&lt;li&gt;Statistical Models, Deep Neural Networks, etc.&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;An objective function that quantifies how well (or badly) the model is doing.&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;By learning here, we mean improving at some task over time.&lt;/li&gt;
&lt;li&gt;Owing to non-differentiability or other complications, it is common instead to optimize a surrogate objective.&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;An algorithm to adjust the model&#39;s parameters to optimize the objective function.&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;E.g., gradient descent.&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;监督学习&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#监督学习&#34;&gt;#&lt;/a&gt; 监督学习&lt;/h3&gt;
&lt;pre&gt;&lt;code&gt;       Data
         │
         ▼
      Model
         │
         ▼
     Training
         │
         ▼
    Evaluating
         │
         ▼
     Inference
&lt;/code&gt;&lt;/pre&gt;
&lt;h4 id=&#34;数据&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#数据&#34;&gt;#&lt;/a&gt; 数据&lt;/h4&gt;
&lt;p&gt;&lt;img loading=&#34;lazy&#34; src=&#34;/assets/%E5%9B%BE%E7%89%87/image-20260709114327605.png&#34; alt=&#34;image-20260709114327605&#34; /&gt;&lt;/p&gt;
&lt;p&gt;结构化如DB，半结构化如JSON，非结果化比如JPG什么的（不能SELECT）。我们最终把数据存储在数据集中。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;监督学习的数据构成&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Dataset&lt;br /&gt;
│&lt;br /&gt;
├── Example 1&lt;br /&gt;
│      ├── Features&lt;br /&gt;
│      └── Label&lt;br /&gt;
│&lt;br /&gt;
├── Example 2&lt;br /&gt;
│      ├── Features&lt;br /&gt;
│      └── Label&lt;br /&gt;
│&lt;br /&gt;
├── Example 3&lt;br /&gt;
│      ├── Features&lt;br /&gt;
│      └── Label&lt;br /&gt;
│&lt;br /&gt;
└── ...&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Datasets are composed of individual examples, each containing features and a label.
&lt;ul&gt;
&lt;li&gt;You could think of an example as analogous to a single row in a spreadsheet.&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;Features are the values that a supervised model uses to predict the label.&lt;/li&gt;
&lt;li&gt;The label is the &amp;quot;answer,&amp;quot; or the value we want the model to predict.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;e.g. In a rainfall prediction model, the features could include latitude, longitude, temperature, humidity, cloud, coverage, wind direction, and atmospheric pressure. The label would be rainfall amount.&lt;/p&gt;
&lt;h4 id=&#34;模型&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#模型&#34;&gt;#&lt;/a&gt; 模型&lt;/h4&gt;
&lt;p&gt;&amp;lt;img src=&amp;quot;/assets/图片/image-20260709115035774.png&amp;quot; alt=&amp;quot;image-20260709115035774&amp;quot; style=&amp;quot;zoom:50%;&amp;quot; /&amp;gt;&lt;/p&gt;
&lt;h4 id=&#34;训练&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#训练&#34;&gt;#&lt;/a&gt; 训练&lt;/h4&gt;
&lt;p&gt;&amp;lt;img src=&amp;quot;/assets/图片/image-20260709115111542.png&amp;quot; alt=&amp;quot;image-20260709115111542&amp;quot; style=&amp;quot;zoom:50%;&amp;quot; /&amp;gt;&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;都是很基础的概念emmm&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h3 id=&#34;分类和回归问题&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#分类和回归问题&#34;&gt;#&lt;/a&gt; 分类和回归问题&lt;/h3&gt;
&lt;h4 id=&#34;回归和分类&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#回归和分类&#34;&gt;#&lt;/a&gt; 回归和分类&lt;/h4&gt;
&lt;p&gt;&lt;img loading=&#34;lazy&#34; src=&#34;/assets/%E5%9B%BE%E7%89%87/image-20260709115357695.png&#34; alt=&#34;image-20260709115357695&#34; /&gt;&lt;/p&gt;
&lt;p&gt;使用不同的模型的时候，要遵循不同的假设：比如线性模型你要假定数据分布是线性的。&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;模型&lt;/th&gt;
&lt;th&gt;优点&lt;/th&gt;
&lt;th&gt;缺点&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;KNN&lt;/td&gt;
&lt;td&gt;简单，不需要训练复杂模型&lt;/td&gt;
&lt;td&gt;数据量大时预测很慢&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Linear Model&lt;/td&gt;
&lt;td&gt;快、容易解释&lt;/td&gt;
&lt;td&gt;只能表达线性关系&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Decision Tree&lt;/td&gt;
&lt;td&gt;可解释性强，规则清晰&lt;/td&gt;
&lt;td&gt;容易过拟合&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Random Forest&lt;/td&gt;
&lt;td&gt;准确率高，不易过拟合&lt;/td&gt;
&lt;td&gt;不容易解释&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Naive Bayes&lt;/td&gt;
&lt;td&gt;速度快，小数据效果好&lt;/td&gt;
&lt;td&gt;独立性假设通常不成立&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Neural Network&lt;/td&gt;
&lt;td&gt;表达能力极强，可处理复杂数据&lt;/td&gt;
&lt;td&gt;需要大量数据和算力，训练成本高&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;h4 id=&#34;评估&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#评估&#34;&gt;#&lt;/a&gt; 评估&lt;/h4&gt;
&lt;blockquote&gt;
&lt;p&gt;evaluation&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;基本步骤：&lt;/p&gt;
&lt;p&gt;&amp;lt;img src=&amp;quot;/assets/图片/image-20260709120027846.png&amp;quot; alt=&amp;quot;image-20260709120027846&amp;quot; style=&amp;quot;zoom:50%;&amp;quot; /&amp;gt;&lt;/p&gt;
&lt;p&gt;对于回归和分类任务来说：&lt;/p&gt;
&lt;p&gt;&amp;lt;img src=&amp;quot;/assets/图片/image-20260709120055948.png&amp;quot; alt=&amp;quot;image-20260709120055948&amp;quot; style=&amp;quot;zoom:50%;&amp;quot; /&amp;gt;&lt;/p&gt;
&lt;p&gt;左侧这个是均方根误差，是经常使用的一种，对于右侧分类任务，我们使用混淆矩阵（Confusion Matrix）：&lt;/p&gt;
&lt;p&gt;&amp;lt;img src=&amp;quot;/assets/图片/image-20260709120611525.png&amp;quot; alt=&amp;quot;image-20260709120611525&amp;quot; style=&amp;quot;zoom:50%;&amp;quot; /&amp;gt;&lt;/p&gt;
&lt;p&gt;首先，对于yes我们标记1,对于no我们标记0,然后进行如下操作：&lt;/p&gt;
&lt;p&gt;&amp;lt;img src=&amp;quot;/assets/图片/image-20260709120648106.png&amp;quot; alt=&amp;quot;image-20260709120648106&amp;quot; style=&amp;quot;zoom:50%;&amp;quot; /&amp;gt;&lt;/p&gt;
&lt;p&gt;这样操作可以让模型知道自己错在哪里。四个评价指标如下：&lt;/p&gt;
&lt;p&gt;&amp;lt;img src=&amp;quot;/assets/图片/image-20260709120945162.png&amp;quot; alt=&amp;quot;image-20260709120945162&amp;quot; style=&amp;quot;zoom:50%;&amp;quot; /&amp;gt;&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;Accuracy (准确率)&lt;/li&gt;
&lt;/ol&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;公式&lt;/strong&gt;: &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mfrac&gt;&lt;mrow&gt;&lt;mi&gt;T&lt;/mi&gt;&lt;mi&gt;P&lt;/mi&gt;&lt;mo&gt;+&lt;/mo&gt;&lt;mi&gt;T&lt;/mi&gt;&lt;mi&gt;N&lt;/mi&gt;&lt;/mrow&gt;&lt;mrow&gt;&lt;mi&gt;T&lt;/mi&gt;&lt;mi&gt;P&lt;/mi&gt;&lt;mo&gt;+&lt;/mo&gt;&lt;mi&gt;T&lt;/mi&gt;&lt;mi&gt;N&lt;/mi&gt;&lt;mo&gt;+&lt;/mo&gt;&lt;mi&gt;F&lt;/mi&gt;&lt;mi&gt;P&lt;/mi&gt;&lt;mo&gt;+&lt;/mo&gt;&lt;mi&gt;F&lt;/mi&gt;&lt;mi&gt;N&lt;/mi&gt;&lt;/mrow&gt;&lt;/mfrac&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;\frac{TP + TN}{TP + TN + FP + FN}&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1.2757em;vertical-align:-0.4033em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mopen nulldelimiter&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mfrac&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.8723em;&#34;&gt;&lt;span style=&#34;top:-2.655em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34; style=&#34;margin-right:0.13889em;&#34;&gt;TP&lt;/span&gt;&lt;span class=&#34;mbin mtight&#34;&gt;+&lt;/span&gt;&lt;span class=&#34;mord mathnormal mtight&#34; style=&#34;margin-right:0.10903em;&#34;&gt;TN&lt;/span&gt;&lt;span class=&#34;mbin mtight&#34;&gt;+&lt;/span&gt;&lt;span class=&#34;mord mathnormal mtight&#34; style=&#34;margin-right:0.13889em;&#34;&gt;FP&lt;/span&gt;&lt;span class=&#34;mbin mtight&#34;&gt;+&lt;/span&gt;&lt;span class=&#34;mord mathnormal mtight&#34; style=&#34;margin-right:0.10903em;&#34;&gt;FN&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;top:-3.23em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;frac-line&#34; style=&#34;border-bottom-width:0.04em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;top:-3.394em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34; style=&#34;margin-right:0.13889em;&#34;&gt;TP&lt;/span&gt;&lt;span class=&#34;mbin mtight&#34;&gt;+&lt;/span&gt;&lt;span class=&#34;mord mathnormal mtight&#34; style=&#34;margin-right:0.10903em;&#34;&gt;TN&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.4033em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mclose nulldelimiter&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;释义&lt;/strong&gt;: 所有样本中，预测正确的样本所占的比例。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;特点&lt;/strong&gt;: 最直观的指标，但在样本极度不均衡时容易失效。&lt;/li&gt;
&lt;/ul&gt;
&lt;ol start=&#34;2&#34;&gt;
&lt;li&gt;Precision (精确率 / 查准率)&lt;/li&gt;
&lt;/ol&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;公式&lt;/strong&gt;: &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mfrac&gt;&lt;mrow&gt;&lt;mi&gt;T&lt;/mi&gt;&lt;mi&gt;P&lt;/mi&gt;&lt;/mrow&gt;&lt;mrow&gt;&lt;mi&gt;T&lt;/mi&gt;&lt;mi&gt;P&lt;/mi&gt;&lt;mo&gt;+&lt;/mo&gt;&lt;mi&gt;F&lt;/mi&gt;&lt;mi&gt;P&lt;/mi&gt;&lt;/mrow&gt;&lt;/mfrac&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;\frac{TP}{TP + FP}&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1.2757em;vertical-align:-0.4033em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mopen nulldelimiter&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mfrac&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.8723em;&#34;&gt;&lt;span style=&#34;top:-2.655em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34; style=&#34;margin-right:0.13889em;&#34;&gt;TP&lt;/span&gt;&lt;span class=&#34;mbin mtight&#34;&gt;+&lt;/span&gt;&lt;span class=&#34;mord mathnormal mtight&#34; style=&#34;margin-right:0.13889em;&#34;&gt;FP&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;top:-3.23em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;frac-line&#34; style=&#34;border-bottom-width:0.04em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;top:-3.394em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34; style=&#34;margin-right:0.13889em;&#34;&gt;TP&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.4033em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mclose nulldelimiter&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;释义&lt;/strong&gt;: 在所有&lt;strong&gt;预测为正例&lt;/strong&gt;的样本中，真正是正例的比例。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;关注点&lt;/strong&gt;: 减少误报（推准）。侧重于“只要预测为正例，就一定要准”。&lt;/li&gt;
&lt;/ul&gt;
&lt;ol start=&#34;3&#34;&gt;
&lt;li&gt;Recall (召回率 / 查全率)&lt;/li&gt;
&lt;/ol&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;公式&lt;/strong&gt;: &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mfrac&gt;&lt;mrow&gt;&lt;mi&gt;T&lt;/mi&gt;&lt;mi&gt;P&lt;/mi&gt;&lt;/mrow&gt;&lt;mrow&gt;&lt;mi&gt;T&lt;/mi&gt;&lt;mi&gt;P&lt;/mi&gt;&lt;mo&gt;+&lt;/mo&gt;&lt;mi&gt;F&lt;/mi&gt;&lt;mi&gt;N&lt;/mi&gt;&lt;/mrow&gt;&lt;/mfrac&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;\frac{TP}{TP + FN}&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1.2757em;vertical-align:-0.4033em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mopen nulldelimiter&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mfrac&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.8723em;&#34;&gt;&lt;span style=&#34;top:-2.655em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34; style=&#34;margin-right:0.13889em;&#34;&gt;TP&lt;/span&gt;&lt;span class=&#34;mbin mtight&#34;&gt;+&lt;/span&gt;&lt;span class=&#34;mord mathnormal mtight&#34; style=&#34;margin-right:0.10903em;&#34;&gt;FN&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;top:-3.23em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;frac-line&#34; style=&#34;border-bottom-width:0.04em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;top:-3.394em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34; style=&#34;margin-right:0.13889em;&#34;&gt;TP&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.4033em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mclose nulldelimiter&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;释义&lt;/strong&gt;: 在所有&lt;strong&gt;实际为正例&lt;/strong&gt;的样本中，被成功预测出来的比例。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;关注点&lt;/strong&gt;: 减少漏报（找全）。侧重于“把所有真的正例都捞出来”。&lt;/li&gt;
&lt;/ul&gt;
&lt;ol start=&#34;4&#34;&gt;
&lt;li&gt;F1 Score (F1 值)&lt;/li&gt;
&lt;/ol&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;公式&lt;/strong&gt;: &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mn&gt;2&lt;/mn&gt;&lt;mo&gt;⋅&lt;/mo&gt;&lt;mfrac&gt;&lt;mrow&gt;&lt;mi&gt;P&lt;/mi&gt;&lt;mi&gt;r&lt;/mi&gt;&lt;mi&gt;e&lt;/mi&gt;&lt;mi&gt;c&lt;/mi&gt;&lt;mi&gt;i&lt;/mi&gt;&lt;mi&gt;s&lt;/mi&gt;&lt;mi&gt;i&lt;/mi&gt;&lt;mi&gt;o&lt;/mi&gt;&lt;mi&gt;n&lt;/mi&gt;&lt;mo&gt;⋅&lt;/mo&gt;&lt;mi&gt;R&lt;/mi&gt;&lt;mi&gt;e&lt;/mi&gt;&lt;mi&gt;c&lt;/mi&gt;&lt;mi&gt;a&lt;/mi&gt;&lt;mi&gt;l&lt;/mi&gt;&lt;mi&gt;l&lt;/mi&gt;&lt;/mrow&gt;&lt;mrow&gt;&lt;mi&gt;P&lt;/mi&gt;&lt;mi&gt;r&lt;/mi&gt;&lt;mi&gt;e&lt;/mi&gt;&lt;mi&gt;c&lt;/mi&gt;&lt;mi&gt;i&lt;/mi&gt;&lt;mi&gt;s&lt;/mi&gt;&lt;mi&gt;i&lt;/mi&gt;&lt;mi&gt;o&lt;/mi&gt;&lt;mi&gt;n&lt;/mi&gt;&lt;mo&gt;+&lt;/mo&gt;&lt;mi&gt;R&lt;/mi&gt;&lt;mi&gt;e&lt;/mi&gt;&lt;mi&gt;c&lt;/mi&gt;&lt;mi&gt;a&lt;/mi&gt;&lt;mi&gt;l&lt;/mi&gt;&lt;mi&gt;l&lt;/mi&gt;&lt;/mrow&gt;&lt;/mfrac&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;2 \cdot \frac{Precision \cdot Recall}{Precision + Recall}&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6444em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;2&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mbin&#34;&gt;⋅&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1.2834em;vertical-align:-0.4033em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mopen nulldelimiter&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mfrac&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.8801em;&#34;&gt;&lt;span style=&#34;top:-2.655em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34; style=&#34;margin-right:0.13889em;&#34;&gt;P&lt;/span&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;rec&lt;/span&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;i&lt;/span&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;s&lt;/span&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;i&lt;/span&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;o&lt;/span&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;n&lt;/span&gt;&lt;span class=&#34;mbin mtight&#34;&gt;+&lt;/span&gt;&lt;span class=&#34;mord mathnormal mtight&#34; style=&#34;margin-right:0.00773em;&#34;&gt;R&lt;/span&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;ec&lt;/span&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;a&lt;/span&gt;&lt;span class=&#34;mord mathnormal mtight&#34; style=&#34;margin-right:0.01968em;&#34;&gt;ll&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;top:-3.23em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;frac-line&#34; style=&#34;border-bottom-width:0.04em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;top:-3.394em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34; style=&#34;margin-right:0.13889em;&#34;&gt;P&lt;/span&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;rec&lt;/span&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;i&lt;/span&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;s&lt;/span&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;i&lt;/span&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;o&lt;/span&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;n&lt;/span&gt;&lt;span class=&#34;mbin mtight&#34;&gt;⋅&lt;/span&gt;&lt;span class=&#34;mord mathnormal mtight&#34; style=&#34;margin-right:0.00773em;&#34;&gt;R&lt;/span&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;ec&lt;/span&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;a&lt;/span&gt;&lt;span class=&#34;mord mathnormal mtight&#34; style=&#34;margin-right:0.01968em;&#34;&gt;ll&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.4033em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mclose nulldelimiter&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;释义&lt;/strong&gt;: 精确率和召回率的&lt;strong&gt;调和平均数&lt;/strong&gt; (Harmonic Mean)。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;特点&lt;/strong&gt;: 综合考量 Precision 和 Recall，适用于需要平衡两者或两者发生冲突的场景。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;我们使用这几个指标，是因为有的时候准确率会出现问题：&lt;/p&gt;
&lt;p&gt;&amp;lt;img src=&amp;quot;/assets/图片/image-20260709121619736.png&amp;quot; alt=&amp;quot;image-20260709121619736&amp;quot; style=&amp;quot;zoom:50%;&amp;quot; /&amp;gt;&lt;/p&gt;
&lt;p&gt;这个时候就不能只看accuracy了。&lt;/p&gt;
&lt;p&gt;对于多分类任务的指标计算 (Multiclass Evaluation)：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;&lt;strong&gt;拆分 (Convert)&lt;/strong&gt;：采用 One-vs-Rest (OvR) 策略，将每个类别轮流视为正例（其余合并为反例），拆解出 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;C&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;C&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.07153em;&#34;&gt;C&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 个标准的 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mn&gt;2&lt;/mn&gt;&lt;mo&gt;×&lt;/mo&gt;&lt;mn&gt;2&lt;/mn&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;2 \times 2&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.7278em;vertical-align:-0.0833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;2&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mbin&#34;&gt;×&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6444em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;2&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 二分类混淆矩阵。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;平均 (Average)&lt;/strong&gt;：分别计算各矩阵的指标后求平均值（如宏平均 Macro-average 或加权平均 Weighted-average），从而得出全局评估结果。&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;如图：&lt;/p&gt;
&lt;p&gt;&amp;lt;img src=&amp;quot;/assets/图片/image-20260709140848933.png&amp;quot; alt=&amp;quot;image-20260709140848933&amp;quot; style=&amp;quot;zoom:50%;&amp;quot; /&amp;gt;&lt;/p&gt;
&lt;p&gt;最后对三者进行平均，即可得出结果。&lt;/p&gt;
&lt;p&gt;对于平均值的算法有两种：&lt;strong&gt;微平均 (Micro) vs 宏平均 (Macro)&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Micro-averaging（微平均）&lt;/strong&gt;：先累计所有类别的 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;T&lt;/mi&gt;&lt;mi&gt;P&lt;/mi&gt;&lt;mo separator=&#34;true&#34;&gt;,&lt;/mo&gt;&lt;mi&gt;F&lt;/mi&gt;&lt;mi&gt;P&lt;/mi&gt;&lt;mo separator=&#34;true&#34;&gt;,&lt;/mo&gt;&lt;mi&gt;F&lt;/mi&gt;&lt;mi&gt;N&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;TP, FP, FN&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.8778em;vertical-align:-0.1944em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.13889em;&#34;&gt;TP&lt;/span&gt;&lt;span class=&#34;mpunct&#34;&gt;,&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.1667em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.13889em;&#34;&gt;FP&lt;/span&gt;&lt;span class=&#34;mpunct&#34;&gt;,&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.1667em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.10903em;&#34;&gt;FN&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 数量再算指标。它&lt;strong&gt;受大样本类别主导&lt;/strong&gt;，反映的是全局所有样本的整体准确度。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Macro-averaging（宏平均）&lt;/strong&gt;：先算出各类的独立指标，再做算术平均。它&lt;strong&gt;平等对待每个类别&lt;/strong&gt;（不看样本量），更能反映模型在稀有、小样本类别上的分类性能。&lt;/li&gt;
&lt;/ul&gt;
&lt;h4 id=&#34;liner-models&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#liner-models&#34;&gt;#&lt;/a&gt; liner models&lt;/h4&gt;
&lt;p&gt;&lt;strong&gt;线性模型基本设定与假设 (Linear Models Setup)&lt;/strong&gt; ：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;设定&lt;/strong&gt;：每个样本由 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;d&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;d&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6944em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;d&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 维特征向量 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;msub&gt;&lt;mi mathvariant=&#34;bold&#34;&gt;x&lt;/mi&gt;&lt;mi&gt;i&lt;/mi&gt;&lt;/msub&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;\mathbf{x}_i&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.5944em;vertical-align:-0.15em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathbf&#34;&gt;x&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.3117em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:0em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;i&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 和一个目标值 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;msub&gt;&lt;mi&gt;y&lt;/mi&gt;&lt;mi&gt;i&lt;/mi&gt;&lt;/msub&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;y_i&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.625em;vertical-align:-0.1944em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.03588em;&#34;&gt;y&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.3117em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;i&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 组成（例如通过船只的长度、吨位来预测其运行效率）。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;核心假设&lt;/strong&gt;：假定特征与目标值之间存在&lt;strong&gt;线性关系&lt;/strong&gt;。模型通过对特征进行加权求和加上偏置项来输出预测值 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;msub&gt;&lt;mover accent=&#34;true&#34;&gt;&lt;mi&gt;y&lt;/mi&gt;&lt;mo&gt;^&lt;/mo&gt;&lt;/mover&gt;&lt;mi&gt;i&lt;/mi&gt;&lt;/msub&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;\hat{y}_i&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.8889em;vertical-align:-0.1944em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord accent&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.6944em;&#34;&gt;&lt;span style=&#34;top:-3em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.03588em;&#34;&gt;y&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;top:-3em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;accent-body&#34; style=&#34;left:-0.1944em;&#34;&gt;&lt;span class=&#34;mord&#34;&gt;^&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.1944em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.3117em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;i&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;：&lt;/p&gt;
&lt;p&gt;&lt;span class=&#34;katex-display&#34;&gt;&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34; display=&#34;block&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;msub&gt;&lt;mover accent=&#34;true&#34;&gt;&lt;mi&gt;y&lt;/mi&gt;&lt;mo&gt;^&lt;/mo&gt;&lt;/mover&gt;&lt;mi&gt;i&lt;/mi&gt;&lt;/msub&gt;&lt;mo&gt;=&lt;/mo&gt;&lt;mi&gt;f&lt;/mi&gt;&lt;mo stretchy=&#34;false&#34;&gt;(&lt;/mo&gt;&lt;msub&gt;&lt;mi&gt;θ&lt;/mi&gt;&lt;mn&gt;0&lt;/mn&gt;&lt;/msub&gt;&lt;mo&gt;+&lt;/mo&gt;&lt;msub&gt;&lt;mi&gt;θ&lt;/mi&gt;&lt;mn&gt;1&lt;/mn&gt;&lt;/msub&gt;&lt;msub&gt;&lt;mi&gt;x&lt;/mi&gt;&lt;mrow&gt;&lt;mi&gt;i&lt;/mi&gt;&lt;mn&gt;1&lt;/mn&gt;&lt;/mrow&gt;&lt;/msub&gt;&lt;mo&gt;+&lt;/mo&gt;&lt;mo&gt;⋯&lt;/mo&gt;&lt;mo&gt;+&lt;/mo&gt;&lt;msub&gt;&lt;mi&gt;θ&lt;/mi&gt;&lt;mi&gt;d&lt;/mi&gt;&lt;/msub&gt;&lt;msub&gt;&lt;mi&gt;x&lt;/mi&gt;&lt;mrow&gt;&lt;mi&gt;i&lt;/mi&gt;&lt;mi&gt;d&lt;/mi&gt;&lt;/mrow&gt;&lt;/msub&gt;&lt;mo stretchy=&#34;false&#34;&gt;)&lt;/mo&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;\hat{y}_i = f(\theta_0 + \theta_1 x_{i1} + \dots + \theta_d x_{id})
&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.8889em;vertical-align:-0.1944em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord accent&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.6944em;&#34;&gt;&lt;span style=&#34;top:-3em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.03588em;&#34;&gt;y&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;top:-3em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;accent-body&#34; style=&#34;left:-0.1944em;&#34;&gt;&lt;span class=&#34;mord&#34;&gt;^&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.1944em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.3117em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;i&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1em;vertical-align:-0.25em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.10764em;&#34;&gt;f&lt;/span&gt;&lt;span class=&#34;mopen&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.02778em;&#34;&gt;θ&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.3011em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;0&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mbin&#34;&gt;+&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.8444em;vertical-align:-0.15em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.02778em;&#34;&gt;θ&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.3011em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;1&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;x&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.3117em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:0em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;i&lt;/span&gt;&lt;span class=&#34;mord mtight&#34;&gt;1&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mbin&#34;&gt;+&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6667em;vertical-align:-0.0833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;minner&#34;&gt;⋯&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mbin&#34;&gt;+&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1em;vertical-align:-0.25em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.02778em;&#34;&gt;θ&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.3361em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;d&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;x&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.3361em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:0em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;i&lt;/span&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;d&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mclose&#34;&gt;)&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;目标&lt;/strong&gt;：学习出最佳的参数回归系数 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;θ&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;\theta&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6944em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.02778em;&#34;&gt;θ&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;，使得预测值 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;msub&gt;&lt;mover accent=&#34;true&#34;&gt;&lt;mi&gt;y&lt;/mi&gt;&lt;mo&gt;^&lt;/mo&gt;&lt;/mover&gt;&lt;mi&gt;i&lt;/mi&gt;&lt;/msub&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;\hat{y}_i&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.8889em;vertical-align:-0.1944em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord accent&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.6944em;&#34;&gt;&lt;span style=&#34;top:-3em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.03588em;&#34;&gt;y&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;top:-3em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;accent-body&#34; style=&#34;left:-0.1944em;&#34;&gt;&lt;span class=&#34;mord&#34;&gt;^&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.1944em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.3117em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;i&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 尽可能接近真实标签 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;msub&gt;&lt;mi&gt;y&lt;/mi&gt;&lt;mi&gt;i&lt;/mi&gt;&lt;/msub&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;y_i&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.625em;vertical-align:-0.1944em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.03588em;&#34;&gt;y&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.3117em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;i&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;向量化处理：&lt;/p&gt;
&lt;p&gt;&amp;lt;img src=&amp;quot;/assets/图片/image-20260709141902956.png&amp;quot; alt=&amp;quot;image-20260709141902956&amp;quot; style=&amp;quot;zoom:50%;&amp;quot; /&amp;gt;&lt;/p&gt;
&lt;p&gt;转化为张量处理可以使用GPU加快计算。比如TPU是用来深度学习方面的，不再专注于图像领域。&lt;/p&gt;
&lt;h3 id=&#34;线性回归&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#线性回归&#34;&gt;#&lt;/a&gt; 线性回归&lt;/h3&gt;
&lt;p&gt;问题背景就是用脚印的大小估算身高。我们就可以建立一个这样的模型：&lt;/p&gt;
&lt;p&gt;&amp;lt;img src=&amp;quot;/assets/图片/image-20260709144619722.png&amp;quot; alt=&amp;quot;image-20260709144619722&amp;quot; style=&amp;quot;zoom:50%;&amp;quot; /&amp;gt;&lt;/p&gt;
&lt;p&gt;求解最优参数：用损失函数求导为0。&lt;/p&gt;
&lt;p&gt;&amp;lt;img src=&amp;quot;/assets/图片/image-20260709145301496.png&amp;quot; alt=&amp;quot;image-20260709145301496&amp;quot; style=&amp;quot;zoom:50%;&amp;quot; /&amp;gt;&lt;/p&gt;
&lt;h4 id=&#34;梯度下降&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#梯度下降&#34;&gt;#&lt;/a&gt; 梯度下降&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;核心思想&lt;/strong&gt;：一种迭代优化算法。从随机初始位置出发，逆着梯度方向（下山）逐步调整参数 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;θ&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;\theta&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6944em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.02778em;&#34;&gt;θ&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;，直到走到损失函数 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;L&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;L&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;L&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 的最小值处（碗底）。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;学习率 (&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;η&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;\eta&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.625em;vertical-align:-0.1944em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.03588em;&#34;&gt;η&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;)&lt;/strong&gt;：控制每一步跨得有多大（梯度缩放因子）。常用取值范围：&lt;code&gt;0.01&lt;/code&gt; ~ &lt;code&gt;0.0001&lt;/code&gt;。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;算法流程&lt;/strong&gt;：
&lt;ol&gt;
&lt;li&gt;&lt;strong&gt;初始化&lt;/strong&gt;：随机给 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;θ&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;\theta&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6944em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.02778em;&#34;&gt;θ&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 赋值。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;循环迭代&lt;/strong&gt;：
&lt;ul&gt;
&lt;li&gt;计算当前梯度：&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;msub&gt;&lt;mi mathvariant=&#34;normal&#34;&gt;∇&lt;/mi&gt;&lt;mi&gt;θ&lt;/mi&gt;&lt;/msub&gt;&lt;mi&gt;L&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;\nabla_\theta L&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.8333em;vertical-align:-0.15em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord&#34;&gt;∇&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.3361em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:0em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34; style=&#34;margin-right:0.02778em;&#34;&gt;θ&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;L&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;更新参数（向下滑行）：&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;θ&lt;/mi&gt;&lt;mo&gt;←&lt;/mo&gt;&lt;mi&gt;θ&lt;/mi&gt;&lt;mo&gt;−&lt;/mo&gt;&lt;mo stretchy=&#34;false&#34;&gt;(&lt;/mo&gt;&lt;mi&gt;η&lt;/mi&gt;&lt;mo&gt;⋅&lt;/mo&gt;&lt;msub&gt;&lt;mi mathvariant=&#34;normal&#34;&gt;∇&lt;/mi&gt;&lt;mi&gt;θ&lt;/mi&gt;&lt;/msub&gt;&lt;mi&gt;L&lt;/mi&gt;&lt;mo stretchy=&#34;false&#34;&gt;)&lt;/mo&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;\theta \leftarrow \theta - (\eta \cdot \nabla_\theta L)&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6944em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.02778em;&#34;&gt;θ&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;←&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.7778em;vertical-align:-0.0833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.02778em;&#34;&gt;θ&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mbin&#34;&gt;−&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1em;vertical-align:-0.25em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mopen&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.03588em;&#34;&gt;η&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mbin&#34;&gt;⋅&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1em;vertical-align:-0.25em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord&#34;&gt;∇&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.3361em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:0em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34; style=&#34;margin-right:0.02778em;&#34;&gt;θ&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;L&lt;/span&gt;&lt;span class=&#34;mclose&#34;&gt;)&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;终止条件&lt;/strong&gt;：当 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;θ&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;\theta&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6944em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.02778em;&#34;&gt;θ&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; &lt;strong&gt;收敛&lt;/strong&gt;（几乎不再变化）时停止循环，此时的 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;θ&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;\theta&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6944em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.02778em;&#34;&gt;θ&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 即为最优解。&lt;/li&gt;
&lt;/ol&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h4 id=&#34;局限&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#局限&#34;&gt;#&lt;/a&gt; 局限&lt;/h4&gt;
&lt;ol&gt;
&lt;li&gt;&lt;strong&gt;未清洗数据&lt;/strong&gt;：未处理异常值（Outliers），异常值容易对拟合直线产生极大干扰。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;忽略类别特征&lt;/strong&gt;：避开了特征编码（Encoding）步骤，仅使用了连续数值特征。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;未做数据缩放&lt;/strong&gt;：没有进行任何归一化或标准化处理。&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;&lt;strong&gt;核心概念对比&lt;/strong&gt;：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;归一化 (Normalization)&lt;/strong&gt;：将数值缩放到固定区间（通常是 &lt;code&gt;0&lt;/code&gt; ~ &lt;code&gt;1&lt;/code&gt;）。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;标准化 (Standardization)&lt;/strong&gt;：转换数据使其&lt;strong&gt;均值为 0，标准差为 1&lt;/strong&gt;。&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;logistic-regression&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#logistic-regression&#34;&gt;#&lt;/a&gt; Logistic Regression&lt;/h3&gt;
&lt;blockquote&gt;
&lt;p&gt;逻辑回归，主要解决的也是二分类的问题。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;&amp;lt;img src=&amp;quot;/assets/图片/image-20260709151028667.png&amp;quot; alt=&amp;quot;image-20260709151028667&amp;quot; style=&amp;quot;zoom:33%;&amp;quot; /&amp;gt;&lt;/p&gt;
&lt;p&gt;套用了一个Sigmoid函数，把结果都落到0-1区间，来把连续的回归转化为概率，然后小于0.5的归类为class 0，大于0.5的归类为class 1&lt;/p&gt;
&lt;h4 id=&#34;损失计算&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#损失计算&#34;&gt;#&lt;/a&gt; 损失计算&lt;/h4&gt;
&lt;p&gt;在线性回归中我们用均方误差（MSE），而在二分类逻辑回归中，标准的损失函数是&lt;strong&gt;交叉熵损失（Cross-Entropy Loss）&lt;/strong&gt;。&lt;/p&gt;
&lt;p&gt;交叉熵损失函数 (Cross-Entropy Loss)：&lt;/p&gt;
&lt;p&gt;&lt;span class=&#34;katex-display&#34;&gt;&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34; display=&#34;block&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;L&lt;/mi&gt;&lt;mo&gt;=&lt;/mo&gt;&lt;mo&gt;−&lt;/mo&gt;&lt;mo fence=&#34;false&#34; stretchy=&#34;true&#34; minsize=&#34;1.2em&#34; maxsize=&#34;1.2em&#34;&gt;[&lt;/mo&gt;&lt;msub&gt;&lt;mi&gt;y&lt;/mi&gt;&lt;mi&gt;i&lt;/mi&gt;&lt;/msub&gt;&lt;mi&gt;log&lt;/mi&gt;&lt;mo&gt;⁡&lt;/mo&gt;&lt;msub&gt;&lt;mover accent=&#34;true&#34;&gt;&lt;mi&gt;y&lt;/mi&gt;&lt;mo&gt;^&lt;/mo&gt;&lt;/mover&gt;&lt;mi&gt;i&lt;/mi&gt;&lt;/msub&gt;&lt;mo&gt;+&lt;/mo&gt;&lt;mo stretchy=&#34;false&#34;&gt;(&lt;/mo&gt;&lt;mn&gt;1&lt;/mn&gt;&lt;mo&gt;−&lt;/mo&gt;&lt;msub&gt;&lt;mi&gt;y&lt;/mi&gt;&lt;mi&gt;i&lt;/mi&gt;&lt;/msub&gt;&lt;mo stretchy=&#34;false&#34;&gt;)&lt;/mo&gt;&lt;mi&gt;log&lt;/mi&gt;&lt;mo&gt;⁡&lt;/mo&gt;&lt;mo stretchy=&#34;false&#34;&gt;(&lt;/mo&gt;&lt;mn&gt;1&lt;/mn&gt;&lt;mo&gt;−&lt;/mo&gt;&lt;msub&gt;&lt;mover accent=&#34;true&#34;&gt;&lt;mi&gt;y&lt;/mi&gt;&lt;mo&gt;^&lt;/mo&gt;&lt;/mover&gt;&lt;mi&gt;i&lt;/mi&gt;&lt;/msub&gt;&lt;mo stretchy=&#34;false&#34;&gt;)&lt;/mo&gt;&lt;mo fence=&#34;false&#34; stretchy=&#34;true&#34; minsize=&#34;1.2em&#34; maxsize=&#34;1.2em&#34;&gt;]&lt;/mo&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;L = - \big[ y_i \log \hat{y}_i + (1 - y_i) \log (1 - \hat{y}_i) \big]
&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;L&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1.2em;vertical-align:-0.35em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;−&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;delimsizing size1&#34;&gt;[&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.03588em;&#34;&gt;y&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.3117em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;i&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.1667em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mop&#34;&gt;lo&lt;span style=&#34;margin-right:0.01389em;&#34;&gt;g&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.1667em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord accent&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.6944em;&#34;&gt;&lt;span style=&#34;top:-3em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.03588em;&#34;&gt;y&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;top:-3em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;accent-body&#34; style=&#34;left:-0.1944em;&#34;&gt;&lt;span class=&#34;mord&#34;&gt;^&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.1944em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.3117em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;i&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mbin&#34;&gt;+&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1em;vertical-align:-0.25em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mopen&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;1&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mbin&#34;&gt;−&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1em;vertical-align:-0.25em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.03588em;&#34;&gt;y&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.3117em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;i&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mclose&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.1667em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mop&#34;&gt;lo&lt;span style=&#34;margin-right:0.01389em;&#34;&gt;g&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mopen&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;1&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mbin&#34;&gt;−&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1.2em;vertical-align:-0.35em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord accent&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.6944em;&#34;&gt;&lt;span style=&#34;top:-3em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.03588em;&#34;&gt;y&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;top:-3em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;accent-body&#34; style=&#34;left:-0.1944em;&#34;&gt;&lt;span class=&#34;mord&#34;&gt;^&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.1944em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.3117em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;i&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mclose&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;delimsizing size1&#34;&gt;]&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;梯度公式：&lt;/p&gt;
&lt;p&gt;&lt;span class=&#34;katex-display&#34;&gt;&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34; display=&#34;block&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mfrac&gt;&lt;mrow&gt;&lt;mi mathvariant=&#34;normal&#34;&gt;∂&lt;/mi&gt;&lt;mi&gt;L&lt;/mi&gt;&lt;/mrow&gt;&lt;mrow&gt;&lt;mi mathvariant=&#34;normal&#34;&gt;∂&lt;/mi&gt;&lt;mi&gt;θ&lt;/mi&gt;&lt;/mrow&gt;&lt;/mfrac&gt;&lt;mo&gt;=&lt;/mo&gt;&lt;mfrac&gt;&lt;mn&gt;1&lt;/mn&gt;&lt;mi&gt;n&lt;/mi&gt;&lt;/mfrac&gt;&lt;msup&gt;&lt;mi mathvariant=&#34;bold&#34;&gt;X&lt;/mi&gt;&lt;mi&gt;T&lt;/mi&gt;&lt;/msup&gt;&lt;mo stretchy=&#34;false&#34;&gt;(&lt;/mo&gt;&lt;mover accent=&#34;true&#34;&gt;&lt;mi mathvariant=&#34;bold&#34;&gt;y&lt;/mi&gt;&lt;mo&gt;^&lt;/mo&gt;&lt;/mover&gt;&lt;mo&gt;−&lt;/mo&gt;&lt;mi mathvariant=&#34;bold&#34;&gt;y&lt;/mi&gt;&lt;mo stretchy=&#34;false&#34;&gt;)&lt;/mo&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;\frac{\partial L}{\partial \theta} = \frac{1}{n} \mathbf{X}^T (\hat{\mathbf{y}} - \mathbf{y})
&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:2.0574em;vertical-align:-0.686em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mopen nulldelimiter&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mfrac&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:1.3714em;&#34;&gt;&lt;span style=&#34;top:-2.314em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord&#34; style=&#34;margin-right:0.05556em;&#34;&gt;∂&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.02778em;&#34;&gt;θ&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;top:-3.23em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;frac-line&#34; style=&#34;border-bottom-width:0.04em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;top:-3.677em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord&#34; style=&#34;margin-right:0.05556em;&#34;&gt;∂&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;L&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.686em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mclose nulldelimiter&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:2.0074em;vertical-align:-0.686em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mopen nulldelimiter&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mfrac&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:1.3214em;&#34;&gt;&lt;span style=&#34;top:-2.314em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;n&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;top:-3.23em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;frac-line&#34; style=&#34;border-bottom-width:0.04em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;top:-3.677em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord&#34;&gt;1&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.686em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mclose nulldelimiter&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathbf&#34;&gt;X&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.8913em;&#34;&gt;&lt;span style=&#34;top:-3.113em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34; style=&#34;margin-right:0.13889em;&#34;&gt;T&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mopen&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;mord accent&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.7079em;&#34;&gt;&lt;span style=&#34;top:-3em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathbf&#34; style=&#34;margin-right:0.01597em;&#34;&gt;y&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;top:-3.0134em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;accent-body&#34; style=&#34;left:-0.1944em;&#34;&gt;&lt;span class=&#34;mord&#34;&gt;^&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.1944em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mbin&#34;&gt;−&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1em;vertical-align:-0.25em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathbf&#34; style=&#34;margin-right:0.01597em;&#34;&gt;y&lt;/span&gt;&lt;span class=&#34;mclose&#34;&gt;)&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;h3 id=&#34;polynomial-linear-regression&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#polynomial-linear-regression&#34;&gt;#&lt;/a&gt; Polynomial Linear Regression&lt;/h3&gt;
&lt;blockquote&gt;
&lt;p&gt;多项式线性回归&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;利用多项式扩展（如 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;msup&gt;&lt;mi&gt;x&lt;/mi&gt;&lt;mn&gt;2&lt;/mn&gt;&lt;/msup&gt;&lt;mo separator=&#34;true&#34;&gt;,&lt;/mo&gt;&lt;msup&gt;&lt;mi&gt;x&lt;/mi&gt;&lt;mn&gt;3&lt;/mn&gt;&lt;/msup&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;x^2, x^3&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1.0085em;vertical-align:-0.1944em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;x&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.8141em;&#34;&gt;&lt;span style=&#34;top:-3.063em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;2&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mpunct&#34;&gt;,&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.1667em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;x&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.8141em;&#34;&gt;&lt;span style=&#34;top:-3.063em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;3&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;），使线性回归能够拟合非线性曲线。&lt;/p&gt;
&lt;p&gt;&lt;span class=&#34;katex-display&#34;&gt;&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34; display=&#34;block&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;msub&gt;&lt;mover accent=&#34;true&#34;&gt;&lt;mi&gt;y&lt;/mi&gt;&lt;mo&gt;^&lt;/mo&gt;&lt;/mover&gt;&lt;mi&gt;i&lt;/mi&gt;&lt;/msub&gt;&lt;mo&gt;=&lt;/mo&gt;&lt;msub&gt;&lt;mi&gt;θ&lt;/mi&gt;&lt;mn&gt;0&lt;/mn&gt;&lt;/msub&gt;&lt;mo&gt;+&lt;/mo&gt;&lt;msub&gt;&lt;mi&gt;θ&lt;/mi&gt;&lt;mn&gt;1&lt;/mn&gt;&lt;/msub&gt;&lt;msub&gt;&lt;mi&gt;x&lt;/mi&gt;&lt;mi&gt;i&lt;/mi&gt;&lt;/msub&gt;&lt;mo&gt;+&lt;/mo&gt;&lt;msub&gt;&lt;mi&gt;θ&lt;/mi&gt;&lt;mn&gt;2&lt;/mn&gt;&lt;/msub&gt;&lt;msubsup&gt;&lt;mi&gt;x&lt;/mi&gt;&lt;mi&gt;i&lt;/mi&gt;&lt;mn&gt;2&lt;/mn&gt;&lt;/msubsup&gt;&lt;mo&gt;+&lt;/mo&gt;&lt;mo&gt;⋯&lt;/mo&gt;&lt;mo&gt;+&lt;/mo&gt;&lt;msub&gt;&lt;mi&gt;θ&lt;/mi&gt;&lt;mi&gt;p&lt;/mi&gt;&lt;/msub&gt;&lt;msubsup&gt;&lt;mi&gt;x&lt;/mi&gt;&lt;mi&gt;i&lt;/mi&gt;&lt;mi&gt;p&lt;/mi&gt;&lt;/msubsup&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;\hat{y}_i = \theta_0 + \theta_1 x_i + \theta_2 x_i^2 + \dots + \theta_p x_i^p
&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.8889em;vertical-align:-0.1944em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord accent&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.6944em;&#34;&gt;&lt;span style=&#34;top:-3em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.03588em;&#34;&gt;y&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;top:-3em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;accent-body&#34; style=&#34;left:-0.1944em;&#34;&gt;&lt;span class=&#34;mord&#34;&gt;^&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.1944em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.3117em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;i&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.8444em;vertical-align:-0.15em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.02778em;&#34;&gt;θ&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.3011em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;0&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mbin&#34;&gt;+&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.8444em;vertical-align:-0.15em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.02778em;&#34;&gt;θ&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.3011em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;1&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;x&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.3117em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:0em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;i&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mbin&#34;&gt;+&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1.1111em;vertical-align:-0.247em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.02778em;&#34;&gt;θ&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.3011em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;2&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;x&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.8641em;&#34;&gt;&lt;span style=&#34;top:-2.453em;margin-left:0em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;i&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;top:-3.113em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;2&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.247em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mbin&#34;&gt;+&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6667em;vertical-align:-0.0833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;minner&#34;&gt;⋯&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mbin&#34;&gt;+&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1.0684em;vertical-align:-0.2861em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.02778em;&#34;&gt;θ&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.1514em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;p&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.2861em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;x&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.7823em;&#34;&gt;&lt;span style=&#34;top:-2.4231em;margin-left:0em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;i&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;top:-3.1809em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;p&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.2769em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;核心本质&lt;/strong&gt;：&lt;strong&gt;关于参数 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;θ&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;\theta&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6944em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.02778em;&#34;&gt;θ&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 依然是线性的&lt;/strong&gt;。因此它属于线性模型，所有先前的求解算法（正规方程、梯度下降）完全通用。&lt;/p&gt;
&lt;p&gt;&amp;lt;img src=&amp;quot;/assets/图片/image-20260709153430874.png&amp;quot; alt=&amp;quot;image-20260709153430874&amp;quot; style=&amp;quot;zoom:50%;&amp;quot; /&amp;gt;&lt;/p&gt;
&lt;p&gt;当特征是多个的时候，我们可以如下计算：&lt;/p&gt;
&lt;p&gt;&amp;lt;img src=&amp;quot;/assets/图片/image-20260709154043614.png&amp;quot; alt=&amp;quot;image-20260709154043614&amp;quot; style=&amp;quot;zoom:50%;&amp;quot; /&amp;gt;&lt;/p&gt;
&lt;p&gt;但对于这个存在问题：&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;核心公式&lt;/strong&gt;：特征数 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;d&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;d&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6944em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;d&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;、阶数 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;p&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;p&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.625em;vertical-align:-0.1944em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;p&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 时，总参数量为 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;M&lt;/mi&gt;&lt;mo&gt;=&lt;/mo&gt;&lt;mrow&gt;&lt;mo fence=&#34;true&#34;&gt;(&lt;/mo&gt;&lt;mfrac linethickness=&#34;0px&#34;&gt;&lt;mrow&gt;&lt;mi&gt;p&lt;/mi&gt;&lt;mo&gt;+&lt;/mo&gt;&lt;mi&gt;d&lt;/mi&gt;&lt;/mrow&gt;&lt;mi&gt;p&lt;/mi&gt;&lt;/mfrac&gt;&lt;mo fence=&#34;true&#34;&gt;)&lt;/mo&gt;&lt;/mrow&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;M = \binom{p+d}{p}&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.10903em;&#34;&gt;M&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1.4112em;vertical-align:-0.4811em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mopen delimcenter&#34; style=&#34;top:0em;&#34;&gt;&lt;span class=&#34;delimsizing size1&#34;&gt;(&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mfrac&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.9301em;&#34;&gt;&lt;span style=&#34;top:-2.355em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;p&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;top:-3.144em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;p&lt;/span&gt;&lt;span class=&#34;mbin mtight&#34;&gt;+&lt;/span&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;d&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.4811em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mclose delimcenter&#34; style=&#34;top:0em;&#34;&gt;&lt;span class=&#34;delimsizing size1&#34;&gt;)&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;维度灾难&lt;/strong&gt;：&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;d&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;d&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6944em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;d&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 和 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;p&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;p&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.625em;vertical-align:-0.1944em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;p&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 略微增大，参数量呈爆炸式增长。。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;两大死穴&lt;/strong&gt;：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;&lt;strong&gt;过拟合 (Overfitting)&lt;/strong&gt;：参数过多导致模型过分拟合噪声。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;低可解释性 (Low Interpretability)&lt;/strong&gt;：复杂的特征组合使模型变成难以理解的黑盒。&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;&lt;strong&gt;删项困境&lt;/strong&gt;：虽然理论上可以通过手动删项来精简模型，但实际中很难给出合理的数学或业务依据。&lt;/p&gt;
&lt;h3 id=&#34;正则&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#正则&#34;&gt;#&lt;/a&gt; 正则&lt;/h3&gt;
&lt;p&gt;&amp;lt;img src=&amp;quot;/assets/图片/image-20260709154537390.png&amp;quot; alt=&amp;quot;image-20260709154537390&amp;quot; style=&amp;quot;zoom:50%;&amp;quot; /&amp;gt;&lt;/p&gt;
&lt;p&gt;通过惩罚过大的参数 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;θ&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;\theta&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6944em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.02778em;&#34;&gt;θ&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 来防止模型过拟合。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;公式&lt;/strong&gt;：&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;L&lt;/mi&gt;&lt;mo&gt;=&lt;/mo&gt;&lt;mtext&gt;原损失&lt;/mtext&gt;&lt;mo&gt;+&lt;/mo&gt;&lt;mi&gt;λ&lt;/mi&gt;&lt;mo&gt;⋅&lt;/mo&gt;&lt;mtext&gt;惩罚项&lt;/mtext&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;L = \text{原损失} + \lambda \cdot \text{惩罚项}&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;L&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.7667em;vertical-align:-0.0833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord text&#34;&gt;&lt;span class=&#34;mord cjk_fallback&#34;&gt;原损失&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mbin&#34;&gt;+&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6944em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;λ&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mbin&#34;&gt;⋅&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord text&#34;&gt;&lt;span class=&#34;mord cjk_fallback&#34;&gt;惩罚项&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;（&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;λ&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;\lambda&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6944em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;λ&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 决定惩罚强度）。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;分类&lt;/strong&gt;：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;&lt;strong&gt;L2 正则化 (Ridge)&lt;/strong&gt;：加上参数的&lt;strong&gt;平方和&lt;/strong&gt;（&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mo&gt;∑&lt;/mo&gt;&lt;msubsup&gt;&lt;mi&gt;θ&lt;/mi&gt;&lt;mi&gt;i&lt;/mi&gt;&lt;mn&gt;2&lt;/mn&gt;&lt;/msubsup&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;\sum \theta_i^2&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1.0728em;vertical-align:-0.2587em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mop op-symbol small-op&#34; style=&#34;position:relative;top:0em;&#34;&gt;∑&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.1667em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.02778em;&#34;&gt;θ&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.8141em;&#34;&gt;&lt;span style=&#34;top:-2.4413em;margin-left:-0.0278em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;i&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;top:-3.063em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;2&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.2587em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;）。让参数普遍变小，使曲线平滑。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;L1 正则化 (Lasso)&lt;/strong&gt;：加上参数的&lt;strong&gt;绝对值和&lt;/strong&gt;（&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mo&gt;∑&lt;/mo&gt;&lt;mi mathvariant=&#34;normal&#34;&gt;∣&lt;/mi&gt;&lt;msub&gt;&lt;mi&gt;θ&lt;/mi&gt;&lt;mi&gt;i&lt;/mi&gt;&lt;/msub&gt;&lt;mi mathvariant=&#34;normal&#34;&gt;∣&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;\sum |\theta_i|&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1em;vertical-align:-0.25em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mop op-symbol small-op&#34; style=&#34;position:relative;top:0em;&#34;&gt;∑&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.1667em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;∣&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.02778em;&#34;&gt;θ&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.3117em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;i&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;∣&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;）。会把不重要的参数&lt;strong&gt;直接剔除（归零）&lt;/strong&gt;，实现特征自动选择。&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;###训练与评估&lt;/p&gt;
&lt;p&gt;&amp;lt;img src=&amp;quot;/assets/图片/image-20260709154725383.png&amp;quot; alt=&amp;quot;image-20260709154725383&amp;quot; style=&amp;quot;zoom:50%;&amp;quot; /&amp;gt;&lt;/p&gt;
&lt;p&gt;如图，绝对不能使用测试集来调参。&lt;/p&gt;
&lt;p&gt;经典的解决方案：&lt;strong&gt;K折交叉验证（K-Fold Cross Validation）&lt;/strong&gt;。&lt;/p&gt;
&lt;p&gt;&amp;lt;img src=&amp;quot;/assets/图片/image-20260709154928535.png&amp;quot; alt=&amp;quot;image-20260709154928535&amp;quot; style=&amp;quot;zoom:50%;&amp;quot; /&amp;gt;&lt;/p&gt;
&lt;p&gt;即将数据分块，然后使用不同的块来当测试集。这个是用来选择超参数的。根据不同超参数的性能最终决定选择的超参数。&lt;/p&gt;
&lt;h2 id=&#34;lecture-1b&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#lecture-1b&#34;&gt;#&lt;/a&gt; lecture 1b&lt;/h2&gt;
&lt;h3 id=&#34;naive-bayes-classifier&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#naive-bayes-classifier&#34;&gt;#&lt;/a&gt; Naive Bayes Classifier&lt;/h3&gt;
&lt;blockquote&gt;
&lt;p&gt;朴素贝叶斯分类器&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;&lt;strong&gt;定位&lt;/strong&gt;：在文档/文本分类（Document classification）任务中，朴素贝叶斯是一个极度流行且经典的 &lt;strong&gt;Baseline（基准/垫底保障）算法&lt;/strong&gt;。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;特点（优缺点）&lt;/strong&gt;：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;优点&lt;/strong&gt;：模型非常简单、训练和推理速度极快、而且数学可解释性强。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;缺点&lt;/strong&gt;：正因为它太简单，它的准确率通常达不到当今最顶尖（State-of-the-art / SOTA）的水平。工程上通常先拿它跑出一个基础分数，用来给后面更复杂的模型（如神经网络）当对照组。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;一些应用：&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;语种检测 (Language detection)&lt;/strong&gt;：判断一句话是英语、中文、德语还是马来语。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;垃圾邮件检测 (Spam detection)&lt;/strong&gt;：判断邮件是垃圾邮件（Spam）还是正常邮件（Not spam）。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;学科/题材分类 (Subject/genre classification)&lt;/strong&gt;：识别一篇文章属于生物、化学、地理还是心理学。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;作者身份归属 (Authorship attribution)&lt;/strong&gt;：分析文风，预测某匿名文章是谁写的（比如是斯蒂芬·金还是丹·布朗）。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;情感分析 (Sentiment analysis)&lt;/strong&gt;：判断一段评论的态度是积极、消极、中立还是混合。&lt;/p&gt;
&lt;p&gt;比如这里有一个问题背景：&lt;/p&gt;
&lt;p&gt;&amp;lt;img src=&amp;quot;/assets/图片/image-20260709160633034.png&amp;quot; alt=&amp;quot;image-20260709160633034&amp;quot; style=&amp;quot;zoom: 50%;&amp;quot; /&amp;gt;&lt;/p&gt;
&lt;p&gt;那么我们最终算这个概率就行了，谁大把它归类给谁。这个就是一个贝叶斯公式：&lt;/p&gt;
&lt;p&gt;&lt;img loading=&#34;lazy&#34; src=&#34;/assets/%E5%9B%BE%E7%89%87/image-20260709161006952.png&#34; alt=&#34;image-20260709161006952&#34; /&gt;&lt;/p&gt;
&lt;p&gt;对于各个部分如何计算：&lt;/p&gt;
&lt;p&gt;&amp;lt;img src=&amp;quot;/assets/图片/image-20260709161616087.png&amp;quot; alt=&amp;quot;image-20260709161616087&amp;quot; style=&amp;quot;zoom:50%;&amp;quot; /&amp;gt;&lt;/p&gt;
&lt;p&gt;&amp;lt;img src=&amp;quot;/assets/图片/image-20260709161656377.png&amp;quot; alt=&amp;quot;image-20260709161656377&amp;quot; style=&amp;quot;zoom:50%;&amp;quot; /&amp;gt;&lt;/p&gt;
&lt;p&gt;但是对于这个有两个问题，不过他们有对应的解决办法：&lt;/p&gt;
&lt;p&gt;&amp;lt;img src=&amp;quot;/assets/图片/image-20260709161934150.png&amp;quot; alt=&amp;quot;image-20260709161934150&amp;quot; style=&amp;quot;zoom:50%;&amp;quot; /&amp;gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;下溢危机&lt;/strong&gt;：概率连乘导致浮点数太小而溢出，解决方法是&lt;strong&gt;两边取对数（Log）将连乘变连加&lt;/strong&gt;。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;零概危机&lt;/strong&gt;：新词概率为 0 会导致整体一票否决。解决方法是 &lt;strong&gt;Add-k 平滑&lt;/strong&gt;（分子 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mo&gt;+&lt;/mo&gt;&lt;mi&gt;k&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;+k&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.7778em;vertical-align:-0.0833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;+&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.03148em;&#34;&gt;k&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;，分母 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mo&gt;+&lt;/mo&gt;&lt;mi&gt;k&lt;/mi&gt;&lt;mi mathvariant=&#34;normal&#34;&gt;∣&lt;/mi&gt;&lt;mi&gt;V&lt;/mi&gt;&lt;mi mathvariant=&#34;normal&#34;&gt;∣&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;+k|V|&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1em;vertical-align:-0.25em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;+&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.03148em;&#34;&gt;k&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;∣&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.22222em;&#34;&gt;V&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;∣&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;），给没见过的词分配一个极小的保底概率。&lt;/p&gt;
&lt;p&gt;但是这个语料库中出现的概率什么的在语料库中都是定值，所以这并不是一个优化算法。&lt;/p&gt;
&lt;h3 id=&#34;决策树&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#决策树&#34;&gt;#&lt;/a&gt; 决策树&lt;/h3&gt;
&lt;p&gt;&amp;lt;img src=&amp;quot;/assets/图片/image-20260709163023317.png&amp;quot; alt=&amp;quot;image-20260709163023317&amp;quot; style=&amp;quot;zoom:50%;&amp;quot; /&amp;gt;&lt;/p&gt;
&lt;h4 id=&#34;训练decision-tree&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#训练decision-tree&#34;&gt;#&lt;/a&gt; 训练decision tree&lt;/h4&gt;
&lt;p&gt;&amp;lt;img src=&amp;quot;/assets/图片/image-20260709164046569.png&amp;quot; alt=&amp;quot;image-20260709164046569&amp;quot; style=&amp;quot;zoom:50%;&amp;quot; /&amp;gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;msub&gt;&lt;mi&gt;D&lt;/mi&gt;&lt;mn&gt;0&lt;/mn&gt;&lt;/msub&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;D_0&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.8333em;vertical-align:-0.15em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.02778em;&#34;&gt;D&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.3011em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;0&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;：&lt;strong&gt;根节点&lt;/strong&gt;包含的&lt;strong&gt;所有&lt;/strong&gt;原始数据记录（在右边例子中，就是 ID 1~9 的全部 9 条数据）。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;msub&gt;&lt;mi&gt;D&lt;/mi&gt;&lt;mi&gt;t&lt;/mi&gt;&lt;/msub&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;D_t&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.8333em;vertical-align:-0.15em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.02778em;&#34;&gt;D&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.2806em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;t&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;：当前到达某个&lt;strong&gt;特定节点 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;t&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;t&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6151em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;t&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt; 的数据子集。随着树往下长，数据会被越分越少。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;这是一个递归（Recursively）的过程，每到一个节点，计算机就会掏出以下“生存法则”进行判断：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;法则一：什么时候停？（触发叶子节点）&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;条件 1：&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi mathvariant=&#34;normal&#34;&gt;∣&lt;/mi&gt;&lt;msub&gt;&lt;mi&gt;D&lt;/mi&gt;&lt;mi&gt;t&lt;/mi&gt;&lt;/msub&gt;&lt;mi mathvariant=&#34;normal&#34;&gt;∣&lt;/mi&gt;&lt;mo&gt;=&lt;/mo&gt;&lt;mn&gt;1&lt;/mn&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;|D_t| = 1&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1em;vertical-align:-0.25em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;∣&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.02778em;&#34;&gt;D&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.2806em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;t&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;∣&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6444em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;1&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;，即当前节点里&lt;strong&gt;只剩最后 1 条数据&lt;/strong&gt;了，没法再分了。&lt;/li&gt;
&lt;li&gt;条件 2：当前 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;msub&gt;&lt;mi&gt;D&lt;/mi&gt;&lt;mi&gt;t&lt;/mi&gt;&lt;/msub&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;D_t&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.8333em;vertical-align:-0.15em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.02778em;&#34;&gt;D&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.2806em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;t&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 里的&lt;strong&gt;所有记录都属于同一个类别（或相同的值）&lt;/strong&gt;。比如留下来的所有人全都是 &lt;code&gt;Credit Approval = No&lt;/code&gt;，已经彻底“纯净”了。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;结果&lt;/strong&gt;：满足以上任一条件，节点 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;t&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;t&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6151em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;t&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 就会金盆洗手，正式收工成为&lt;strong&gt;叶子节点（leaf node）&lt;/strong&gt;。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;法则二：不停的话怎么分？（选择测试条件）&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;如果数据还很杂乱（既有 Yes 又有 No），那就&lt;strong&gt;选择一个最佳的特征和切分条件（choose test to split）&lt;/strong&gt;，把当前的大数据集 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;msub&gt;&lt;mi&gt;D&lt;/mi&gt;&lt;mi&gt;t&lt;/mi&gt;&lt;/msub&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;D_t&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.8333em;vertical-align:-0.15em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.02778em;&#34;&gt;D&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.2806em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;t&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 强行切分成更小的子集（也就是子树）。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;右图实例演示&lt;/strong&gt;：&lt;/p&gt;
&lt;p&gt;根节点拥有 1~9 号全部数据。模型选择用 &lt;code&gt;Education&lt;/code&gt; 这一列来切一刀：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;学士（Bachelor）分支：分走了 ID 为 &lt;code&gt;2, 5, 7&lt;/code&gt; 的数据。&lt;/li&gt;
&lt;li&gt;硕士/博士（Master, PhD）分支：分走了 ID 为 &lt;code&gt;1, 3, 4, 6, 8, 9&lt;/code&gt; 的数据。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;接下来，对这两个被切出来的小子集，继续重复（递归调用）上述流程，直到大家都变成叶子节点为止。&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h4 id=&#34;寻找最优划分&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#寻找最优划分&#34;&gt;#&lt;/a&gt; 寻找最优划分&lt;/h4&gt;
&lt;p&gt;寻找绝对完美的全局最优决策树是个 &lt;strong&gt;NP-complete 问题&lt;/strong&gt;，大样本下根本算不动。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;工程解法&lt;/strong&gt;：采用&lt;strong&gt;贪心算法&lt;/strong&gt;（只顾眼前最优）。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;评判标准&lt;/strong&gt;：哪一个特征切分后能带来&lt;strong&gt;更低的不纯度（Lower Impurity / 更清晰的标签分离）&lt;/strong&gt;，谁就是当前的最佳特征。&lt;/p&gt;
&lt;p&gt;&amp;lt;img src=&amp;quot;/assets/图片/image-20260709164502290.png&amp;quot; alt=&amp;quot;image-20260709164502290&amp;quot; style=&amp;quot;zoom:50%;&amp;quot; /&amp;gt;&lt;/p&gt;
&lt;p&gt;如图，第二种划分就是更优的。&lt;/p&gt;
&lt;p&gt;那么如何量化不纯度呢，我们这里有两个指标：基尼指数（Gini Index）和信息熵（Entropy）&lt;/p&gt;
&lt;p&gt;节点越纯净，Gini 和 Entropy 越接近 &lt;strong&gt;0&lt;/strong&gt;；反之，数据越杂乱，指标数值越大。&lt;/p&gt;
&lt;p&gt;&amp;lt;img src=&amp;quot;/assets/图片/image-20260709164748012.png&amp;quot; alt=&amp;quot;image-20260709164748012&amp;quot; style=&amp;quot;zoom:50%;&amp;quot; /&amp;gt;&lt;/p&gt;
&lt;p&gt;&amp;lt;img src=&amp;quot;/assets/图片/image-20260709164906776.png&amp;quot; alt=&amp;quot;image-20260709164906776&amp;quot; style=&amp;quot;zoom:33%;&amp;quot; /&amp;gt;&lt;/p&gt;
&lt;p&gt;执行步骤就是寻找最优划分然后划分掉就可以。最终效果：&lt;/p&gt;
&lt;p&gt;&amp;lt;img src=&amp;quot;/assets/图片/image-20260709165014733.png&amp;quot; alt=&amp;quot;image-20260709165014733&amp;quot; style=&amp;quot;zoom: 33%;&amp;quot; /&amp;gt;&lt;/p&gt;
&lt;h4 id=&#34;拟合&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#拟合&#34;&gt;#&lt;/a&gt; 拟合&lt;/h4&gt;
&lt;p&gt;&amp;lt;img src=&amp;quot;/assets/图片/image-20260709165200700.png&amp;quot; alt=&amp;quot;image-20260709165200700&amp;quot; style=&amp;quot;zoom:50%;&amp;quot; /&amp;gt;&lt;/p&gt;
&lt;p&gt;如上是三种拟合效果，第三种显然过拟合了。很可能是树太深导致的。如果深度到达一定的值，就要停止分裂。&lt;/p&gt;
&lt;p&gt;此可以设置一个最小数量。当一个子节点的数量少于这个最小数量的时候，就停止分裂。&lt;/p&gt;
&lt;h3 id=&#34;tree-ensembles&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#tree-ensembles&#34;&gt;#&lt;/a&gt; Tree Ensembles&lt;/h3&gt;
&lt;blockquote&gt;
&lt;p&gt;集成树，即把多棵树集成在一起做决策&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h4 id=&#34;bagging-with-trees&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#bagging-with-trees&#34;&gt;#&lt;/a&gt; Bagging with Trees&lt;/h4&gt;
&lt;p&gt;&lt;strong&gt;Basic Idea&lt;/strong&gt;&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;em&gt;注：Bagging 的应用&lt;strong&gt;不局限于决策树&lt;/strong&gt; (not limited to Decision Trees)。&lt;/em&gt;&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;多模型训练&lt;/strong&gt;：利用不同的训练数据，训练多个基础模型（分类器 Classifier 或 回归器 Regressor）。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;结合预测结果&lt;/strong&gt;：结合每个基础模型的预测结果，来生成最终的预测（如分类任务采用投票法，回归任务采用平均法）。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;核心优势&lt;/strong&gt;：
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;提高准确率&lt;/strong&gt; (Increases accuracy)&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;降低方差&lt;/strong&gt; (Lowers variance) —— 有效防止模型过拟合，提高泛化能力。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;数据来源：自助采样法 (Bootstrap Sampling)&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;核心问题&lt;/strong&gt;：从哪里获取更多不同的训练数据？ &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mo&gt;→&lt;/mo&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;\rightarrow&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.3669em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;→&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; &lt;strong&gt;采用自助采样法 (Bootstrap Sampling)&lt;/strong&gt;。&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;重复采样&lt;/strong&gt;：从单一的原始训练数据集 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;D&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;D&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.02778em;&#34;&gt;D&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 中进行多次&lt;strong&gt;重复抽取&lt;/strong&gt;。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;有放回的均匀抽样&lt;/strong&gt;：
&lt;ul&gt;
&lt;li&gt;自助样本集 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;msub&gt;&lt;mi&gt;D&lt;/mi&gt;&lt;mi&gt;i&lt;/mi&gt;&lt;/msub&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;D_i&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.8333em;vertical-align:-0.15em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.02778em;&#34;&gt;D&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.3117em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;i&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 是从原始数据集 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;D&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;D&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.02778em;&#34;&gt;D&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 中，通过&lt;strong&gt;均匀地 (uniformly)&lt;/strong&gt; 且 &lt;strong&gt;有放回地 (with replacement)&lt;/strong&gt; 采样得到的。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;数据量保持一致&lt;/strong&gt;：每个子集的数据量与原数据集相同，即 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi mathvariant=&#34;normal&#34;&gt;∣&lt;/mi&gt;&lt;msub&gt;&lt;mi&gt;D&lt;/mi&gt;&lt;mi&gt;i&lt;/mi&gt;&lt;/msub&gt;&lt;mi mathvariant=&#34;normal&#34;&gt;∣&lt;/mi&gt;&lt;mo&gt;=&lt;/mo&gt;&lt;mi mathvariant=&#34;normal&#34;&gt;∣&lt;/mi&gt;&lt;mi&gt;D&lt;/mi&gt;&lt;mi mathvariant=&#34;normal&#34;&gt;∣&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;|D_i| = |D|&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1em;vertical-align:-0.25em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;∣&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.02778em;&#34;&gt;D&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.3117em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;i&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;∣&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1em;vertical-align:-0.25em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;∣&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.02778em;&#34;&gt;D&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;∣&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;模型训练&lt;/strong&gt;：在每一个抽样出来的独立自助数据集 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;msub&gt;&lt;mi&gt;D&lt;/mi&gt;&lt;mi&gt;i&lt;/mi&gt;&lt;/msub&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;D_i&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.8333em;vertical-align:-0.15em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.02778em;&#34;&gt;D&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.3117em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;i&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 上，分别训练一个对应的基础模型。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;e.g.在决策中的应用：&lt;/p&gt;
&lt;p&gt;&amp;lt;img src=&amp;quot;/assets/图片/image-20260709223022495.png&amp;quot; alt=&amp;quot;image-20260709223022495&amp;quot; style=&amp;quot;zoom:50%;&amp;quot; /&amp;gt;&lt;/p&gt;
&lt;p&gt;Bagging 机制与局限性&lt;/p&gt;
&lt;p&gt;原始数据 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mover&gt;&lt;mo stretchy=&#34;true&#34; minsize=&#34;3.0em&#34;&gt;→&lt;/mo&gt;&lt;mpadded width=&#34;+0.6em&#34; lspace=&#34;0.3em&#34;&gt;&lt;mtext&gt;有放回抽样&lt;/mtext&gt;&lt;/mpadded&gt;&lt;/mover&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;\xrightarrow{\text{有放回抽样}}&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1.1113em;vertical-align:-0.011em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel x-arrow&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:1.1003em;&#34;&gt;&lt;span style=&#34;top:-3.322em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight x-arrow-pad&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;&lt;span class=&#34;mord text mtight&#34;&gt;&lt;span class=&#34;mord cjk_fallback mtight&#34;&gt;有放回抽样&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;svg-align&#34; style=&#34;top:-2.689em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;hide-tail&#34; style=&#34;height:0.522em;min-width:1.469em;&#34;&gt;&lt;svg xmlns=&#34;http://www.w3.org/2000/svg&#34; width=&#34;400em&#34; height=&#34;0.522em&#34; viewBox=&#34;0 0 400000 522&#34; preserveAspectRatio=&#34;xMaxYMin slice&#34;&gt;&lt;path d=&#34;M0 241v40h399891c-47.3 35.3-84 78-110 128
