&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#A0ADA0;--shiki-dark:#758575DD&#34;&gt;            // 交换 arr[i] 和 arr[j]&lt;/span&gt;&lt;/span&gt;
